window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s3-325","number":325,"surah":3,"verses":[98],"references":[{"surah":3,"verses":[98]}],"verseLabel":"آل عمران: 98","question":"لماذا اختير ﴿شهيد﴾ هنا لا ﴿عليم﴾؟","answer":"الشهادة علم مع حضور وإقامة حجة، وهي أنسب بمقام محاكمة أعمال أهل الكتاب وتوبيخهم؛ فلا يقتصر المعنى على مجرد الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص494–497، تحت «دلالة صيغة المبالغة في ﴿شهيد على ما تعملون﴾».","url":""}]},{"id":"s3-326","number":326,"surah":3,"verses":[99],"references":[{"surah":3,"verses":[99]}],"verseLabel":"آل عمران: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تصدون عن سبيل الله من آمن﴾ فجعل الدين سبيلًا؟","answer":"شُبه الدين والأدلة الموصلة إليه بطريق مستقيم يبلغ سالكه رضوان الله، وشُبه الصادون بقطاع الطريق الذين يقفون عقبة أمام طالب الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص498، تحت «استعارة السبيل للأدلة الموصلة إلى دين الإسلام».","url":""}]},{"id":"s3-327","number":327,"surah":3,"verses":[99],"references":[{"surah":3,"verses":[99]}],"verseLabel":"آل عمران: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿تبغونها عوجًا﴾، وكيف يُطلب الاعوجاج للطريق؟","answer":"أعيد الضمير إلى سبيل الله، واستعمل العوج المعنوي للدين؛ أي تريدون بتحريفكم وصدكم أن تظهروا السبيل المستقيمة ملتوية حتى لا يتبعها أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص499، تحت «بلاغة الاستخدام في ﴿عن سبيل الله﴾ و﴿تبغونها عوجًا﴾».","url":""}]},{"id":"s3-328","number":328,"surah":3,"verses":[99],"references":[{"surah":3,"verses":[99]}],"verseLabel":"آل عمران: 99","question":"لماذا جاء ﴿وأنتم شهداء﴾ هنا، وجاء في آية 70 ﴿وأنتم تشهدون﴾؟","answer":"قيل هنا ﴿شهداء﴾ لإثبات رسوخ وصف الشهادة فيهم ومقابلته بشهادة الله السابقة، فهم عارفون بأن الدين حق؛ أما ﴿تشهدون﴾ في آية 70 فالفعل أنسب بالشهادة الواقعة على آيات الله المعينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص499–500، تحت «دلالة الجملة الحالية: ﴿وأنتم شهداء﴾».","url":""}]},{"id":"s3-329","number":329,"surah":3,"verses":[99],"references":[{"surah":3,"verses":[99]}],"verseLabel":"آل عمران: 99","question":"لماذا ختم بـ﴿وما الله بغافل عما تعملون﴾ بدل ﴿والله شهيد﴾؟","answer":"ختم بنفي الغفلة ليناسب مكرهم وصدهم الخفي والمعلن، وليهددهم بأن شيئًا منه لا يفوته؛ ونفي الغفلة أبلغ هنا لأن الشاهد من البشر قد يشهد ثم يغفل، والله منزه عن ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص500، تحت «بلاغة ختم الآية بقوله تعالى: ﴿وما الله بغافل عما تعملون﴾».","url":""}]},{"id":"s3-330","number":330,"surah":3,"verses":[100],"references":[{"surah":3,"verses":[100]}],"verseLabel":"آل عمران: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تطيعوا فريقًا من الذين أوتوا الكتاب﴾ ولم يعمم أهل الكتاب؟","answer":"خُص فريق لأن الفتنة صدرت من طائفة، وللتنبيه إلى أن طاعة القليل منهم قد ترد المؤمنين إلى الكفر، فكيف بطاعة الأكثر؛ وفي اللفظ تحذير من التفرق الذي تدعو إليه الفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص504–505، تحت «فائدة تخصيص التحذير من طاعة فريق من أهل الكتاب».","url":""}]},{"id":"s3-331","number":331,"surah":3,"verses":[100],"references":[{"surah":3,"verses":[100]}],"verseLabel":"آل عمران: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿أوتوا الكتاب﴾ لا ﴿آتيناهم الكتاب﴾؟","answer":"جاء ﴿أوتوا الكتاب﴾ لأن السياق يذم فريقًا يريد رد المؤمنين عن إيمانهم؛ ومن نسق القرآن أن يبني الإيتاء للمجهول في مقام الذم، بينما يقول ﴿آتيناهم الكتاب﴾ في مقام المدح فيسند فضل الإيتاء إلى نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص694، تحت «سرّ العدول عن (آتيناهم) إلى ﴿أوتوا﴾».","url":""}]},{"id":"s3-332","number":332,"surah":3,"verses":[100],"references":[{"surah":3,"verses":[100]}],"verseLabel":"آل عمران: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿يردوكم بعد إيمانكم كافرين﴾، فعبّر عن الكفر بالرد إلى الوراء؟","answer":"صُوّر إرجاعهم إلى الكفر ردًّا إلى الوراء؛ لأنهم ينتقلون من الإيمان الذي بلغوه إلى حالتهم السابقة، ففيه إبراز فداحة الانتكاس بعد الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص505، تحت «بلاغة الاستعارة في قوله: ﴿يردوكم بعد إيمانكم كافرين﴾».","url":""}]},{"id":"s3-334","number":334,"surah":3,"verses":[101],"references":[{"surah":3,"verses":[101]}],"verseLabel":"آل عمران: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وكيف تكفرون وأنتم تتلى عليكم آيات الله وفيكم رسوله﴾؟","answer":"الاستفهام يستبعد الكفر مع اجتماع حجتين حاضرتين: الوحي المتلو والرسول المبيّن؛ فليس طريق العصمة غائبًا عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص508–510، تحت «الاستفهام والجملة الحالية وأثرهما في تجلية المعنى».","url":""}]},{"id":"s3-336","number":336,"surah":3,"verses":[101],"references":[{"surah":3,"verses":[101]}],"verseLabel":"آل عمران: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يعتصم بالله﴾، وكيف يكون الاعتصام بالله؟","answer":"الاعتصام بالله لزوم هديه والالتجاء إلى حفظه كمن يتمسك بملجأ يمنعه السقوط؛ فالصورة تجمع الأخذ بالوحي والثقة بالناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص511–514، تحت «الاعتصام والتمسك».","url":""}]},{"id":"s3-337","number":337,"surah":3,"verses":[101],"references":[{"surah":3,"verses":[101]}],"verseLabel":"آل عمران: 101","question":"لماذا جاء جواب الشرط ﴿فقد هدي إلى صراط مستقيم﴾ بالبناء للمجهول؟","answer":"بني ﴿هدي﴾ للمجهول لأن الهادي معلوم من السياق وهو الله، ولتوجيه العناية إلى تحقق الهداية نفسها جزاءً للاعتصام.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص510–511، تحت «الشرط والتحقيق والتنوين والاستعارة وأثر ذلك في توضيح المعنى».","url":""}]},{"id":"s3-338","number":338,"surah":3,"verses":[102],"references":[{"surah":3,"verses":[102]}],"verseLabel":"آل عمران: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿اتقوا الله حق تقاته﴾، وما سر إضافة التقوى إلى حقها؟","answer":"﴿حَقَّ تُقَاتِهِ﴾ مصدر مؤكد يطلب تقوى تليق بحق الله: طاعته وذكره وشكره بحسب الاستطاعة، لا تقوى اسمية أو ناقصة متعمدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص514–515، تحت «النداء والأمر وأثرهما في توضيح المعنى».","url":""}]},{"id":"s3-339","number":339,"surah":3,"verses":[102],"references":[{"surah":3,"verses":[102]}],"verseLabel":"آل عمران: 102","question":"لماذا أتبع الأمر بالتقوى بقوله ﴿ولا تموتن إلا وأنتم مسلمون﴾؟","answer":"النهي ليس عن الموت الذي لا يملكه الإنسان، بل عن ملازمة كل حال قد يفجؤه فيها الموت؛ أي اثبتوا على الإسلام حتى النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص515، تحت «المستثنى، والمجاز، والجملة الحالية، وأثر ذلك في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-340","number":340,"surah":3,"verses":[102],"references":[{"surah":3,"verses":[102]}],"verseLabel":"آل عمران: 102","question":"كيف يُنهى الإنسان عن الموت على غير الإسلام والموت ليس باختياره؟","answer":"النهي متجه إلى الحال التي يملكها الإنسان قبل الموت: الزموا الإسلام دائمًا حتى إذا جاء الموت وجدكم عليه؛ فدوام السبب في الاختيار وإن لم يكن وقت الموت فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص515، تحت «المستثنى، والمجاز، والجملة الحالية، وأثر ذلك في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-341","number":341,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿واعتصموا بحبل الله جميعًا﴾، وما صورة الحبل؟","answer":"حبل الله استعارة لما يصل العباد به ويعصمهم من الضلال، من قرآن وعهد ودين؛ وصورة التمسك بحبل واحد تجمع النجاة والوحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص519، تحت «الاستعارة وأثرها في إثراء المعنى».","url":""}]},{"id":"s3-342","number":342,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿جميعًا﴾ بعد واو الجماعة في ﴿اعتصموا﴾؟","answer":"زيدت ﴿جميعًا﴾ لتوجب أن يقع الاعتصام من الأمة مجتمعةً على حبل واحد، لا أن يتمسك كل فرد بمعزل مع استمرار التفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص519، تحت «الاستعارة وأثرها في إثراء المعنى».","url":""}]},{"id":"s3-343","number":343,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"لماذا قابل الاعتصام بقوله ﴿ولا تفرقوا﴾ ولم يقل: واتحدوا؟","answer":"الأمر بالاعتصام يبين الأصل الإيجابي الجامع، والنهي عن التفرق يسد ضده وطرقه؛ فليس المطلوب اتحادًا على أي شيء بل اجتماع على حبل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص519–520، تحت «الاستعارة وأثرها في إثراء المعنى».","url":""}]},{"id":"s3-344","number":344,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"لماذا ذُكرت نعمة الله في تحويل الأعداء إلى إخوان؟","answer":"ذُكرت حال عداوتهم السابقة ليعرفوا عظم نعمة الله بالإسلام؛ فقد نقلهم من التباغض والتفرق إلى أخوة مؤتلفة، فيلزمون سبب اجتماعهم ولا يعودون إلى الفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص520–521، تحت «وجوه الإعراب، وأثرها في جلاء المعنى وإثرائه».","url":""}]},{"id":"s3-345","number":345,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فألف بين قلوبكم﴾، دون أن يقال: فألف بينكم؟","answer":"خص القلوب لأنها موضع العداوة والمحبة؛ فالتأليف الإلهي أصلح باطنهم حتى نشأت الأخوة، ولم يكن مجرد جمع للأبدان في ظاهر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص521–523، تحت «الاستعارة والإشارة وأثرهما في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-346","number":346,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فأصبحتم بنعمته إخوانًا﴾ مع أن التحول لم يقع في صباح واحد؟","answer":"ليست الإشارة إلى صباح مخصوص؛ فـ﴿أصبحتم﴾ هنا بمعنى صرتم ودخلتم بنعمة الله في حال الأخوة بعد العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص521، تحت «الاستعارة، والإشارة، وأثرهما في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-347","number":347,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"لماذا صوّر حالهم قبل الإسلام بأنهم ﴿على شفا حفرة من النار﴾؟","answer":"يصوّر حالهم قبل الإسلام واقفين على حافة هلاك لا يفصلهم عنه إلا خطوة، فتصير نعمة الإنقاذ مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص524، تحت «شفا وحرف».","url":""}]},{"id":"s3-348","number":348,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]}],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنقذكم منها﴾، دون أن يقال: فأبعدكم عنها؟","answer":"اختير ﴿فأنقذكم﴾ لأنهم كانوا مشرفين على السقوط في الهلاك، فالنعمة تخليص من مهلكة وشيكة، وهو أبلغ من مجرد الإبعاد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص524–527، تحت «(أنقذكم) و(خلّصكم) و(نجّاكم)».","url":""}]},{"id":"s3-350","number":350,"surah":3,"verses":[103],"references":[{"surah":3,"verses":[103]},{"surah":22,"verses":[78]}],"verseLabel":"آل عمران: 103؛ الحج: 78","question":"ما الفرق بين ﴿واعتصموا بحبل الله جميعًا﴾ في آل عمران و﴿واعتصموا بالله﴾ في الحج؟","answer":"الاعتصام بالله لجوء مباشر إلى الحافظ والناصر وهو الأعم، أما الاعتصام بحبل الله فتصوير للوسيلة الجامعة من وحي وعهد وجماعة؛ فالأول يبرز الملجأ، والثاني يبرز سبب الوحدة الموصل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص392–393، تحت «الفرق بين الاعتصام بالله والاعتصام بحبل الله».","url":""}]},{"id":"s3-351","number":351,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتكن منكم أمة﴾، وهل المطلوب بعض الأمة أم جميعها؟","answer":"الأمر متوجه إلى الأمة، لكن مباشرة الدعوة والأمر والنهي فرض كفاية يقوم به المؤهلون؛ فإذا أداه بعضهم على الوجه المطلوب سقط الإثم عن الباقين، وإلا أثم القادرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص528–529، تحت «قوله تعالى: ﴿ولتكن منكم أمة يدعون﴾، و﴿ولتكن﴾ فيها وجهان».","url":""}]},{"id":"s3-352","number":352,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"لماذا قدّم الدعوة إلى الخير على الأمر بالمعروف والنهي عن المنكر؟","answer":"الدعوة إلى الخير أصل إيجابي جامع، ثم فُصلت حراسة المجتمع بإقامة المعروف ومنع المنكر؛ فانتقل من البناء العام إلى وظيفتيه العمليتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص529–530، تحت «عطف الخاص على العام، وحذف المفعول، والإشارة، والقصر، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-353","number":353,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"لماذا عرّف ﴿الخير﴾ و﴿المعروف﴾ و﴿المنكر﴾؟","answer":"عُرّفت الألفاظ للدلالة على المعاني المعلومة المقررة في ميزان الشرع: الخير الجامع، وما عُرف حسنه، وما عُرف إنكاره، لا على أفراد مبهمة يختارها الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص529–530، تحت «عطف الخاص على العام، وحذف المفعول، والإشارة، والقصر، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-354","number":354,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"لماذا حصر الفلاح في قوله ﴿وأولئك هم المفلحون﴾؟","answer":"اجتمع اسم الإشارة وضمير الفصل وتعريف ﴿المفلحون﴾ لقصر الفلاح الكامل على هذه الجماعة باعتبار قيامها بالدعوة والأمر والنهي، مع تعظيم شأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص529–530، تحت «عطف الخاص على العام، وحذف المفعول، والإشارة، والقصر، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-355","number":355,"surah":3,"verses":[105],"references":[{"surah":3,"verses":[105]}],"verseLabel":"آل عمران: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكونوا كالذين تفرقوا واختلفوا﴾، وما الفرق بين التفرق والاختلاف؟","answer":"الاختلاف هنا اتخاذ كل فريق قولًا يناقض الآخر في أصول الحق، وهذا يفضي إلى تفرق الجماعة؛ فجمع بين فساد الاعتقاد ونتيجته الاجتماعية، وقدم التفرق لأنه العاقبة الظاهرة المحذر منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص533–534، تحت «النهي، والصلة، والتأكيد، والقصر، وأثرها جميعها في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-356","number":356,"surah":3,"verses":[105],"references":[{"surah":3,"verses":[105]}],"verseLabel":"آل عمران: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما جاءهم البينات﴾؟","answer":"قُيد تفرقهم بما بعد مجيء البينات لأن الدلائل الواضحة كانت كفيلة بجمعهم على الحق؛ فاختلافهم بعدها عناد بعد قيام الحجة لا خطأ ناشئًا عن خفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص535، تحت «البينات والدلائل».","url":""}]},{"id":"s3-357","number":357,"surah":3,"verses":[105],"references":[{"surah":3,"verses":[105]}],"verseLabel":"آل عمران: 105","question":"لماذا وصف العذاب هنا بـ﴿عظيم﴾ لا ﴿أليم﴾ أو ﴿شديد﴾؟","answer":"وصف بالعظيم لتضخيم قدر العذاب وشموله، بما يناسب عظم الجناية: تفرقهم واختلافهم بعد قيام البينات؛ أما ﴿أليم﴾ فيركز الألم و﴿شديد﴾ القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص556–557، تحت «(أليم) و(شديد) و(عظيم)».","url":""}]},{"id":"s3-358","number":358,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿يوم تبيض وجوه وتسود وجوه﴾، وما سر تحويل المعنى إلى لون الوجه؟","answer":"يظهر أثر المصير على أشرف ما يواجه به الإنسان، فيكون البياض علامة النعيم والسواد علامة الخزي؛ ويجوز أن يكونا حقيقيين مع دلالتهما على السرور والكآبة، وهو الأصل ما لم يصرفه دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537–539، تحت «النشر، والاستفهام، والمجاز، وأثر ذلك في تجلية المعنى».","url":""}]},{"id":"s3-359","number":359,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"لماذا قدّم بياض الوجوه على سوادها؟","answer":"قدم البياض في الإجمال تشريفًا لأهل النعيم وإظهارًا لسبق الرحمة، ثم بدأ في التفصيل بأصحاب الوجوه السوداء لتعجيل توبيخهم، وختم بالمؤمنين ليكون الختام بالرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537، تحت «النشر، والاستفهام، والمجاز، وأثر ذلك في تجلية المعنى».","url":""}]},{"id":"s3-360","number":360,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"لماذا نُكرت ﴿وجوه﴾ في الموضعين؟","answer":"يفيد التنكير كثرة الوجوه أو عموم الفريقين، ويحتمل تفريقًا مناسبًا للمصير: تعظيم الوجوه المبيضة وتحقير الوجوه المسودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537، تحت «بلاغة تنكير ﴿وجوه﴾».","url":""}]},{"id":"s3-361","number":361,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير بقوله تعالى: لأصحاب الوجوه السوداء ﴿أكفرتم بعد إيمانكم﴾ في صورة سؤال؟","answer":"صيغ توبيخهم سؤالًا ليواجهوا فداحة انتقالهم من الإيمان إلى الكفر، فيجمع التعجيب من حالهم والتقريع عليها؛ ويجوز حمله على الاستفهام الإنكاري التوبيخي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص537–539، تحت «النشر، والاستفهام، والمجاز، وأثر ذلك في تجلية المعنى».","url":""}]},{"id":"s3-362","number":362,"surah":3,"verses":[106],"references":[{"surah":3,"verses":[106]}],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿فذوقوا العذاب﴾، وهل العذاب يُذاق؟","answer":"الذوق إحساس مباشر لا واسطة فيه، فاستعير لمباشرة العذاب ومعاناته؛ وفي الأمر ﴿فَذُوقُوا﴾ توبيخ يربط الجزاء بالكفر بعد الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص539–542، تحت «الذوق والإحساس».","url":""}]},{"id":"s3-363","number":363,"surah":3,"verses":[107],"references":[{"surah":3,"verses":[107]}],"verseLabel":"آل عمران: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿ففي رحمة الله هم فيها خالدون﴾ فجعل الرحمة مكانًا؟","answer":"عبر عن الجنة برحمة الله لأنها أجلى آثار رحمته، وجعلهم «فيها» لتصوير إحاطة النعيم بهم واستقرارهم داخله خالدين، لا نيلهم أثرًا عابرًا من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص542–543، تحت «تفصيل ما أُجمل، والصلة، وتقديم ما حقه التأخير، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-364","number":364,"surah":3,"verses":[107],"references":[{"surah":3,"verses":[107]}],"verseLabel":"آل عمران: 107","question":"لماذا كرر الضمير في ﴿هم فيها خالدون﴾؟","answer":"أبرز الضمير ﴿هم﴾ لتأكيد اختصاص هؤلاء بالخبر واستئناف بيان مصيرهم، ومع تقديم ﴿فيها﴾ يثبت أنهم فيها خالدون لا يظعنون ولا يموتون.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص543–545، تحت «الموقع البياني لقوله: ﴿هم فيها خالدون﴾».","url":""}]},{"id":"s3-365","number":365,"surah":3,"verses":[108],"references":[{"surah":3,"verses":[108]}],"verseLabel":"آل عمران: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك آيات الله نتلوها عليك بالحق﴾ بالإشارة إلى البعيد؟","answer":"أشير إليها بـ﴿تلك﴾ تعظيمًا لبعد منزلتها وعلو شأنها؛ فهي آيات الله المتضمنة الحكم الحق في مصير الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص545–546، تحت «الإشارة، ووجوه الإعراب، والتعريض، وأثر ذلك كله في تجلية المعنى وإثرائه».","url":""}]},{"id":"s3-366","number":366,"surah":3,"verses":[108],"references":[{"surah":3,"verses":[108]}],"verseLabel":"آل عمران: 108","question":"لماذا نفى إرادة الظلم عن الله بقوله ﴿وما الله يريد ظلمًا للعالمين﴾؟","answer":"ذُيل خبر الجزاء بنفي إرادة أي ظلم أصلًا، ليقرر أن الثواب والعقاب حق وعدل؛ فنفي الإرادة أبلغ، والمضارع للاستمرار، والتنكير ينفي جنس الظلم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص546–547، تحت «الدلالات البلاغية في قوله: ﴿وما الله يريد ظلمًا للعالمين﴾».","url":""}]},{"id":"s3-367","number":367,"surah":3,"verses":[108],"references":[{"surah":3,"verses":[108]}],"verseLabel":"آل عمران: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿للعالمين﴾ لا: لأحد؟","answer":"قال ﴿للعالمين﴾ ليستغرق جميع الخلق؛ فلا تتعلق إرادته بظلم فرد منهم في أي وقت، وهو الغني المالك لهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص546–547، تحت «الدلالات البلاغية في قوله: ﴿وما الله يريد ظلمًا للعالمين﴾».","url":""}]},{"id":"s3-368","number":368,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾ وكرر الموصول؟","answer":"كرر ﴿ما﴾ لتأكيد شمول الملك لكل من المجالين على الاجتماع والانفراد، ولا سيما الأرض التي قد يتوهم الناس بسبب تصرفهم فيها أنهم يملكون منها شيئًا استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص552–553، تحت «نكتة تكرير ﴿ما﴾».","url":""}]},{"id":"s3-370","number":370,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"لماذا ختم بـ﴿وإلى الله ترجع الأمور﴾ ولم يقل: يرجع الناس؟","answer":"اختيرت ﴿الأمور﴾ لأنها أعم من الناس؛ فذوات الخلق وأحوالهم وشؤونهم ومصائرهم كلها تنتهي إلى الله، وفي ذلك تقرير لملكه وتعريض بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص555، تحت «دلالة (الـ) في ﴿الأمور﴾».","url":""}]},{"id":"s3-372","number":372,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿كنتم خير أمة﴾ بالماضي، دون أن يقال: أنتم خير أمة؟","answer":"الماضي يقرر الخيرية كحقيقة ثابتة في علم الله وكتبه، أو يذكّر بتحققها حين قامت الأمة بشروطها، لا أنه يمنحها امتيازًا بلا عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص558، تحت «دلالة (كان) بين النقصان والتمام».","url":""}]},{"id":"s3-373","number":373,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿أخرجت للناس﴾ بالبناء للمجهول؟","answer":"البناء للمجهول يصرف النظر إلى إخراجها الرباني للقيام برسالة، و﴿للناس﴾ يجعل خيريتها وظيفة نفع وهداية لا تفوقًا ذاتيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص559–560، تحت «سبب إيثار التعبير بصيغة المبني للمفعول».","url":""}]},{"id":"s3-374","number":374,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"لماذا قدّم الأمر بالمعروف والنهي عن المنكر على الإيمان بالله هنا؟","answer":"لأن الخيرية التي امتازت بها الأمة في علاقتها بالناس تظهر بهاتين الوظيفتين، ثم ذُكر الإيمان أصلًا يصححهما؛ وليس الترتيب ترتيب فضل مطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص563–564، تحت «سبب تقديم الأمر بالمعروف والنهي عن المنكر على الإيمان بالله».","url":""}]},{"id":"s3-375","number":375,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"لماذا عُلّقت خيرية الأمة بنفع ﴿الناس﴾ لا بنفسها؟","answer":"عُلّقت الخيرية بالناس لأن الأمة أُخرجت لنفعهم بدعوتهم وإقامة المعروف وكف المنكر؛ ففضلها وظيفة وهداية بقدر وفائها بهذه الأوصاف، لا تفوقًا ذاتيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص560، تحت «دلالة كلمة ﴿أُخرجت﴾».","url":""}]},{"id":"s3-376","number":376,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو آمن أهل الكتاب لكان خيرًا لهم﴾ مع أن فيهم مؤمنين؟","answer":"الحكم موجه إلى جمهور أهل الكتاب الذين لم يؤمنوا الإيمان التام بمحمد ﷺ، ثم احتُرز بقوله ﴿منهم المؤمنون﴾ لئلا يعمم الذم؛ فوجود قلة مؤمنة لا يناقض توبيخ الجماعة الغالبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص565، تحت «فوائد التعبير بالشرط في قوله: ﴿ولو آمن أهل الكتاب﴾».","url":""}]},{"id":"s3-377","number":377,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"لماذا خُتمت الآية بـ﴿منهم المؤمنون وأكثرهم الفاسقون﴾؟","answer":"خُتمت بذلك إنصافًا للقلة المؤمنة ومنعًا لتعميم الذم، مع بيان أن الأكثرية فاسقة خارجة عن الطاعة، ولذلك لم يتحقق الإيمان الذي هو خير لهم في جماعتهم عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص567، تحت «قوله تعالى: ﴿منهم المؤمنون وأكثرهم الفاسقون﴾ بين الاحتراس والاستئناف البياني».","url":""}]},{"id":"s3-378","number":378,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿لن يضروكم إلا أذى﴾، وكيف استثنى الأذى من الضرر؟","answer":"الأذى ضرر يسير لا يبلغ استئصال الدين أو الجماعة؛ فالاستثناء يطمئن المؤمنين مع عدم إنكار ما يصيبهم من قول أو مشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص572–573، تحت «دلالة الاستثناء بين الاتصال والانقطاع».","url":""}]},{"id":"s3-379","number":379,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"لماذا صوّر هزيمتهم بقوله ﴿يولوكم الأدبار﴾؟","answer":"لأن المهزوم يعرض عن خصمه ويوليه ظهره فارًا، فاختيرت الصورة الحركية لتجعل انكسارهم وهربهم مشاهدًا لا مجرد خبر عن الهزيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص574، تحت «نكتة التعبير بقوله: ﴿الأدبار﴾».","url":""}]},{"id":"s3-380","number":380,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"ما مناسبة قوله تعالى بعد ذكر الإدبار: ﴿ثم لا ينصرون﴾؟","answer":"لأن تولية الأدبار قد تكون تحرفًا يعقبه كر أو نصر، فاحترس بنفي النصر، و﴿ثم﴾ ترتقي من هزيمتهم في القتال إلى خذلان أعم وأدوم ما دام المؤمنون قائمين بخيريتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص574–575، تحت «بلاغة الاحتراس في قوله: ﴿ثم لا ينصرون﴾».","url":""}]},{"id":"s3-381","number":381,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ضربت عليهم الذلة﴾، وكيف تُضرب الذلة؟","answer":"استعير الضرب لإلزام الذلة بهم وإحاطتها، كقبة أو خيمة تضرب فوق قوم فتغشاهم ولا تفارقهم؛ فليست ذلة عارضة بل حال ثابتة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص578–579، تحت «بلاغة الاستعارة في قوله: ﴿ضربت عليهم الذلة﴾».","url":""}]},{"id":"s3-382","number":382,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿أين ما ثقفوا﴾، دون أن يقال: أينما وجدوا؟","answer":"﴿ثقفوا﴾ تفيد الظفر بهم والتمكن منهم، لا مجرد العثور المحايد؛ فهي أنسب بسياق الذلة والحماية التي لا تقوم إلا بعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص580، تحت «مناسبة التعبير بكلمة ﴿ثقفوا﴾».","url":""}]},{"id":"s3-383","number":383,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا استثنى ﴿إلا بحبل من الله وحبل من الناس﴾، وما صورة الحبلين؟","answer":"استثنيت حال أمنهم بعهد وذمة؛ فشبه العهد بالحبل الذي يتعلق به المهدد فيمنعه من السقوط: حبل من الله بشرعه وعهده، وحبل من الناس بأمانهم وحمايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص582، تحت «بلاغة الاستعارة في قوله: ﴿بحبل من الله وحبل من الناس﴾».","url":""}]},{"id":"s3-384","number":384,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا كرر لفظ ﴿حبل﴾ ولم يقل: بحبل من الله والناس؟","answer":"كرر ﴿حبل﴾ لأنهما سببان مستقلان لا حبل واحد مشترك النسبة: عهد من الله، وعهد من الناس؛ وفي التكرار توكيد أن الأمن لا يقوم إلا بأحدهما مع تقديم حبل الله لشرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص582، تحت «بلاغة الاستعارة في قوله: ﴿بحبل من الله وحبل من الناس﴾».","url":""}]},{"id":"s3-385","number":385,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿وباءوا بغضب من الله﴾، وكيف يرجع الإنسان بغضب؟","answer":"﴿باءوا﴾ أي رجعوا مستقرين فيما كسبوه، فكأن غضب الله منزل صار مآبهم الملازم جزاء أعمالهم، واللفظ يغلب في الرجوع بعاقبة الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص583، تحت «بلاغة الاستعارة التهكمية في قوله: ﴿وباءوا﴾».","url":""}]},{"id":"s3-386","number":386,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا عُطف ضرب المسكنة على ضرب الذلة؟","answer":"الذلة قهر ظاهر وفقد للعزة، والمسكنة فقر وانكسار باطن وحاجة؛ فجمع العقوبة في الحال الخارجية والنفسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص583–584، تحت «مناسبة الوصل في قوله: ﴿وضربت عليهم المسكنة﴾».","url":""}]},{"id":"s3-387","number":387,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"لماذا كرر ﴿ذلك بأنهم﴾ مرتين في تعليل حالهم؟","answer":"جاء التعليل الأول بالكفر وقتل الأنبياء سببًا للذلة والغضب والمسكنة، ثم كشف الثاني الجذر المتكرر لذلك: العصيان وتجاوز الحدود؛ فليس تكرارًا لفظيًا بل بيان لسلسلة الجريمة وسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص584–587، تحت «بلاغة الاستئناف البياني في قوله: ﴿ذلك بأنهم كانوا﴾».","url":""}]},{"id":"s3-388","number":388,"surah":3,"verses":[112],"references":[{"surah":3,"verses":[112]}],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ويقتلون الأنبياء بغير حق﴾ مع أن قتل الأنبياء لا يكون بحق أصلًا؟","answer":"قُيد القتل بـ﴿بغير حق﴾ للتسجيل عليهم بأنه لم يستند إلى أدنى سبب أو شبهة، لا في الشرع ولا حتى في دعواهم؛ فالقيد للتشنيع وكشف العمد لا لاحتمال قتل نبي بحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص585، تحت «دلالة الحال في قوله: ﴿بغير حق﴾».","url":""}]},{"id":"s3-391","number":391,"surah":3,"verses":[113],"references":[{"surah":3,"verses":[113]}],"verseLabel":"آل عمران: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿ليسوا سواء﴾ بعد الأحكام على أهل الكتاب؟","answer":"جاء ﴿ليسوا سواء﴾ احتراسًا وإنصافًا بعد ذم الأكثرين؛ فليس أهل الكتاب في الكفر والفسق درجة واحدة، بل منهم أمة قائمة مؤمنة تتلو آيات الله وتعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص592–593، تحت «سر العدول عن (متساوين) إلى ﴿سواء﴾ في حيز النفي».","url":""}]},{"id":"s3-392","number":392,"surah":3,"verses":[113],"references":[{"surah":3,"verses":[113]}],"verseLabel":"آل عمران: 113","question":"لماذا وصف طائفة منهم بأنها ﴿أمة قائمة﴾؟","answer":"وصفت بالقائمة لأنها مستقيمة ثابتة على الحق، قائمة بأمر الله وعبادته، في مقابل من انحرف من أهل الكتاب؛ فالقيام هنا قيام دين وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص595، تحت «بلاغة المجاز في قوله تعالى: ﴿أمة قائمة﴾».","url":""}]},{"id":"s3-394","number":394,"surah":3,"verses":[113],"references":[{"surah":3,"verses":[113]}],"verseLabel":"آل عمران: 113","question":"لماذا عطف السجود على تلاوة الآيات بجملة حالية؟","answer":"ليصور اجتماع العلم بالعبادة في الوقت نفسه: يتلون كتاب الله في حال خضوع وسجود، فلا تكون تلاوتهم معرفة مجردة بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص596، تحت «نكتة مجيء ﴿وهم يسجدون﴾ حالًا بعد نعت التلاوة».","url":""}]},{"id":"s3-395","number":395,"surah":3,"verses":[114],"references":[{"surah":3,"verses":[114]}],"verseLabel":"آل عمران: 114","question":"لماذا أعيد الإيمان بالله واليوم الآخر بعد وصفهم بتلاوة الكتاب؟","answer":"لأن التلاوة وحدها قد تقع بلا تصديق أو عمل، فأثبت لهم الإيمان الذي يميز تلاوتهم من تلاوة المحرفين ويصلها بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص597، تحت «نكتة تقديم نعت التلاوة على نعت الإيمان بالله».","url":""}]},{"id":"s3-396","number":396,"surah":3,"verses":[114],"references":[{"surah":3,"verses":[114]}],"verseLabel":"آل عمران: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿ويسارعون في الخيرات﴾، دون أن يقال: إلى الخيرات؟","answer":"قيل ﴿في الخيرات﴾ لتصويرهم منغمسين داخل أعمال الخير يتسابقون في أنواعها، أما «إلى» فتدل على مجرد الاتجاه نحو الغاية قبل بلوغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص597–598، تحت «بلاغة الاستعارة في قوله: ﴿ويسارعون في الخيرات﴾».","url":""}]},{"id":"s3-397","number":397,"surah":3,"verses":[114],"references":[{"surah":3,"verses":[114]}],"verseLabel":"آل عمران: 114","question":"لماذا ختم بـ﴿وأولئك من الصالحين﴾ لا: هم الصالحون؟","answer":"قال ﴿من الصالحين﴾ لإدخالهم في جماعة الصالحين الممتدة من هذه الأمة وغيرها، إثباتًا لاستحقاقهم الوصف من غير حصر الصلاح فيهم وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص599–600، تحت «دلالة اسم الإشارة ﴿وأولئك﴾».","url":""}]},{"id":"s3-398","number":398,"surah":3,"verses":[115],"references":[{"surah":3,"verses":[115]}],"verseLabel":"آل عمران: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يفعلوا من خير فلن يكفروه﴾، وكيف يُكفر الخير؟","answer":"استعمل الكفر في أصل معنى الستر والجحود؛ أي لن يُستر خيرهم أو يُجحد، بل يحفظ لهم ويجازون عليه مهما كان، ولذلك عمم بـ﴿من خير﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص605، تحت «مجاز التعبير بـ﴿يكفروه﴾».","url":""}]},{"id":"s3-399","number":399,"surah":3,"verses":[115],"references":[{"surah":3,"verses":[115]}],"verseLabel":"آل عمران: 115","question":"لماذا بُني ﴿فلن يكفروه﴾ للمجهول؟","answer":"بني للمجهول لأن من لا يكفر الخير معلوم وهو الله، ولتتجه العناية إلى الخير نفسه وضمان حفظه وجزائه، لا إلى ذكر الفاعل الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص605–606، تحت «مناسبة التعبير بصيغة المبني للمفعول في ﴿يكفروه﴾».","url":""}]},{"id":"s3-400","number":400,"surah":3,"verses":[115],"references":[{"surah":3,"verses":[115]}],"verseLabel":"آل عمران: 115","question":"لماذا ختم بـ﴿والله عليم بالمتقين﴾ لا بالمحسنين؟","answer":"لأن قبول العمل مردّه إلى باعث التقوى الخفي الذي يشمل الإحسان المذكور وغيره؛ فختم بالوصف الأعم والأصل الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص607–610، تحت «حسن التذييل في قوله: ﴿والله عليم بالمتقين﴾».","url":""}]},{"id":"s3-401","number":401,"surah":3,"verses":[116],"references":[{"surah":3,"verses":[116]}],"verseLabel":"آل عمران: 116","question":"لماذا قدّم الأموال على الأولاد في نفي الإغناء؟","answer":"المال هو أول ما يُبذل عادة لدفع الضرر والفداء، ثم تأتي قوة الأولاد والنسب؛ فنفى القرآن أقرب وسيلتي الاعتماد عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص615، تحت «نكتة جمع الأولاد إلى الأموال، وسر تقديم الأموال على الأولاد».","url":""}]},{"id":"s3-402","number":402,"surah":3,"verses":[116],"references":[{"surah":3,"verses":[116]}],"verseLabel":"آل عمران: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تغني عنهم أموالهم ولا أولادهم من الله شيئًا﴾؟","answer":"ينفي التركيب نفيًا مؤكدًا أن تدفع الأموال أو الأولاد عنهم أي شيء من عذاب الله أو حكمه؛ فلا فداء بالمال ولا نصرة بالولد، ولو بأدنى قدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص611–612، تحت «بلاغة المجاز في قوله: ﴿لن تغني عنهم أموالهم ولا أولادهم﴾».","url":""}]},{"id":"s3-403","number":403,"surah":3,"verses":[116],"references":[{"surah":3,"verses":[116]}],"verseLabel":"آل عمران: 116","question":"ما دلالة الجملة المستقلة في قوله تعالى: ﴿وأولئك أصحاب النار هم فيها خالدون﴾؟","answer":"جيء بـ﴿هم﴾ لتوكيد الحكم وتقوية اختصاصهم به، ومع تقديم ﴿فيها﴾ يقرر أنهم ملازمو النار خالدون فيها لا يخرجون منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص618–619، تحت «نكتة ذكر المسند إليه ﴿هم﴾ في قوله: ﴿هم فيها خالدون﴾».","url":""}]},{"id":"s3-404","number":404,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"لماذا شُبّه إنفاق الكافرين بريح فيها صر أصابت حرثًا؟","answer":"لأن الإنفاق يبدو كحرث يرجى ثمره، لكن الكفر يسلط عليه بردًا مهلكًا فيذهب أصله وثمرته؛ فالصورة تجمع العمل والرجاء ثم الخيبة المفاجئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص624–626، تحت «بلاغة التشبيه التمثيلي في قوله: ﴿مثل ما ينفقون﴾».","url":""}]},{"id":"s3-405","number":405,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"لماذا اختيرت ﴿ريح﴾ مفردة لا ﴿رياح﴾؟","answer":"أفردت لأنها ريح عذاب واحدة متجهة بقوتها إلى الحرث فتهلكه، بخلاف الرياح المتفرقة التي يكثر ورودها في سياق الرحمة وتلقيح السحاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص636–640، تحت «الريح والرياح».","url":""}]},{"id":"s3-406","number":406,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿فيها صر﴾، دون أن يقال: باردة أو شديدة؟","answer":"﴿الصر﴾ برد شديد نافذ يحرق النبات وييبسه، وفي جرس اللفظ إيحاء بالصرير والعنف؛ فهو أبلغ من وصف الريح بأنها باردة أو شديدة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص629–630، تحت «دلالة ﴿صر﴾ في قوله: ﴿فيها صر﴾».","url":""}]},{"id":"s3-407","number":407,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿أصابت حرث قوم ظلموا أنفسهم﴾، وما أثر وصفهم بالظلم؟","answer":"وصفوا بظلم النفس ليظهر أن هلاك الحرث لم يقع اعتباطًا، بل وافق استحقاقهم، وليهيئ للمقابلة: ما ظلمهم الله ولكنهم هم الذين جلبوا الخسران لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص630–631، تحت «بلاغة الإدماج في قوله: ﴿قوم ظلموا أنفسهم﴾».","url":""}]},{"id":"s3-408","number":408,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿فأهلكته﴾ بعد أن صوّر الإصابة؟","answer":"عُقب الإصابة بالفاء لتصوير الإهلاك نتيجة سريعة مباشرة، ولفظ الإهلاك يدل على ذهاب الحرث وثمرته كلها، كما يحبط الكفر أثر النفقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص632، تحت «براعة الإطناب بالتتميم في قوله: ﴿فأهلكته﴾».","url":""}]},{"id":"s3-409","number":409,"surah":3,"verses":[117],"references":[{"surah":3,"verses":[117]}],"verseLabel":"آل عمران: 117","question":"لماذا نفى ظلم الله ثم قال ﴿ولكن أنفسهم يظلمون﴾؟","answer":"نُفي الظلم عن الله لأن إحباط أعمالهم جزاء عادل، ثم استدرك بإثبات ظلمهم لأنفسهم؛ فهم الذين أفسدوا عملهم بالكفر وجلبوا عليها الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص632، تحت «دلالة حذف متعلق الظلم في قوله: ﴿ظلموا أنفسهم﴾».","url":""}]},{"id":"s3-410","number":410,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تتخذوا بطانة من دونكم﴾، وما صورة البطانة؟","answer":"شُبه القريب المطلع على السر ببطانة الثوب لملاصقتها باطنه وخفائها عن الناس؛ فالنهي عن إدخال من دون المؤمنين إلى موضع الثقة والسر الذي يكشف مواطن القوة والضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص641–642، تحت «بلاغة الاستعارة في قوله: ﴿لا تتخذوا بطانة من دونكم﴾».","url":""}]},{"id":"s3-411","number":411,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يألونكم خبالًا﴾، دون أن يقال: لا يقصرون في إفسادكم؟","answer":"أي لا يدخرون وسعًا في إيقاع الخبال بكم؛ والخبال فساد واضطراب شامل للرأي والحال، فالتعبير يجمع استفراغ الجهد واتساع أثر الإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص645، تحت «وجه نصب ﴿خبالًا﴾ في قوله: ﴿لا يألونكم خبالًا﴾».","url":""}]},{"id":"s3-412","number":412,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ودوا ما عنتم﴾، فجعل مشقتهم أمنية؟","answer":"لم يقتصروا على إيقاع الخبال، بل استقرت محبتهم لكل مشقة تصيب المؤمنين؛ فالتعبير يكشف أن عنتكم غاية يتمنونها لا أثرًا عارضًا لأفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص646، تحت «دلالة الأفعال الماضية: ﴿ودوا﴾ و﴿عنتم﴾ و﴿بدت﴾».","url":""}]},{"id":"s3-413","number":413,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿قد بدت البغضاء من أفواههم﴾ لا من ألسنتهم؟","answer":"اختيرت الأفواه لأنها منفذ الكلام كله، فكأن البغضاء امتلأت بها حتى فاضت، وما بقي في الصدور أعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص649–651، تحت «أفواههم وألسنتهم».","url":""}]},{"id":"s3-414","number":414,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تخفي صدورهم أكبر﴾، دون أن يقال: قلوبهم؟","answer":"اختيرت الصدور لأنها الحيز الذي يضم القلوب وما تستكنه من أسرار، فكأن بغضاء عظيمة مخزونة فيها لا تفصح الأفواه إلا عن طرف منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص647–648، تحت «بلاغة المجاز المرسل في قوله: ﴿وما تخفي صدورهم أكبر﴾».","url":""}]},{"id":"s3-415","number":415,"surah":3,"verses":[118],"references":[{"surah":3,"verses":[118]}],"verseLabel":"آل عمران: 118","question":"لماذا خُتمت الآية بـ﴿إن كنتم تعقلون﴾؟","answer":"لأن الآيات كشفت ظاهر عداوتهم وباطنها، فالعقل السليم يقتضي ألا يُتخذوا بطانة؛ والشرط يحث المؤمنين على إعمال العقل ويعرض بمن يخالف هذا البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص648، تحت «مناسبة الفاصلة ﴿تعقلون﴾ لمضمون الآية».","url":""}]},{"id":"s3-416","number":416,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ها أنتم أولاء تحبونهم ولا يحبونكم﴾؟","answer":"جيء بالتنبيه والإشارة كأن حالهم حاضرة تُرى: أنتم هؤلاء تحبون قومًا لا يبادلونكم الحب؛ وفيه تعجيب وتوبيخ يدعوان إلى مراجعة هذه الثقة غير المتكافئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص652، تحت «بلاغة الاكتفاء في قوله: ﴿ها أنتم أولاء تحبونهم ولا يحبونكم﴾».","url":""}]},{"id":"s3-417","number":417,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وتؤمنون بالكتاب كله﴾ بالإفراد مع تعدد الكتب؟","answer":"أُفرد ﴿الْكِتَابِ﴾ والمراد جنس الكتب المنزلة؛ للدلالة على وحدة مصدرها وتوافق أصولها، فالمؤمنون يؤمنون بها كلها، بخلاف من يقبل بعض الوحي ويرد بعضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص652–653، تحت «بلاغة الاكتفاء في قوله: ﴿هاأنتم أولاء تحبونهم ولا يحبونكم وتؤمنون بالكتاب كله﴾».","url":""}]},{"id":"s3-418","number":418,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما سرّ قولهم عند اللقاء ﴿آمَنَّا﴾، ثم عضِّهم الأنامل إذا خلوا؟","answer":"يقولون ﴿آمنا﴾ في حضور المؤمنين مداراةً ونفاقًا، فإذا خلوا ظهر ما يكتمونه من شدة الغيظ؛ فالمقابلة تكشف انفصال ظاهرهم المصطنع عن باطنهم المعادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص653–655، تحت «بلاغة التورية في قوله: ﴿وإذا لقوكم قالوا آمنا﴾».","url":""}]},{"id":"s3-419","number":419,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿عضوا عليكم الأنامل من الغيظ﴾ لا الأصابع؟","answer":"خُصت الأنامل لأنها موضع العض من الأصابع، وصورة ضغط الأسنان على أطرافها تجسد غيظًا شديدًا مكظومًا لا يجد صاحبه سبيلًا إلى الإضرار بمن يغتاظ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص655–656، تحت «براعة التمثيل في قوله: ﴿عضوا عليكم الأنامل من الغيظ﴾».","url":""}]},{"id":"s3-420","number":420,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"لماذا أُمر النبي أن يقول ﴿موتوا بغيظكم﴾؟","answer":"ليس أمرًا مقدورًا يراد امتثاله، بل تهديد وتبكيت: ابقوا في غيظكم حتى تموتوا به، فلن تنالوا ما تتمنونه للمؤمنين ولن يغير حقدكم وعد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص656، تحت «دلالة الأمر في قوله: ﴿موتوا بغيظكم﴾».","url":""}]},{"id":"s3-421","number":421,"surah":3,"verses":[119],"references":[{"surah":3,"verses":[119]}],"verseLabel":"آل عمران: 119","question":"لماذا ختم بـ﴿إن الله عليم بذات الصدور﴾؟","answer":"السياق يكشف بغضًا يخفونه وراء الكلام، فناسبه العلم الملازم لما استقر في الصدور قبل أن يظهر على الألسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص658–659، تحت «بلاغة التذييل في قوله: ﴿إن الله عليم بذات الصدور﴾».","url":""}]},{"id":"s3-422","number":422,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تمسسكم حسنة تسؤهم﴾، فجعل الحسنة تمس؟","answer":"عبر بالمس لأن المس أدنى اتصال، فالمعنى أن أقل حسنة تصل إليكم وتلامس حالكم تكفي لإساءتهم؛ وهذا أبلغ في كشف شدة حسدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص662–663، تحت «دلالة الاستعارة في قوله: ﴿إن تمسسكم حسنة تسؤهم وإن تصبكم سيئة يفرحوا بها﴾».","url":""}]},{"id":"s3-423","number":423,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"لماذا قابل ﴿حسنة﴾ بـ﴿سيئة﴾ مع أن المراد نعمة ومصيبة؟","answer":"سميت النعمة حسنة لحسن أثرها، والمصيبة سيئة لسوء أثرها على من تنزل به؛ وبهذين اللفظين يعم التقابل كل ما يسر المؤمنين أو يسوؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص663، تحت «نكتة الاستعارة في التعبير بالحسنة والسيئة».","url":""}]},{"id":"s3-424","number":424,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى في الحسنة ﴿تسؤهم﴾ وفي السيئة ﴿يفرحوا بها﴾؟","answer":"نسبت الحسنة إلى سوء يقع في نفوسهم فورًا، أما السيئة فجعلت متعلق فرحهم تصريحًا؛ فاجتمع تألمهم بخير المؤمنين وابتهاجهم بشرهم، وهو أقصى انقلاب العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص663، تحت «دلالة المقابلة في قوله: ﴿إن تمسسكم حسنة تسؤهم وإن تصبكم سيئة يفرحوا بها﴾».","url":""}]},{"id":"s3-425","number":425,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"لماذا جُمع الصبر والتقوى في شرط بطلان كيدهم؟","answer":"الصبر يمنع الانهيار أمام الأذى، والتقوى تمنع مجاوزة الحق في الرد؛ وباجتماعهما تحفظ القوة من الضعف ومن الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص665، تحت «دلالة حذف متعلَّقَي الصبر والتقوى في قوله: ﴿وإن تصبروا وتتقوا﴾».","url":""}]},{"id":"s3-426","number":426,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يضركم كيدهم شيئًا﴾ فنكّر شيئًا؟","answer":"نكرت في سياق النفي لتعم؛ أي لا يصيبكم من كيدهم أي ضرر، ولو أقل شيء، مع تحقق شرط الصبر والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص664–665، تحت «دلالة نفي الضر دون نفي الأذى في قوله: ﴿لا يضركم كيدهم شيئًا﴾».","url":""}]},{"id":"s3-427","number":427,"surah":3,"verses":[120],"references":[{"surah":3,"verses":[120]}],"verseLabel":"آل عمران: 120","question":"ما دلالة وصف الله تعالى بأنه ﴿بما يعملون محيط﴾ في ختام الآية؟","answer":"الإحاطة هنا كناية عن شمول علم الله وقدرته لأعمالهم وكيدهم، فلا يفوته منها ظاهر ولا خفي. وخاتمتها تطمئن المؤمنين أن ما أُمروا بالصبر والتقوى في مواجهته واقع تحت علم الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص665–666، تحت «دلالة قوله تعالى: ﴿بما يعملون محيط﴾».","url":""}]},{"id":"s3-428","number":428,"surah":3,"verses":[121],"references":[{"surah":3,"verses":[121]}],"verseLabel":"آل عمران: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ غدوت من أهلك﴾، دون أن يقال: خرجت؟","answer":"﴿غدوت﴾ لا تدل على مطلق الخروج، بل على الخروج في أول النهار؛ فترسم بدء الحدث من بيت النبي ﷺ باكرًا لتبوئة المؤمنين مواقع القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص506، تحت «الغدو والإصباح».","url":""}]},{"id":"s3-429","number":429,"surah":3,"verses":[121],"references":[{"surah":3,"verses":[121]}],"verseLabel":"آل عمران: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿تبوئ المؤمنين مقاعد للقتال﴾، وما صورة التبوئة والمقاعد؟","answer":"التبوئة تهيئة المكان وإنزال صاحبه فيه، والمقاعد هي المواقع التي يثبت فيها المقاتلون؛ فالصورة تجعل توزيع الصفوف كإسكان كل جماعة في موضعها المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص670–671، تحت «دلالة التعبير بالمقاعد دون المواقف في قوله: ﴿مقاعد للقتال﴾».","url":""}]},{"id":"s3-430","number":430,"surah":3,"verses":[121],"references":[{"surah":3,"verses":[121]}],"verseLabel":"آل عمران: 121","question":"لماذا ختمت الآية بـ﴿والله سميع عليم﴾؟","answer":"يسمع ما دار من المشاورة والأقوال عند الخروج، ويعلم النيات والتدبير؛ فخاتمتها إحاطة بما ظهر وما بطن في موقف أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص671، تحت «بلاغة التذييل في قوله: ﴿والله سميع عليم﴾».","url":""}]},{"id":"s3-431","number":431,"surah":3,"verses":[122],"references":[{"surah":3,"verses":[122]}],"verseLabel":"آل عمران: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ همت طائفتان منكم أن تفشلا﴾، دون أن يقال: عزمتا؟","answer":"اختير الهم لأنه ميل وقصد أولي إلى الفشل لم يستقر عزمًا ولا يتحول فعلًا؛ فأنقذتهما ولاية الله وثبتهما قبل أن تمضيا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص675–676، تحت «سر التعبير بالهم دون العزم».","url":""}]},{"id":"s3-433","number":433,"surah":3,"verses":[122],"references":[{"surah":3,"verses":[122]}],"verseLabel":"آل عمران: 122","question":"لماذا جاء بعد الهمّ بالفشل قوله ﴿والله وليهما﴾؟","answer":"عُقب الهم بالولاية لبيان أن الله تولاهما بالتثبيت فلم يتحول ميلهما العارض إلى فشل، وفي ذلك تطمين بأن الحفظ والنصر من مقتضى ولايته للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص677، تحت «دلالة الاعتراض بعد ذكر الصفة».","url":""}]},{"id":"s3-434","number":434,"surah":3,"verses":[122],"references":[{"surah":3,"verses":[122]},{"surah":9,"verses":[51]}],"verseLabel":"آل عمران: 122؛ التوبة: 51","question":"لماذا ختم بـ﴿وعلى الله فليتوكل المؤمنون﴾ بتقديم الجار والمجرور؟","answer":"في آل عمران: 122: قُدم ﴿على الله﴾ لقصر التوكل عليه؛ فمن كان الله وليه وجب أن يعتمد عليه وحده في الثبات والنصر، لا على العدد والعدة.\n\nفي التوبة: 51: تقديم ﴿على الله﴾ يفيد القصر: على الله وحده يعتمد المؤمنون، لا على عدة أو حذر مستقل عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص678، تحت «السر في تقديم الجار والمجرور».","url":""}]},{"id":"s3-435","number":435,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد نصركم الله ببدر وأنتم أذلة﴾؟","answer":"ذُكر بدر شاهدًا واقعًا على ثمرة التوكل وولاية الله؛ فقد نصرهم مع ضعفهم، فكان تذكيرًا يمنع الفشل ويجدد الثقة بعد ما أصابهم في أُحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص682، تحت «دلالة الاستئناف بعد ذكر الأحداث الواقعة يوم أُحد».","url":""}]},{"id":"s3-436","number":436,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"لماذا وصف المؤمنين يوم بدر بـ﴿أذلة﴾ لا: قليلين؟","answer":"﴿أذلة﴾ تصف مجموع ضعفهم الظاهر يوم بدر: قلة العدد والسلاح والمال أمام عدو قوي، فهي أوسع من «قليلين» ولا تعني المهانة في الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص683–685، تحت «دلالة الكناية في التعبير عن الضعف بجمع القلة بلفظة ﴿أذلة﴾».","url":""}]},{"id":"s3-437","number":437,"surah":3,"verses":[123],"references":[{"surah":3,"verses":[123]}],"verseLabel":"آل عمران: 123","question":"لماذا أُتبع النصر بالأمر ﴿فاتقوا الله لعلكم تشكرون﴾؟","answer":"لما كان النصر نعمة من الله أُمروا بتقواه ليلزموا طاعته ولا يغتروا بالأسباب، وبذلك يتحقق شكر النعمة قولًا وعملًا وتدوم آثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص686، تحت «نكتة التعبير بـ﴿لعلكم﴾ في مقام الشكر».","url":""}]},{"id":"s3-438","number":438,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]}],"verseLabel":"آل عمران: 124","question":"ما دلالة عرض كفاية المدد في صورة السؤال: ﴿ألن يكفيكم﴾؟","answer":"التقرير يحملهم على الإقرار بأن مدد الله كافٍ، فينشأ الاطمئنان من جواب تستحضره نفوسهم لا من خبر يلقى عليهم فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص693، تحت «دلالة دخول همزة الاستفهام على أداة النفي».","url":""}]},{"id":"s3-439","number":439,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]}],"verseLabel":"آل عمران: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يمدكم ربكم﴾، دون أن يقال: ينصركم؟","answer":"اختير الإمداد لأنه رفد القوة بملائكة يتتابعون إلى المؤمنين، وهو سبب للتثبيت والبشارة، أما النصر فهو الغلبة النهائية التي قررت الآيات أنها من عند الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص699، تحت «المدد والإمداد».","url":""}]},{"id":"s3-440","number":440,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]}],"verseLabel":"آل عمران: 124","question":"لماذا كان الإمداد بـ﴿ثلاثة آلاف من الملائكة منزلين﴾؟","answer":"حُددت الثلاثة آلاف لتقوية البشرى ومقابلة ما خيف من زيادة العدو، ووصفوا بالمنزلين لبيان أن المدد يُنزل من عند الله إلى ساحة القتال تثبيتًا للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص695، تحت «نكتة وصف الملائكة بالتنزل».","url":""}]},{"id":"s3-441","number":441,"surah":3,"verses":[124],"references":[{"surah":3,"verses":[124]},{"surah":8,"verses":[9]}],"verseLabel":"آل عمران: 124؛ الأنفال: 9","question":"لماذا كان الإمداد في الأنفال بألف من الملائكة، وفي آل عمران بثلاثة آلاف ثم خمسة آلاف؟","answer":"آية الأنفال تحكي أصل الاستجابة يوم بدر فذكرت الألف ابتداءً، أما آل عمران فتستعيد الموقف لتثبيت المؤمنين بعد أحد وتعرض تدرج البشارة بحسب الصبر والتقوى وفور العدو؛ فالأعداد مراحل إمداد وبشارة لا تعارض بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698، تحت «الحكمة من تدرج ذكر المدد بين سورتي الأنفال وآل عمران».","url":""}]},{"id":"s3-442","number":442,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"لماذا ارتفع العدد من ثلاثة آلاف إلى خمسة آلاف؟","answer":"البشارة الثانية معلقة بصبرهم وتقواهم ومجيء العدو من فوره، فزاد العدد مع اشتداد الظرف وثبات المؤمنين؛ وهو تدرج في التطمين لا اضطراب في الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص694، تحت «سر التكثير بذكر العدد مع جمع لفظة الملائكة».","url":""}]},{"id":"s3-443","number":443,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"لماذا عُلّق الإمداد بشرطي الصبر والتقوى؟","answer":"ليتعلق القلب بالطاعة لا بالعدد: الصبر ثبات أمام العدو، والتقوى حفظ لأمر الله؛ وهما سبب الأهلية للتأييد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص697، تحت «دلالة اقتران لفظ ﴿الفور﴾ وعطفه على ذكر الصبر والتقوى».","url":""}]},{"id":"s3-444","number":444,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿ويأتوكم من فورهم هذا﴾؟","answer":"أي يأتيكم العدو عاجلًا من ساعته بلا إمهال؛ واسم الإشارة يقرب هذا الفور ويستحضره، فتناسب زيادة المدد مباغتة الخطر وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص697، تحت «سر الكناية بالفور على العجلة».","url":""}]},{"id":"s3-445","number":445,"surah":3,"verses":[125],"references":[{"surah":3,"verses":[125]}],"verseLabel":"آل عمران: 125","question":"لماذا وُصف الملائكة بـ﴿مسوّمين﴾؟","answer":"أي ذوي علامات ظاهرة تميزهم وتطمئن المؤمنين، أو مرسلين مسلطين في القتال بحسب القراءة؛ فاللفظ يصور مددًا منظمًا معروف السمة لا حضورًا مبهمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698–699، تحت «سر الكناية عن الشدة بالتسويم».","url":""}]},{"id":"s3-446","number":446,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]}],"verseLabel":"آل عمران: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به﴾، مع أن النصر حاصل؟","answer":"قصر وظيفة المدد على البشارة والطمأنينة حتى لا تتعلق القلوب بالملائكة أو العدد؛ فالنصر في حقيقته من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص704–705، تحت «بلاغة القصر بالاستثناء في الإخبار عن البشرى وطمأنة القلوب».","url":""}]},{"id":"s3-447","number":447,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]}],"verseLabel":"آل عمران: 126","question":"لماذا نُسب الاطمئنان إلى القلوب؟","answer":"لأن القلب موطن الخوف والثبات والنية، والمقصود من المدد تسكين الاضطراب الباطن قبل أثره العسكري؛ أما النصر فمن عند الله لا من العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص704، تحت «بلاغة القصر بالاستثناء في الإخبار عن البشرى وطمأنة القلوب».","url":""}]},{"id":"s3-448","number":448,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]}],"verseLabel":"آل عمران: 126","question":"لماذا ختم بـ﴿العزيز الحكيم﴾؟","answer":"العزة تثبت نفاذ القدرة، والحكمة تثبت أن هذا النفاذ موضوع في موضعه بلا عبث ولا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص706، تحت «دلالة ختم التذييل بوصف العزة والحكمة للرب الجليل».","url":""}]},{"id":"s3-449","number":449,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]},{"surah":8,"verses":[10]}],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"لماذا زادت آل عمران ﴿بشرى لكم﴾، بينما قالت الأنفال ﴿إلا بشرى﴾؟","answer":"آل عمران تحكي بدرًا للمواساة بعد جرح أحد فخصت البشرى بالمؤمنين تصريحًا: ﴿لكم﴾؛ أما الأنفال فنزلت في قلب الحدث وكان كون البشرى لهم معلومًا من الخطاب، فاستغنى السياق عن المتعلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص706–708، تحت «بلاغة اختلاف النظم في المتشابه اللفظي بين سورتي آل عمران والأنفال».","url":""}]},{"id":"s3-450","number":450,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]},{"surah":8,"verses":[10]}],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"ما سرّ اختلاف الترتيب بين قوله تعالى في آل عمران ﴿ولتطمئن قلوبكم به﴾، وفي الأنفال ﴿ولتطمئن به قلوبكم﴾؟","answer":"في آل عمران: 126؛ الأنفال: 10: مقام آل عمران مقام جبر القلوب بعد أحد، فقدم القلوب لتكون موضع العناية والمواساة؛ أما الأنفال فالمقام مقام الإمداد في بدر، فقدم ﴿به﴾ لربط الطمأنينة بسبب البشرى والإمداد ولإفادة الاختصاص.\n\nفي الأنفال: 10: قُدّم ﴿به﴾ للعناية بسبب الطمأنينة، ولربطها بالمدد المذكور مع التأكيد أن أثره نفسي لا أنه مصدر النصر استقلالًا.\n\nفي الأنفال: 10: قُدّم ﴿به﴾ في الأنفال لقرب ذكر المدد والعناية بكونه سبب الطمأنينة، وأُخر في آل عمران لأن العناية هناك بطمأنينة القلوب المخاطبة عقب ﴿بشرى لكم﴾.","sources":[{"label":"[آل عمران: 126؛ الأنفال: 10] موسوعة التفسير البلاغي، ج5، ص707–708","url":""},{"label":"[الأنفال: 10] موسوعة التفسير البلاغي، ج15، ص634–636","url":""},{"label":"[الأنفال: 10] موسوعة التفسير البلاغي، ج5، ص706–707، تحت آل عمران 126","url":""}]},{"id":"s3-451","number":451,"surah":3,"verses":[126],"references":[{"surah":3,"verses":[126]},{"surah":8,"verses":[10]}],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"لماذا ختمت آل عمران بـ﴿الله العزيز الحكيم﴾، وختمت الأنفال بـ﴿إن الله عزيز حكيم﴾؟","answer":"الأنفال نزلت وقت المواجهة والوعد لمّا يتحقق بعد، فناسبها توكيد العزة والحكمة بـ﴿إن﴾؛ أما آل عمران فتحكي نصرًا شوهد أثره، فتكفي الصفتان معرفتين بلا توكيد جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص708، تحت «تعريف الفاصلة وتنكيرها مع التوكيد في ﴿العزيز الحكيم﴾ و﴿إن الله عزيز حكيم﴾».","url":""}]},{"id":"s3-452","number":452,"surah":3,"verses":[127],"references":[{"surah":3,"verses":[127]}],"verseLabel":"آل عمران: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ليقطع طرفًا من الذين كفروا﴾، وما صورة قطع الطرف؟","answer":"صوّر جماعة العدو جسمًا يُقطع طرف منه بالقتل والأسر، فيضعف باقيه؛ والتبعيض يطابق ما وقع من إصابة فريق لا استئصال الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص709، تحت «دلالة تخصيص قطع الطرف».","url":""}]},{"id":"s3-453","number":453,"surah":3,"verses":[127],"references":[{"surah":3,"verses":[127]}],"verseLabel":"آل عمران: 127","question":"لماذا عطف ﴿أو يكبتهم﴾ على قطع الطرف؟","answer":"عطف الكبت لأنه مآل آخر غير قطع الطرف: فقد يهلك الله طائفة منهم بالقتل، أو يصرعهم ويذلهم ويغيظهم ويردهم مهزومين؛ فـ﴿أو﴾ تفصل بين وجهي النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص709، تحت «دلالة تخصيص قطع الطرف».","url":""}]},{"id":"s3-454","number":454,"surah":3,"verses":[127],"references":[{"surah":3,"verses":[127]}],"verseLabel":"آل عمران: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿فينقلبوا خائبين﴾، فجعل رجوعهم انقلابًا؟","answer":"﴿ينقلبوا﴾ تصور رجوعهم القهقرى وقد تحولت حالهم من الطمع في الغلبة إلى الهزيمة، و﴿خائبين﴾ أي محرومين لم ينالوا ما طلبوا؛ فليس رجوعًا مكانيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص711، تحت «سر التناسب بين ذكر الكبت والانقلاب بالخيبة».","url":""}]},{"id":"s3-455","number":455,"surah":3,"verses":[128],"references":[{"surah":3,"verses":[128]}],"verseLabel":"آل عمران: 128","question":"لماذا اعترض السياق بقوله ﴿ليس لك من الأمر شيء﴾ مخاطبًا النبي ﷺ؟","answer":"الاعتراض يردّ أمر الهداية والجزاء إلى الله، ويعلّم أن وظيفة الرسول البلاغ والجهاد لا التحكم في مصائر القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص715، تحت «بديع الالتفات بتوجيه الخطاب لرسول الله ﷺ وتخصيصه به».","url":""}]},{"id":"s3-456","number":456,"surah":3,"verses":[128],"references":[{"surah":3,"verses":[128]}],"verseLabel":"آل عمران: 128","question":"لماذا سوّى في الاحتمال بين ﴿يتوب عليهم﴾ و﴿يعذبهم﴾؟","answer":"ذُكرت التوبة والعذاب احتمالين لأن الحكم لله وحده لا لرغبة بشر: إن رجعوا وفقهم وقبل توبتهم، وإن أصروا عذبهم بظلمهم؛ وفي ذلك إبقاء لباب الهداية مع إثبات العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص716، تحت «سر إدراج ذكر التوبة والتعذيب في معرض ذكر علل النصر وغاياته».","url":""}]},{"id":"s3-457","number":457,"surah":3,"verses":[128],"references":[{"surah":3,"verses":[128]}],"verseLabel":"آل عمران: 128","question":"لماذا ختم بـ﴿فإنهم ظالمون﴾ لا: كافرون؟","answer":"وصفهم بالظلم لبيان سبب العذاب: فقد ظلموا أنفسهم بالكفر والعدوان ووضعوا الحق في غير موضعه؛ واللفظ أعم في تصوير الجناية، ولا يغلق باب التوبة الذي ذكر قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص716، تحت «سر إدراج ذكر التوبة والتعذيب في معرض ذكر علل النصر وغاياته».","url":""}]},{"id":"s3-458","number":458,"surah":3,"verses":[129],"references":[{"surah":3,"verses":[129]}],"verseLabel":"آل عمران: 129","question":"لماذا قدّم المغفرة على العذاب؟","answer":"لأن الآية جاءت بعد فتح باب التوبة والدعاء على الظالمين، فقدم ما يلائم سعة الرحمة وإمكان الرجوع، ثم ذكر العذاب عدلًا لمن أصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص724، تحت «دلالة التذييل بذكر وصفي المغفرة والرحمة وتأكيده».","url":""}]},{"id":"s3-459","number":459,"surah":3,"verses":[129],"references":[{"surah":3,"verses":[129]}],"verseLabel":"آل عمران: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر لمن يشاء ويعذب من يشاء﴾ ثم ختم بـ﴿غفور رحيم﴾ دون اسم يدل على العقاب؟","answer":"الخاتمة تفتح باب الرجاء، وتبين أن المغفرة أثر الرحمة لا مجرد إسقاط العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص724، تحت «دلالة التذييل بذكر وصف المغفرة والرحمة وتأكيده».","url":""}]},{"id":"s3-460","number":460,"surah":3,"verses":[130],"references":[{"surah":3,"verses":[130]}],"verseLabel":"آل عمران: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تأكلوا الربا﴾ مع أن التعامل به ليس أكلًا فقط؟","answer":"عبّر بالأكل عن أخذ مال الربا والانتفاع به لأن الأكل أشهر وجوه استهلاك المال وأظهر مقاصده؛ فالنهي يعم تملكه والتصرف فيه، لا المضغ الحسي وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص729، تحت «دلالة المجاز في التعبير بالأكل عن التعاطي».","url":""}]},{"id":"s3-461","number":461,"surah":3,"verses":[130],"references":[{"surah":3,"verses":[130]}],"verseLabel":"آل عمران: 130","question":"لماذا وصف الربا بـ﴿أضعافًا مضاعفة﴾؟","answer":"الوصف يصور ربا الجاهلية: إذا حل الدين زيد في المال مقابل التأجيل، فتتكرر الزيادة حتى يصير أضعافًا؛ وهو تشنيع لصورة الاستغلال الشائعة لا قيد يجيز الربا القليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص730، تحت «دلالة وصف الربا المنهي عنه في كونه أضعافًا مضاعفة».","url":""}]},{"id":"s3-462","number":462,"surah":3,"verses":[130,200],"references":[{"surah":3,"verses":[130,200]}],"verseLabel":"آل عمران: 130؛ آل عمران: 200","question":"لماذا خُتم النهي عن الربا وخُتمت السورة معًا بـ﴿واتقوا الله لعلكم تفلحون﴾؟","answer":"في آل عمران: 130: لما كان الربا يغري بربح عاجل، أمرهم بتقوى الله وترك ما حرم، وربط الفلاح الحقيقي بالطاعة لا بتكثير المال؛ فسلامة الدين والمآل هي الربح الباقي.\n\nفي آل عمران: 130؛ آل عمران: 200: في آية الربا تربط الخاتمة الفلاح بتقوى الطمع المالي، وفي آخر السورة تجمع التقوى الصبر والمصابرة والرباط؛ فتكرارها يجعل التقوى أصل الفلاح في مجاهدة المال وفي مجاهدة العدو والنفس.","sources":[{"label":"[آل عمران: 130] موسوعة التفسير البلاغي، ج5، ص726–738","url":""},{"label":"[آل عمران: 130؛ آل عمران: 200] موسوعة التفسير البلاغي، ج5، ص726–738؛ ج6، ص543–564","url":""}]},{"id":"s3-464","number":464,"surah":3,"verses":[131],"references":[{"surah":3,"verses":[131]}],"verseLabel":"آل عمران: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿واتقوا النار التي أعدت للكافرين﴾ للمؤمنين؟","answer":"حُذر المؤمنون من نار أعدت للكافرين كي لا يسلكوا سبيلهم في الربا والعصيان، وليشتد زجرهم عن المعصية؛ ولا يلزم من الوعيد أن كل من وقع في ذنب الربا صار كافرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص732–733، تحت «دلالة تعريف لفظة ﴿النار﴾ باللام والصلة».","url":""}]},{"id":"s3-465","number":465,"surah":3,"verses":[131],"references":[{"surah":3,"verses":[131]}],"verseLabel":"آل عمران: 131","question":"لماذا بُني ﴿أعدت﴾ للمجهول؟","answer":"حُذف الفاعل لأنه معلوم من العقيدة والسياق، ووجه الاهتمام إلى النار نفسها وإلى كونها قد أعدت وفرغ من إعدادها؛ فيشتد الإحساس بيقين الوعيد وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص733، تحت «سر بناء الفعل للمفعول في وصف النار».","url":""}]},{"id":"s3-466","number":466,"surah":3,"verses":[132],"references":[{"surah":3,"verses":[132]}],"verseLabel":"آل عمران: 132","question":"لماذا جمع بين طاعة الله وطاعة الرسول بعد النهي عن الربا؟","answer":"طاعة الله امتثال أصل التحريم، وطاعة الرسول قبول بيانه وتطبيقه؛ فسد الطريق على من يدعي الإيمان ثم يرد الحكم العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص733–734، تحت «فائدة عطف طاعة الرسول ﷺ على طاعة الله سبحانه وتعالى».","url":""}]},{"id":"s3-468","number":468,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿وسارعوا إلى مغفرة من ربكم وجنة﴾، وكيف يُسارَع إلى المغفرة؟","answer":"لا تكون المسارعة إلى المغفرة ذاتها حركة مكانية، بل إلى أسبابها من التوبة والطاعات؛ وصورت الأعمال سباقًا إلى غاية عظيمة لتحض على المبادرة والتنافس وعدم التسويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738، تحت «سر التعبير بصيغة المفاعلة في ﴿وسارعوا﴾».","url":""}]},{"id":"s3-469","number":469,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"لماذا قدّم المغفرة على الجنة؟","answer":"المغفرة تزيل مانع الدخول أولًا، ثم تأتي الجنة غايةً بعد السلامة من الذنب؛ فرتب النظم التخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص741، تحت «نكتة تقديم المغفرة على الجنة»","url":""}]},{"id":"s3-470","number":470,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"لماذا وصف الجنة بأن عرضها السماوات والأرض ولم يذكر طولها؟","answer":"لأن العرض أقصر البعدين عادة؛ فإذا بلغ هذا الاتساع كان الطول أعظم، والمقصود تقريب سعة لا يحيط بها القياس البشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص741، تحت «براعة اصطفاء لفظ ﴿العرض﴾ وصفًا للجنة».","url":""}]},{"id":"s3-471","number":471,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿أعدت للمتقين﴾ في مقابل ﴿أعدت للكافرين﴾؟","answer":"قابل إعداد الجنة للمتقين بإعداد النار للكافرين لتمييز مآل الطريقين؛ وخص المتقين تشريفًا لأن صفاتهم الآتية جعلتهم أهل الجنة، كما أن مشابهة الكافرين تقرب صاحبها من نصيب وعيدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص743، تحت «بلاغة الفصل بالاستئناف في الفاصلة».","url":""}]},{"id":"s3-472","number":472,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]},{"surah":57,"verses":[21]}],"verseLabel":"آل عمران: 133؛ الحديد: 21","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿وسارعوا﴾، وقوله تعالى في الحديد ﴿سابقوا﴾؟","answer":"المسارعة تركز على مبادرة الإنسان إلى أسباب المغفرة عقب أوامر التقوى والإنفاق، أما المسابقة فتضيف وجود متنافسين وطلب السبق، وهو أنسب بسياق الحديد الذي يعالج التفاوت في الإيمان والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص177–178، تحت «دلالة صيغة المفاعلة في قوله: ﴿سابقوا﴾».","url":""}]},{"id":"s3-473","number":473,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]},{"surah":57,"verses":[21]}],"verseLabel":"آل عمران: 133؛ الحديد: 21","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿جنة عرضها السماوات والأرض﴾، وفي الحديد ﴿جنة عرضها كعرض السماء والأرض﴾؟","answer":"آل عمران في مقام الحث المباشر فأثبتت السعة للجنة إبلاغًا في التعظيم، أما الحديد فجاءت بكاف التشبيه لتقريب ما لا يحيط به الحس إلى أوسع مشهود يعرفه المخاطب؛ والعبارتان تدلان على سعة خارجة عن القياس المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص192–193، تحت «بلاغة الاتفاق والاختلاف بين آية الحديد وآية آل عمران».","url":""}]},{"id":"s3-474","number":474,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"لماذا قدّم الإنفاق في السراء والضراء على كظم الغيظ والعفو؟","answer":"بدأ ببذل المال في الحالين لأنه علامة عملية ظاهرة للتقوى، ثم ارتقى إلى ضبط النفس والعفو وهما أشق باطنًا؛ فجمع الإحسان بالمال والإحسان إلى المسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص750–751، تحت «بلاغة الافتتاح بذكر الإنفاق».","url":""}]},{"id":"s3-475","number":475,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿الكاظمين الغيظ﴾، وما صورة كظم الغيظ؟","answer":"أصل الكظم ملء السقاء وشد فمه حتى لا يفيض؛ فصور الغيظ شيئًا ملأ النفس ثم حبسه صاحبه ومنع آثاره من الخروج، مع قدرته على الانتقام، وذلك أبلغ من مجرد عدم الغضب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص753، تحت «حسن اختيار لفظ الغيظ دون الغضب».","url":""}]},{"id":"s3-476","number":476,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"لماذا عطف ﴿العافين عن الناس﴾ على كظم الغيظ؟","answer":"كظم الغيظ يمنع فوران الغضب وآثاره، أما العفو فيترك مؤاخذة المسيء وعقوبته؛ فعطفه يرفع الخلق من ضبط النفس عن الانتقام إلى محو حق المؤاخذة والإحسان إلى الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص754، تحت «توجيه التعبير عن العفو باسم الفاعل».","url":""}]},{"id":"s3-477","number":477,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"لماذا ختم الصفات بـ﴿والله يحب المحسنين﴾ مع أن أولها في المتقين؟","answer":"بدأ بوصفهم المتقين لأن التقوى تؤهل للجنة، ثم سماهم محسنين لأن الإنفاق والكظم والعفو إتيان للأعمال على وجهها الحسن؛ فجمعت الآية ترك المنكر وفعل الخير وختمت بمحبة الله جزاء الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص754–755، تحت «علة الجمع بين صفتي التقوى والإحسان».","url":""}]},{"id":"s3-478","number":478,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿فعلوا فاحشة أو ظلموا أنفسهم﴾، وما الفرق بينهما؟","answer":"الفاحشة ذنب عظيم بالغ القبح، أما ظلم النفس فأعم من كل معصية يؤاخذ بها الإنسان، وقيل هو ما دون الكبيرة؛ فعطف العام على الخاص ليشمل وقوع المتقين في الذنب على تفاوت درجاته ثم مبادرتهم للتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص761، تحت «الفرق بين الفاحشة وبين ظلم النفس».","url":""}]},{"id":"s3-479","number":479,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ذكروا الله فاستغفروا لذنوبهم﴾، وما أثر الفاء؟","answer":"لما استحضروا جلال الله وحقه ووعيده عقب الذنب نشأ عن هذا الذكر الاستغفار مباشرة؛ فالفاء تفيد سرعة التعقيب، وتصور أن الذكر الصادق لا بد أن يثمر رجوعًا عاجلًا لا تسويفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص762، تحت «نكتة العطف بالفاء في قوله: ﴿فاستغفروا﴾».","url":""}]},{"id":"s3-480","number":480,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"لماذا اعترض بقوله ﴿ومن يغفر الذنوب إلا الله﴾؟","answer":"الاعتراض استفهام إنكاري يقرر انفراد الله بالمغفرة: لا ملجأ للمذنب إلا إليه ولا ذنب يتعاظم على عفوه؛ فوسط وصف التائبين تطمين لهم وحث على ألا يمنعهم عظم الذنب من الاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص763، تحت «بلاغة إظهار لفظ الذنوب في موقع الإضمار».","url":""}]},{"id":"s3-481","number":481,"surah":3,"verses":[135],"references":[{"surah":3,"verses":[135]}],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم يصروا على ما فعلوا وهم يعلمون﴾؟","answer":"صفة المتقين ليست العصمة من الزلل، بل ألا يلازموا الذنب بعد تذكرهم وعلمهم بقبحه ونهي الله عنه؛ فـ﴿يصروا﴾ تصور الثبات المتعمد عليه، و﴿وهم يعلمون﴾ تكشف قيام الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص763، تحت «سر تأخير نفي الإصرار على الاستغفار».","url":""}]},{"id":"s3-482","number":482,"surah":3,"verses":[136],"references":[{"surah":3,"verses":[136]}],"verseLabel":"آل عمران: 136","question":"لماذا سميت المغفرة والجنات ﴿جزاءهم﴾؟","answer":"سميت المغفرة والجنات جزاءً لأنها الثمرة التي وعدها الله لمن اتصف بالإنفاق والكظم والعفو، وإذا أذنب بادر إلى الاستغفار ولم يصر؛ فوافق الثواب عملهم مع بقائه فضلًا وتكريمًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص764–765، تحت «شرح المفردات» في بيان ﴿جزاؤهم مغفرة من ربهم وجنات﴾.","url":""}]},{"id":"s3-483","number":483,"surah":3,"verses":[136],"references":[{"surah":3,"verses":[136]},{"surah":9,"verses":[89]},{"surah":14,"verses":[23]},{"surah":16,"verses":[31]},{"surah":18,"verses":[31]}],"verseLabel":"آل عمران: 136؛ التوبة: 89؛ إبراهيم: 23؛ النحل: 31؛ الكهف: 31","question":"ما سرّ التعبير بجريان الأنهار ﴿من تحتها﴾، وما دلالة العدول إلى ﴿من تحتهم﴾ في الكهف؟","answer":"في آل عمران: 136: ﴿من تحتها﴾ ترسم الأنهار جارية تحت أشجار الجنان وقصور أهلها، ملازمةً لمواضع نعيمهم وتحت تصرفهم؛ أما «فيها» فتثبت وجودها داخل الجنة دون هذه الصورة المكانية الدقيقة.\n\nفي التوبة: 89: التعبير بالجريان من تحتها يصور الأنهار دائمة الحركة قريبة من قصورها وأشجارها وتحت تصرف أهلها، وهو أبلغ من مجرد وجودها.\n\nفي إبراهيم: 23: تقديم الجار يصور الأنهار محيطة بأسفل الجنات ملازمة لها، فيكتمل مشهد النعيم.\n\nفي النحل: 31: تصور الماء ملازمًا لأصول الجنات، لا طارئًا يحتاج إلى جلب.\n\nفي الكهف: 31: أضيف ﴿تحت﴾ إلى ضمير أهل الجنة زيادة في تقرير ملكهم للجنات واستحقاقهم للبشارة؛ فاجتمعت مؤكدات الخبر لإتمام بشارتهم والتعريض بإغاظة المشركين.","sources":[{"label":"[آل عمران: 136] موسوعة التفسير البلاغي، ج5، ص764–769","url":""},{"label":"[التوبة: 89] موسوعة التفسير البلاغي، ج18، ص35–38","url":""},{"label":"[إبراهيم: 23] موسوعة التفسير البلاغي، ج24 ص773","url":""},{"label":"[النحل: 31] موسوعة التفسير البلاغي، ج26، ص322-334","url":""},{"label":"[الكهف: 31] ج29 ص759–761","url":""}]},{"id":"s3-484","number":484,"surah":3,"verses":[136],"references":[{"surah":3,"verses":[136]}],"verseLabel":"آل عمران: 136","question":"لماذا ختم بـ﴿ونعم أجر العاملين﴾؟","answer":"﴿نعم﴾ تمدح وتعظم ما سبق من المغفرة والجنات والخلود، وتسميه أجر العاملين لتربط الوعد بالعمل وتستنهض السامع إلى صفاتهم؛ فهو خير جزاء لمن لم يقف عند التمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص767، تحت «بلاغة اختيار لفظ الأجر للجزاء».","url":""}]},{"id":"s3-485","number":485,"surah":3,"verses":[137],"references":[{"surah":3,"verses":[137]}],"verseLabel":"آل عمران: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خلت من قبلكم سنن﴾، وكيف تخلو السنن؟","answer":"السنن قواعد ثابتة لا تفنى، وإنما خلت أي مضت قبلهم وقائعها وأممها التي جرت عليها؛ فنسب المضي إلى السنن مجازًا، تذكيرًا بتكرر سنة الله في ابتلاء المؤمنين ثم نصرهم وعاقبة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص769–770، تحت «شرح المفردات».","url":""}]},{"id":"s3-486","number":486,"surah":3,"verses":[137],"references":[{"surah":3,"verses":[137]}],"verseLabel":"آل عمران: 137","question":"لماذا أُمروا بالسير في الأرض والنظر في عاقبة المكذبين؟","answer":"لينتقل خبر السنن من السماع إلى الشاهد التاريخي، فيروا أن تداول الأيام لا يبطل عاقبة التكذيب وأن هزيمة عابرة لا تعني خذلان الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص772، تحت «بلاغة المجاز المرسل في جملة السير في الأرض».","url":""}]},{"id":"s3-488","number":488,"surah":3,"verses":[138],"references":[{"surah":3,"verses":[138]}],"verseLabel":"آل عمران: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿هذا بيان للناس وهدى وموعظة للمتقين﴾، فجعل البيان للناس والهدى للمتقين؟","answer":"البيان عام للناس، أما الهدى والموعظة فخُص بهما المتقون لأنهم ينتفعون بهما ويستجيبون؛ فالهدى هنا دلالة توصل إلى الغاية، وهذا الأثر يتحقق في المتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص778، تحت عنوان «سر تخصيص المتقين بالهدى، والموعظة»","url":""}]},{"id":"s3-489","number":489,"surah":3,"verses":[138],"references":[{"surah":3,"verses":[138]}],"verseLabel":"آل عمران: 138","question":"لماذا عطف الهدى والموعظة على البيان؟","answer":"البيان يكشف الحقيقة للعقول كلها، والهدى يدل المستجيب إلى الطريق، والموعظة تحرك القلب للعمل؛ فليست الألفاظ مترادفة بل مراحل أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص778–781، تحت «البيان، والهدى، والموعظة».","url":""}]},{"id":"s3-490","number":490,"surah":3,"verses":[139],"references":[{"surah":3,"verses":[139]}],"verseLabel":"آل عمران: 139","question":"لماذا جمع بين النهي عن الوهن والحزن؟","answer":"نُهوا عن الوهن، وهو ضعف العزيمة والإرادة المؤدي إلى العجز، وعن الحزن، وهو شدة الأسف والانكسار؛ ليعالج أثر أُحد في قوتهم العملية والنفسية معًا، فيثبتوا ولا يستسلموا للهزيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص784، تحت «الحزن والهم والبث»","url":""}]},{"id":"s3-491","number":491,"surah":3,"verses":[139],"references":[{"surah":3,"verses":[139]}],"verseLabel":"آل عمران: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنتم الأعلون إن كنتم مؤمنين﴾؟","answer":"قرر علوهم بالإيمان في الحجة والعاقبة والنصر ليزيل أثر الهزيمة، وعلق بـ﴿إن كنتم مؤمنين﴾ تهييجًا لهم أن يحققوا مقتضى إيمانهم بالثبات؛ فهو شرط حث لا شك في أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص783، تحت «بلاغة إيراد الفاصلة جملة شرط».","url":""}]},{"id":"s3-492","number":492,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿إن يمسسكم قرح فقد مس القوم قرح مثله﴾؟","answer":"ذكّرهم أن جرح أُحد لم ينفردوا به، فقد أصاب عدوهم مثله في بدر؛ والتعبير بالمس يصور القرح إصابة طارئة لا نهاية الطريق، فيسليهم ويمنع أن يتخذوا الجولة دليل خذلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص790، تحت «بلاغة الاستعارة في التعبير بالمس».","url":""}]},{"id":"s3-493","number":493,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وتلك الأيام نداولها بين الناس﴾، وكيف تُداوَل الأيام؟","answer":"صوّر الأيام دولاً تنتقل بين الفرق؛ ليبين أن الغلبة لا تثبت لأحد، وأن تداولها ميدان لتمييز الإيمان واتخاذ الشهداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص792، تحت «وجه المجاز في لفظ التداول».","url":""}]},{"id":"s3-494","number":494,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وليعلم الله الذين آمنوا﴾ مع أن الله يعلمهم قبل الامتحان؟","answer":"ليس المراد حدوث علم بعد جهل، فعلم الله سابق؛ بل أن يظهر في الواقع من يثبت إيمانه عند الامتحان، فيتميز للناس ويتعلق به الجزاء على عمل مشهود لا على مجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص793، تحت «وجه إطلاق لفظ علم الله على المعلوم».","url":""}]},{"id":"s3-495","number":495,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿ويتخذ منكم شهداء﴾، دون أن يقال: ويجعل بعضكم شهداء؟","answer":"﴿يتخذ﴾ تفيد أن الله يصطفي من المؤمنين شهداء ويكرمهم بهذه المنزلة، لا مجرد أن تقع عليهم صفة الشهادة؛ و﴿منكم﴾ تبين أن هذا الاصطفاء يقع لبعض الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص794، تحت «علة اختيار لفظ الاتخاذ».","url":""}]},{"id":"s3-496","number":496,"surah":3,"verses":[140],"references":[{"surah":3,"verses":[140]}],"verseLabel":"آل عمران: 140","question":"لماذا خُتمت الآية بـ﴿والله لا يحب الظالمين﴾؟","answer":"لما ذكر تداول الأيام وقد يغلب الظالمون في جولة، نفى أن تكون إدالتهم دليل محبة أو رضا؛ إنما هي لحكمة الابتلاء، والله لا يحب ظلمهم ولن يجعل العاقبة الدائمة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص794، تحت «وجه نفي المحبة بالمضارع المنفي».","url":""}]},{"id":"s3-497","number":497,"surah":3,"verses":[141],"references":[{"surah":3,"verses":[141]}],"verseLabel":"آل عمران: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿وليمحص الله الذين آمنوا ويمحق الكافرين﴾؟","answer":"التمحيص تنقية الشيء من شوائبه، كتنقية الذهب بالنار، فناسب المؤمنين إذ تطهرهم المحنة؛ والمحق إنقاص الشيء حتى يذهب، فناسب الكافرين. وتقارب اللفظين يشدد مقابلة التطهير بالإهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص13–14، تحت «بلاغة الاستعارة في قوله: ﴿وليمحص الله﴾، ﴿ويمحق الكافرين﴾».","url":""}]},{"id":"s3-498","number":498,"surah":3,"verses":[142],"references":[{"surah":3,"verses":[142]}],"verseLabel":"آل عمران: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿أم حسبتم أن تدخلوا الجنة﴾ في صورة سؤال؟","answer":"جاء استفهامًا إنكاريًا ليبطل ظن أن الجنة تنال بالدعوى والتمني قبل اختبار الجهاد والصبر؛ وصيغة السؤال تجعل السامع يراجع حسبانه ويقر بأن الثمن عمل وثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص19، تحت «دلالة التعبير بـ(أم) في قوله تعالى: ﴿أم حسبتم﴾».","url":""}]},{"id":"s3-499","number":499,"surah":3,"verses":[142],"references":[{"surah":3,"verses":[142]}],"verseLabel":"آل عمران: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين﴾؟","answer":"أي لم يظهر بعد في واقع الامتحان جهاد المجاهدين وصبر الصابرين ظهورًا يتعلق به الجزاء، مع توقع حصوله؛ فـ﴿لما﴾ تنفي الوقوع إلى الآن لا علم الله السابق، وتقرر أن الجنة لا تنال قبل تحقق العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص20، تحت «نكتة التعبير بـ(لما)».","url":""}]},{"id":"s3-500","number":500,"surah":3,"verses":[142],"references":[{"surah":3,"verses":[142]}],"verseLabel":"آل عمران: 142","question":"لماذا غُيّرت الصياغة من ﴿الذين جاهدوا﴾ إلى ﴿الصابرين﴾؟","answer":"﴿الذين جاهدوا﴾ تبرز وقوع فعل الجهاد منهم في ميدان الامتحان، أما ﴿الصابرين﴾ فاسم فاعل يصور الصبر صفة ثابتة راسخة؛ لأن الجهاد موقف، والصبر خُلُق ملازم يحتاجه في الموقف وبعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص21، تحت «مناسبة المخالفة في التعبير في قوله ﴿جاهدوا﴾ و﴿الصابرين﴾».","url":""}]},{"id":"s3-501","number":501,"surah":3,"verses":[143],"references":[{"surah":3,"verses":[143]}],"verseLabel":"آل عمران: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد كنتم تمنون الموت﴾ لا: الشهادة؟","answer":"كانوا يتمنون لقاء العدو طلبًا لما يفضي إليه من الشهادة، فعبّر بالموت لأنه الحقيقة الشديدة التي عاينوها ولأن مجرد التمني لا يثبت لصاحبه منزلة الشهيد؛ فواجههم بلازم الأمنية حين حضر الخطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص28، تحت «دلالة التمني في قوله تعالى: ﴿ولقد كنتم تمنون الموت﴾».","url":""}]},{"id":"s3-502","number":502,"surah":3,"verses":[143],"references":[{"surah":3,"verses":[143]}],"verseLabel":"آل عمران: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد رأيتموه وأنتم تنظرون﴾، وما الفرق بين الرؤية والنظر؟","answer":"النظر أول توجيه العين إلى المشهد وتأمله، والرؤية إدراك صورته والنفاذ إلى حقيقته؛ فقد عاينوا الموت في القتلى أمامهم وأدركوا رهبة حقيقته، فجمع اللفظان المشاهدة بالبصر والاعتبار بالبصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص31، تحت «النظر والرؤية».","url":""}]},{"id":"s3-503","number":503,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿وما محمد إلا رسول﴾ بالقصر؟","answer":"القصر يقرر أنه رسول بشر أدى البلاغ، لا أن الرسالة متوقفة على خلوده؛ فموته أو قتله لا يسوغ ترك الدين. وجاء باسم الرسالة لأنها المهمة الباقية التي يجب اتباعها بعد غياب حاملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص36، تحت «سر التعبير بأسلوب القصر في قوله تعالى: ﴿وما محمد إلا رسول﴾».","url":""}]},{"id":"s3-504","number":504,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خلت من قبله الرسل﴾، دون أن يقال: الأنبياء؟","answer":"اختير ﴿الرسل﴾ لأن المقام في بقاء البلاغ والدين بعد وفاة المبلّغ؛ فمحمد ﷺ واحد من رسل مضوا بعد أداء رسالاتهم، ولم تبطل رسالاتهم بموتهم. أما «الأنبياء» فلا يبرز وظيفة البلاغ بهذا الوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص37، تحت «مناسبة مجيء قوله تعالى: ﴿قد خلت من قبله الرسل﴾».","url":""}]},{"id":"s3-505","number":505,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا قدّم ﴿مات﴾ على ﴿قتل﴾ في ﴿أفإن مات أو قتل﴾؟","answer":"قدم الموت لأنه المصير المشترك الذي خلت به الرسل، مع أن إشاعة القتل هي التي أثارت الفتنة يوم أُحد؛ وفي التقديم إشعار بأن النبي ﷺ سيموت موتًا لا قتلًا، والحكمان سواء في عدم جواز الانقلاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص38، تحت «سر تقديم الموت على القتل في قوله تعالى: ﴿مات أو قتل﴾».","url":""}]},{"id":"s3-506","number":506,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا صوّر الارتداد بقوله ﴿انقلبتم على أعقابكم﴾؟","answer":"صوّر الردة رجوعًا جسديًا إلى الخلف بعد التقدم في الطريق؛ فتبدو خسارة من يربط الدين بحياة شخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص44–45، تحت «الانقلاب، والارتداد، والرجوع، والعود».","url":""}]},{"id":"s3-507","number":507,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا كرر فعل الانقلاب في ﴿ومن ينقلب على عقبيه فلن يضر الله شيئًا﴾؟","answer":"ذُكر الانقلاب أولًا في سؤال يوبخ الجماعة على ربط الدين بحياة الرسول، ثم أعيد في شرط عام يشمل كل فرد ويبين عاقبته: من يرتد لا ينقص ملك الله ولا دينه شيئًا، وإنما يخسر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص39–40، تحت «براعة التعبير في قوله: ﴿ومن ينقلب على عقبيه فلن يضر الله شيئًا﴾».","url":""}]},{"id":"s3-508","number":508,"surah":3,"verses":[144],"references":[{"surah":3,"verses":[144]}],"verseLabel":"آل عمران: 144","question":"لماذا ختم بـ﴿وسيجزي الله الشاكرين﴾ لا الصابرين أو الثابتين؟","answer":"الثابت بعد موت الرسول يشكر الله على نعمة الإسلام باتباع الرسالة وعدم ربطها بشخص المبلّغ؛ لذلك قابل المنقلبين بالشاكرين، فالشكر هنا ثبات وطاعة وحفظ للنعمة لا مجرد قول باللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص40، تحت «حسن التذييل في قوله تعالى: ﴿وسيجزي الله الشاكرين﴾».","url":""}]},{"id":"s3-509","number":509,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان لنفس أن تموت إلا بإذن الله﴾؟","answer":"نفت الآية أن تموت أي نفس بسبب مستقل عن مشيئة الله ووقتها المقدر؛ لتثبت الفارين أن الإقدام لا يقدم الأجل والفرار لا يؤخره، فالحياة والموت بيد الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص52، تحت «بلاغة أسلوب القصر بقوله: ﴿وما كان لنفس أن تموت إلا بإذن الله﴾».","url":""}]},{"id":"s3-510","number":510,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"لماذا سمّى أجل الموت ﴿كتابًا مؤجلًا﴾؟","answer":"سمي الأجل كتابًا لأنه قدر مثبت مكتوب، ووصف بالمؤجل لأن لكل نفس وقتًا معينًا ينتهي إليه عمرها؛ فالصورة تمنح الأجل معنى الثبوت والانضباط الذي لا تغيره أسباب الخوف والقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص54، تحت «دلالة التعبير في قوله تعالى: ﴿كتابًا مؤجلًا﴾».","url":""}]},{"id":"s3-511","number":511,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"لماذا كرر ﴿نؤته منها﴾ في ثواب الدنيا وثواب الآخرة؟","answer":"أعيد ﴿نؤته منها﴾ ليستقل كل قصد بجزائه: من حصر إرادته في الدنيا أعطي نصيبًا منها، ومن أراد الآخرة أعطي من ثوابها؛ فالتكرار يبرز اختلاف الغايتين والمآلين لا مجرد وقوع العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص54، تحت «مناسبة التعبير في قوله تعالى: ﴿ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الآخرة نؤته منها﴾».","url":""}]},{"id":"s3-512","number":512,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"لماذا خُتمت الآية مرة أخرى بـ﴿وسنجزي الشاكرين﴾؟","answer":"أعيد وعد الشاكرين ليثبت أن أصحاب القصد الأعلى هم الذين عرفوا نعمة الله فاستعملوها في طاعته ولم يبيعوا الدين بعاجل الدنيا؛ والتكرار يصل ثباتهم عند موت الرسول بحسن اختيارهم للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص55، تحت «حسن التذييل في قوله: ﴿وسنجزي الشاكرين﴾».","url":""}]},{"id":"s3-513","number":513,"surah":3,"verses":[146],"references":[{"surah":3,"verses":[146]}],"verseLabel":"آل عمران: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿وكأين من نبي قاتل معه ربيون كثير﴾؟","answer":"﴿كأين﴾ تفيد كثرة الوقائع: كم من نبي قاتل معه جماعات كثيرة من الربانيين فلم تكسرهم المصائب؛ فليست سابقة أُحد بدعًا، بل نموذجًا تقابله سوابق كثيرة تدعو أمة محمد إلى الاقتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص62، تحت «دلالة التعبير بلفظ ﴿كأين﴾ في قوله تعالى: ﴿وكأين من نبي﴾».","url":""}]},{"id":"s3-514","number":514,"surah":3,"verses":[146],"references":[{"surah":3,"verses":[146]}],"verseLabel":"آل عمران: 146","question":"لماذا جمع بين ﴿فما وهنوا﴾ و﴿وما ضعفوا﴾ و﴿وما استكانوا﴾؟","answer":"نفى فتور العزم، ثم ضعف القدرة، ثم الخضوع للعدو؛ فاستوعب مراحل الانكسار النفسية والعملية والظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص69، تحت «الضعف والاستكانة والوهن».","url":""}]},{"id":"s3-515","number":515,"surah":3,"verses":[146],"references":[{"surah":3,"verses":[146]}],"verseLabel":"آل عمران: 146","question":"لماذا ختم بـ﴿والله يحب الصابرين﴾؟","answer":"لأن عدم الوهن والضعف والاستكانة هو صورة الصبر عند الشدة، فسمّاهم صابرين وختم بمحبة الله لهم؛ لينقل الثبات من مجرد احتمال الألم إلى منزلة ينال بها العبد محبة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص68، تحت «في جملة التذييل فوائد لغوية وبلاغية في قوله تعالى: ﴿والله يحب الصابرين﴾».","url":""}]},{"id":"s3-516","number":516,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"لماذا حُصر قولهم في الدعاء ﴿وما كان قولهم إلا أن قالوا﴾؟","answer":"بالنفي والاستثناء حصر قول الربانيين عند الشدة في الدعاء، فلم يتكلموا بجزع أو اعتراض أو استسلام؛ فكان أول ردهم محاسبة النفس وطلب العون من الله، لا لوم القدر أو التراجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص75، تحت «مناسبة مجيء القصر بطريق النفي والاستثناء».","url":""}]},{"id":"s3-517","number":517,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"لماذا بدأوا بطلب مغفرة الذنوب قبل طلب تثبيت الأقدام والنصر؟","answer":"رأوا الذنب سببًا يحجب التأييد، فبدؤوا بإصلاح الصلة بالله، ثم سألوا الثبات، ثم ثمرة الثبات وهي النصر؛ فرتبوا الدعاء من الداخل إلى الخارج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص76، تحت «مناسبة الترتيب في الدعاء».","url":""}]},{"id":"s3-518","number":518,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"ما دلالة عطف ﴿وإسرافنا في أمرنا﴾ على ﴿ذنوبنا﴾ في دعائهم؟","answer":"طلبوا مغفرة الذنوب عامة، ثم خصوا الإسراف، وهو مجاوزة الحد والتفريط في الأمر، لعظم أثره في أسباب الهزيمة؛ فجمعوا بين تقصيرهم كله وبين ما تجاوزوا فيه حدود الصواب خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص76، تحت «نكتة عطف الخاص على العام».","url":""}]},{"id":"s3-519","number":519,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"لماذا صوّر الثبات بقوله ﴿وثبت أقدامنا﴾؟","answer":"ثبات الأقدام كناية عن ثبات القلوب والصفوف عند لقاء العدو؛ فمن اضطرب باطنه زلت قدمه وفر، ومن رسخ يقينه ثبت مكانه، فصورت القوة المعنوية في هيئة جسدية مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص77، تحت «دلالة ﴿وثبت أقدامنا﴾ بين أن يكون مجازًا مرسلًا بغرض الكناية وأن يكون استعارة».","url":""}]},{"id":"s3-520","number":520,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"ما دلالة الفاء في قوله تعالى: ﴿فآتاهم الله ثواب الدنيا وحسن ثواب الآخرة﴾؟","answer":"تدل الفاء على أن إعطاءهم ثواب الدارين مترتب على دعائهم وصبرهم وإخلاصهم لله، وفي دلالتها على التعقيب إشعار بتعجيل قبول دعائهم والاستجابة لطلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص83، تحت عنوان «دلالة الفاء في قوله: ﴿فآتاهم الله ثواب الدنيا﴾»","url":""}]},{"id":"s3-778","number":778,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"ما المراد بثواب الدنيا وثواب الآخرة في جزاء الثابتين مع أنبيائهم؟","answer":"يدل سياق الثبات في القتال على أن ثواب الدنيا هو النصر والغنيمة والعز وطيب الذكر، وأن ثواب الآخرة هو الجنة والنعيم الدائم؛ فالسياق يبين نوع الجزاء في كل دار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص84، تحت عنوان «دلالة قوله تعالى: ﴿ثواب الدنيا﴾ و﴿حسن ثواب﴾»","url":""}]},{"id":"s3-521","number":521,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"لماذا وصف ثواب الآخرة وحده بـ﴿حسن﴾؟","answer":"خص ثواب الآخرة بالحسن لأنه كامل باق لا يشوبه ألم ولا يعقبه زوال، أما ثواب الدنيا فعلى جلاله محدود وقد تخالطه المنغصات؛ فالتقييد يقرر تفاضل الجزاءين لا نفي الخير عن الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص84، تحت «نكتة وصف ثواب الآخرة بالحسن وتركه في وصف الدنيا».","url":""}]},{"id":"s3-522","number":522,"surah":3,"verses":[148],"references":[{"surah":3,"verses":[148]}],"verseLabel":"آل عمران: 148","question":"لماذا ختم بـ﴿والله يحب المحسنين﴾ بعد وصف الصابرين؟","answer":"وصفوا أولًا بالصابرين لثباتهم عند المصاب، ثم بالمحسنين لأنهم أحسنوا الصلة بالله والدعاء والجهاد؛ فالإحسان أوسع من الصبر، وختم بالمحبة بعد ذكر الثواب ليضيف رضا الله إلى الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص85، تحت «حسن التذييل في قوله تعالى: ﴿والله يحب المحسنين﴾».","url":""}]},{"id":"s3-523","number":523,"surah":3,"verses":[149],"references":[{"surah":3,"verses":[149]}],"verseLabel":"آل عمران: 149","question":"لماذا كرر النداء ﴿يا أيها الذين آمنوا﴾ قبل التحذير من طاعة الكافرين؟","answer":"جدد النداء لاستنفار الانتباه إلى خطر الطاعة العقدية، وناداهم بوصف الإيمان لأن مقتضاه ألا يسلموا قيادهم للكافرين الذين يردونهم عنه؛ فالصفة نفسها حجة التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص90، تحت «نكتة التعبير بالاسم الموصول وصلته في قوله: ﴿الذين آمنوا﴾».","url":""}]},{"id":"s3-524","number":524,"surah":3,"verses":[149],"references":[{"surah":3,"verses":[149]}],"verseLabel":"آل عمران: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿يردوكم على أعقابكم﴾ لا: عن دينكم؟","answer":"صوّر طاعتهم رجوعًا على الأعقاب: بعد أن تقدم المؤمن في طريق الهدى يدير ظهره ويرجع القهقرى إلى الكفر؛ فالتعبير يجسد قبح النكوص وخسارة المسافة التي قطعها، لا مجرد ترك مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص92، تحت «بلاغة قوله تعالى: ﴿يردوكم على أعقابكم﴾».","url":""}]},{"id":"s3-525","number":525,"surah":3,"verses":[149],"references":[{"surah":3,"verses":[149]}],"verseLabel":"آل عمران: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿فتنقلبوا خاسرين﴾ فجاء بالفاء؟","answer":"الفاء تفيد أن الخسران نتيجة مباشرة لطاعة الكافرين وما تسببه من الردة؛ و﴿تنقلبوا﴾ تصور تحولهم من عز الإيمان وربحه إلى حال الخاسرين، فلا فاصل بين النكوص وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص94، تحت «دلالة قوله: ﴿فتنقلبوا خاسرين﴾».","url":""}]},{"id":"s3-526","number":526,"surah":3,"verses":[150],"references":[{"surah":3,"verses":[150]}],"verseLabel":"آل عمران: 150","question":"لماذا أضرب عن طاعة الكافرين بقوله ﴿بل الله مولاكم﴾؟","answer":"أضربت ﴿بل﴾ عن طاعة الكافرين والاحتماء بهم، وأثبتت البديل الحاسم: الله هو وليكم المتكفل بأمركم ونصركم؛ فمن كانت له ولايته لم يطلب العزة عند أعدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص96، تحت «دلالة ﴿بل﴾ بين الإضراب الانتقالي والإبطالي».","url":""}]},{"id":"s3-527","number":527,"surah":3,"verses":[150],"references":[{"surah":3,"verses":[150]}],"verseLabel":"آل عمران: 150","question":"لماذا أفرد الولاية لله ثم قال ﴿وهو خير الناصرين﴾ بالجمع؟","answer":"أفرد الله بالولاية لأنه المتولي الحقيقي المستقل، ثم قال ﴿خير الناصرين﴾ فجمع جنس الناصرين باعتبار ما يجري من نصر على أيدي الملائكة والمؤمنين والأسباب؛ لكن نصرهم تابع ونصر الله أصل وخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص98، تحت «دلالة العطف في قوله: ﴿وهو خير الناصرين﴾».","url":""}]},{"id":"s3-528","number":528,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿سنلقي في قلوب الذين كفروا الرعب﴾، فجعل الرعب شيئًا يُلقى؟","answer":"جُسّم الرعب شيئًا يُلقى في مستقر الإدراك والإرادة، فيسبق انهيار القلب انهيار الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص101، تحت «بلاغة الاستعارة في قوله: ﴿سنلقي في قلوب الذين كفروا الرعب﴾»","url":""}]},{"id":"s3-529","number":529,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا قُدّم ﴿في قلوب الذين كفروا﴾ على ﴿الرعب﴾ في قوله تعالى: ﴿سنلقي في قلوب الذين كفروا الرعب﴾؟","answer":"قُدّم موضع إلقاء الرعب للاهتمام به قبل ذكر ما يُلقى فيه، وللتنبيه إلى أن القلب هو محل الرعب؛ فجاء التركيز على القلوب قبل التصريح بالرعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص102–103، تحت عنوان «بلاغة التقديم والتأخير»","url":""}]},{"id":"s3-530","number":530,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا عُلّل الرعب بقوله ﴿بما أشركوا بالله ما لم ينزل به سلطانًا﴾؟","answer":"أُلقي الرعب فيهم بسبب شركهم أو جزاءً مقابله؛ إذ اعتمدوا شركاء لا سلطان على ألوهيتهم، فخلا القلب من سند الحق والأمن. وبذلك ظهر أن الهزيمة ثمرة باطلهم لا تفوق عدد المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص103، تحت «مناسبة التعبير بقوله: ﴿ما لم ينزل به سلطانًا﴾».","url":""}]},{"id":"s3-531","number":531,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا سمّى الحجة ﴿سلطانًا﴾؟","answer":"سميت الحجة سلطانًا لأنها تتسلط بقوتها على العقل وتلزم الخصم كما يلزمه صاحب السلطة؛ ونفي إنزال السلطان يقرر أن الشرك لا يملك أدنى برهان من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص103–104، تحت «مناسبة التعبير بقوله: ﴿ما لم ينزل به سلطانًا﴾».","url":""}]},{"id":"s3-532","number":532,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿ومأواهم النار﴾، فجعل النار مأوى؟","answer":"المأوى في الأصل مكان يلجأ إليه المرء ويأمن، فجعل النار مأواهم على التهكم والمفارقة: إليها يصيرون ويستقرون، لكنها بدل الحماية عذاب دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص104، تحت «دلالة الجمع بين المأوى والمثوى».","url":""}]},{"id":"s3-533","number":533,"surah":3,"verses":[151],"references":[{"surah":3,"verses":[151]}],"verseLabel":"آل عمران: 151","question":"لماذا ختم بـ﴿وبئس مثوى الظالمين﴾ بعد ﴿مأواهم النار﴾؟","answer":"بعد أن عين النار مأوى لهم، حكم عليها بـ﴿بئس﴾ فبالغ في ذم المستقر، ووصف أهله بالظالمين لربط المصير بسببه؛ فليست إعادة للنار، بل تقبيح للمحل والحال فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص105، تحت «حسن التذييل في قوله: ﴿وبئس مثوى الظالمين﴾».","url":""}]},{"id":"s3-534","number":534,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد صدقكم الله وعده﴾ مع أن المسلمين لم ينتصروا آخر المعركة؟","answer":"صدقهم الله وعد النصر فعلًا في بداية المعركة حين استقاموا على أمر الرسول وأخذوا يحسون عدوهم؛ ثم انقلبت الجولة عند مخالفة الرماة. فالهزيمة لم تكن إخلافًا للوعد، بل أثر زوال شرط الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص111، تحت «تتابع التأكيد في قوله: ﴿ولقد صدقكم الله وعده﴾».","url":""}]},{"id":"s3-535","number":535,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا اختير ﴿تحسونهم﴾ في وصف قتل المشركين؟","answer":"﴿تحسونهم﴾ لا تصف مجرد إصابة أفراد، بل قتلًا ذريعًا مستأصلًا؛ والمضارع يصور المؤمنين يوقعونه بالعدو حالًا بعد حال بإذن الله، شاهدًا على تحقق الوعد قبل المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص111، تحت «مناسبة التعبير بقوله: ﴿تحسونهم﴾ دون ﴿تقتلونهم﴾».","url":""}]},{"id":"s3-536","number":536,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا فشلتم وتنازعتم في الأمر وعصيتم﴾، ورتب هذه الأفعال هكذا؟","answer":"بدأ الفشل في الباطن بخور العزم أمام الغنيمة، فأنتج التنازع في فهم البقاء أو النزول، ثم آل إلى العصيان العملي بترك الموقع؛ فالترتيب يكشف كيف تتحول علة نفسية إلى انقسام ثم مخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص114–115، تحت «دلالة الترتيب بين الأفعال في ﴿فشلتم وتنازعتم في الأمر وعصيتم﴾».","url":""}]},{"id":"s3-537","number":537,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما أراكم ما تحبون﴾ بدل: بعد النصر؟","answer":"لم يقل «بعد النصر» لأن الذي رأوه وشدهم كان أوسع: بوادر الغلبة والغنائم التي يحبونها؛ فالتعبير يكشف محل الاختبار، ويقرر أن المعصية وقعت بعد أن عاينوا فضل الله لا قبل ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص115، تحت «دلالة تعلق ﴿من بعد ما أراكم ما تحبون﴾ بـ﴿فشلتم﴾ وما نُسق عليه».","url":""}]},{"id":"s3-538","number":538,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿منكم من يريد الدنيا ومنكم من يريد الآخرة﴾؟","answer":"كشف التنازع اختلاف المقاصد: بعضهم حمله طلب الغنيمة على النزول، وبعضهم بقي طاعةً يريد الآخرة؛ وكرر ﴿منكم﴾ إنصافًا ليفصل الفريقين، فلا ينسب إرادة الدنيا إلى الجماعة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص117، تحت «بديع التفريق في قوله: ﴿منكم من يريد الدنيا ومنكم من يريد الآخرة﴾».","url":""}]},{"id":"s3-539","number":539,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا صُوّر الانصراف عن العدو بقوله ﴿ثم صرفكم عنهم﴾؟","answer":"الصرف ردهم عن الوجه الذي كانوا ماضين فيه، فبعد الإقبال على العدو والغلبة تحولوا إلى الانكفاء والفرار؛ و﴿ثم﴾ تبين أن ذلك جاء بعد مقدمات الفشل والتنازع والعصيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص117–118، تحت «دلالة ﴿ثم﴾ في ﴿ثم صرفكم عنهم﴾».","url":""}]},{"id":"s3-540","number":540,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ليبتليكم﴾ بعد ذكر المعصية والهزيمة؟","answer":"بيّن أن الصرف والهزيمة ابتلاء يكشفان مقدار الصبر والطاعة بعد الرخاء، لا حكم خذلان دائم؛ فالمحنة عرّفتهم ضعفهم وربتهم على أن النصر مشروط بالثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص118، تحت «بلاغة الاستعارة التمثيلية في قوله: ﴿ليبتليكم﴾».","url":""}]},{"id":"s3-541","number":541,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا أعقب العتاب فورًا بقوله ﴿ولقد عفا عنكم﴾؟","answer":"بعد تفصيل الفشل والتنازع والعصيان أكد العفو فورًا حتى لا يتحول العتاب إلى قنوط؛ فقد قبل ندمهم ولم يستأصلهم بالمؤاخذة، فجمع لهم كشف الخطأ وفتح باب الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص118، تحت «مناسبة التأكيد في قوله: ﴿ولقد عفا عنكم﴾».","url":""}]},{"id":"s3-542","number":542,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"لماذا ختم بـ﴿والله ذو فضل على المؤمنين﴾ لا: غفور لهم؟","answer":"لم يقتصر إحسان الله على ستر الذنب، بل عفا عنهم وأبقاهم في جماعة المؤمنين ورباهم وأيدهم؛ لذلك جاء ﴿ذو فضل﴾ أوسع من «غفور»، جامعًا العفو وغيره من وجوه الرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص119، تحت «حسن التذييل في قوله: ﴿والله ذو فضل على المؤمنين﴾».","url":""}]},{"id":"s3-543","number":543,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ تصعدون ولا تلوون على أحد﴾، وما صورة الصعود وعدم الالتفات؟","answer":"﴿تصعدون﴾ تستحضر اندفاعهم في جهة الجبل بعيدًا عن ساحة القتال، و﴿لا تلوون﴾ تصور أنهم لا يعطفون وجوههم ولا ينتظر بعضهم بعضًا؛ مشهد فرار استولى عليه الرعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص124، تحت «نكتة التعبير بالمضارع في ﴿إذ تصعدون ولا تلوون﴾».","url":""}]},{"id":"s3-544","number":544,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿والرسول يدعوكم في أخراكم﴾؟","answer":"أي إن الرسول بقي خلف جماعتكم المنهزمة يناديكم أن ارجعوا ولا تفروا، وأنتم ماضون لا تلتفتون؛ فالمشهد يبرز ثباته وانقطاع استجابتهم في لحظة الاضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص125، تحت «مناسبة التعبير بـ﴿والرسول﴾».","url":""}]},{"id":"s3-545","number":545,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿فأثابكم غمًا بغم﴾، وسمّى الغم ثوابًا؟","answer":"سمي الغم ثوابًا على أصل معنى الجزاء وبنبرة تقريع؛ فكان جزاء المخالفة غمًا متراكبًا، إما غمًا بسبب غم أحدثوه، أو غم القتل والجراح فوق غم خبر مقتل الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص127، تحت «دلالة تنكير قوله تعالى: ﴿غمًا بغم﴾».","url":""}]},{"id":"s3-546","number":546,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا نُكّر ﴿غمًا بغم﴾؟","answer":"يفيد التنكير التكثير والتفخيم؛ أي غمومًا كثيرة شديدة يتصل بعضها ببعض. فلا يلزم أن يكون المراد غمّين فقط، بل يصوّر التعبير تراكم الغموم وتعاظمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص127، تحت عنوان «دلالة تنكير قوله تعالى ﴿غمًا بغم﴾»","url":""}]},{"id":"s3-547","number":547,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا عُلّل ذلك بقوله ﴿لكيلا تحزنوا على ما فاتكم ولا ما أصابكم﴾؟","answer":"أذاقهم الغم المتراكم ليتمرنوا على احتمال الشدائد، فلا يستولي عليهم حزن ما فاتهم من الغنيمة والنصر ولا ما أصابهم من قتل وجراح؛ فالمحنة علاج لتعلق القلب بالمكسب والسلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص128، تحت «دلالة التعبير بقوله: ﴿لكيلا﴾».","url":""}]},{"id":"s3-548","number":548,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا قدّم ما فات على ما أصاب؟","answer":"لأن حزنهم بدأ بالغنيمة أو النصر الفائت ثم اشتد بالمصاب اللاحق؛ فرتب العلاج بحسب وقوع داعيي الحزن في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص129، تحت «بديع الطباق في قوله: ﴿ما فاتكم﴾ و﴿ما أصابكم﴾».","url":""}]},{"id":"s3-549","number":549,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"لماذا ختم بـ﴿والله خبير بما تعملون﴾؟","answer":"في الختام تهديد للمخالفين وتنبيه إلى أن الله يعلم أعمالهم وسيحاسبهم عليها. وخُص العمل بالذكر للتحذير مما وقع من الفرار وتولية الأدبار، مع أن علمه يشمل الأقوال والنيات أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص129، تحت عنوان «حسن التذييل بقوله: ﴿والله خبير بما تعملون﴾»","url":""}]},{"id":"s3-550","number":550,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]},{"surah":57,"verses":[23]}],"verseLabel":"آل عمران: 153؛ الحديد: 23","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿لكيلا تحزنوا على ما فاتكم﴾، وقوله تعالى في الحديد ﴿لكيلا تأسوا على ما فاتكم﴾؟","answer":"حزن أحد كان ألمًا حيًا متصلًا بهزيمة ومصاب قريب، فناسبه ﴿تحزنوا﴾؛ أما الحديد فيقرر قاعدة عامة في القدر ومتاع الدنيا، فاختير الأسى وهو حزن يمتد على الفائت ويتعلق به القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص224–225، تحت «توجيه المتشابه اللفظي بين آية الحديد وآية آل عمران».","url":""}]},{"id":"s3-551","number":551,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]},{"surah":57,"verses":[23]}],"verseLabel":"آل عمران: 153؛ الحديد: 23","question":"لماذا لم تذكر آل عمران بعد ﴿لكيلا تحزنوا على ما فاتكم﴾ مقابل الحديد ﴿ولا تفرحوا بما آتاكم﴾؟","answer":"مقام آل عمران علاج جرح أحد، فالعناية منصبة على الحزن بالمفقود والمصاب، ولم يكن مقام زهو بالنعمة؛ أما الحديد فيربي على التوازن العام بين الفقد والعطاء، فذكر طرفي الأسى والفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص224–225، تحت «توجيه المتشابه اللفظي بين آية الحديد وآية آل عمران».","url":""}]},{"id":"s3-552","number":552,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم أنزل عليكم من بعد الغم أمنة نعاسًا﴾، فجعل النعاس أمنة منزلة؟","answer":"صوّر الأمن عطاءً ينزل من عند الله بعد تراكم الغم، وبدل منه ﴿نعاسًا﴾ لأن غلبة النوم في موطن الخوف لا تكون إلا بعد سكون القلب؛ فصار النعاس أثر الأمنة المحسوس ودليلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص143–144، تحت «سر الجمع بين لفظي الأمنة والنعاس».","url":""}]},{"id":"s3-553","number":553,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا غشي النعاس طائفة ولم يغش الطائفة الأخرى؟","answer":"الأمنة نزلت على من صدق توكله فسكنت نفسه، أما من أهمتهم أنفسهم وساء ظنهم بالله فظل القلق مستوليًا عليهم؛ فصار النعاس كاشفًا لحال القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص145–146، تحت «بيان الفرق بين الطائفتين بالواو، وباختلاف الوصفين، وحكميهما الإعرابي».","url":""}]},{"id":"s3-554","number":554,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى عن الطائفة الأخرى ﴿قد أهمتهم أنفسهم﴾؟","answer":"أي استولى عليهم الاهتمام بأنفسهم وسلامتهم وحدها، فلم يشغلهم مصير الدين ولا الرسول ولا المؤمنين؛ فتكشف العبارة أن القلق ثمرة أنانية وضعف يقين، في مقابل طائفة الأمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص145–146، تحت «بيان الفرق بين الطائفتين بالواو، وباختلاف الوصفين، وحكمهما الإعرابي».","url":""}]},{"id":"s3-555","number":555,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا وصف ظنهم بأنه ﴿غير الحق ظن الجاهلية﴾؟","answer":"﴿غير الحق﴾ تحكم ببطلان ظنهم، و﴿ظن الجاهلية﴾ تكشف أصله العقدي: سوء معرفة بالله ووعده وتدبيره، كتوهم أن الرسول سيخذل أو أن النصر خارج أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص149، تحت «غرض التعبير بلفظ ﴿الجاهلية﴾».","url":""}]},{"id":"s3-556","number":556,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا سألوا ﴿هل لنا من الأمر من شيء﴾ في صورة استفهام؟","answer":"هو استفهام اعتراض وتشكيك من أصحاب الظن، يوحي بأنهم حُرموا التدبير؛ فجاء الجواب بقصر الأمر كله على الله وكشف ما يخفونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص149، تحت «بلاغة الاستفهام في قوله تعالى: ﴿يقولون هل لنا من الأمر من شيء﴾».","url":""}]},{"id":"s3-557","number":557,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا جاء الرد ﴿قل إن الأمر كله لله﴾ بتوكيد وعموم؟","answer":"أكد بـ﴿إن﴾ لأن قولهم صادر عن شك واعتراض، وعمم بـ﴿كله﴾ حتى لا يبقى تدبير أو نصر أو أجل خارج سلطان الله؛ فالرد لا ينفي استعمال الأسباب، بل ينفي استقلالها وأهواء الناس بالأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص150–151، تحت «بلاغة حشد المؤكدات».","url":""}]},{"id":"s3-558","number":558,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿يخفون في أنفسهم ما لا يبدون لك﴾؟","answer":"أخفوا في قلوبهم اعتراضًا لم يجرؤوا على إظهاره للرسول: اتهام تدبير الخروج بأنه سبب القتل؛ فالجملة تكشف الفرق بين سؤالهم الظاهر وسوء ظنهم الباطن، وتقرر أن الله أطلع نبيه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص147–148، تحت «سر التعبير بقوله: ﴿في أنفسهم﴾ بعد ﴿يخفون﴾».","url":""}]},{"id":"s3-559","number":559,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا كرر سؤالهم بصيغة أخرى: ﴿لو كان لنا من الأمر شيء ما قتلنا هاهنا﴾؟","answer":"السؤال الأول اعتراض مبهم: هل لنا من التدبير شيء؟ أما الثانية فتصرح بمكنون الاعتراض: لو أخذ برأينا وبقينا في المدينة لما قتل أصحابنا. فهي تكشف النتيجة القدرية الفاسدة الكامنة وراء السؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص149–150، تحت «بلاغة الاستفهام في قوله تعالى: ﴿يقولون هل لنا من الأمر من شيء﴾».","url":""}]},{"id":"s3-560","number":560,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿لبرز الذين كتب عليهم القتل إلى مضاجعهم﴾؟","answer":"حتى لو بقيتم في البيوت لخرج من كتب عليه القتل إلى المكان المقدر له؛ فـ﴿لبرز﴾ تصور قوة نفاذ القدر الذي يستخرج صاحبه إلى أجله، وتبطل وهم أن اختيار الخطة يمنع الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص152، تحت «فائدة تعليم الجواب».","url":""}]},{"id":"s3-561","number":561,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا سمّى مواضع القتل ﴿مضاجعهم﴾؟","answer":"المضجع مكان يضع فيه الإنسان جنبه للنوم، فصور موضع القتل مضجعًا يستقر فيه الجسد كالنائم؛ وإضافته إليهم توحي بأن لكل واحد موضعًا مقدرًا يبلغه عند أجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص153، تحت «نكتة الاستعارة في لفظ المضاجع».","url":""}]},{"id":"s3-562","number":562,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا جمع بين ابتلاء ما في الصدور وتمحيص ما في القلوب؟","answer":"الابتلاء يُظهر المستور ويختبره، والتمحيص ينقيه ويميز خالصه من دخيله؛ فالمحنة كاشفة ومطهرة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص154، تحت «علة إطلاق الصدور على الضمائر، والقلوب على الاعتقاد».","url":""}]},{"id":"s3-563","number":563,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"لماذا خُتمت الآية بـ﴿والله عليم بذات الصدور﴾؟","answer":"لأن الآية عرضت أقوالًا تخفي وراءها ظنونًا واعتراضات؛ فقرر أن الله يعلم السريرة التي تولد منها الكلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص154–155، تحت «جماع المؤكدات في فاصلة الآية».","url":""}]},{"id":"s3-564","number":564,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الذين تولوا منكم يوم التقى الجمعان﴾ ولم يسمّهم؟","answer":"لم يسمهم سترًا عليهم بعد أن عفا الله عنهم، وعرّفهم بالفعل والوقت بقدر ما تقوم به العبرة: الذين أدبروا يوم أُحد؛ فثبت الخطأ للتربية من غير تخليد أسماء أصحابه بالفضيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص166، تحت «وجه التعبير بلفظ الجمع».","url":""}]},{"id":"s3-565","number":565,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما استزلهم الشيطان ببعض ما كسبوا﴾، فجعل الخطأ زلّة؟","answer":"الاستزلال طلب إيقاع القدم في الزلل بعد ثباتها، فصور الفرار عثرة جرهم إليها الشيطان بسبب بعض ما سبق من ذنوبهم؛ وفي تسميته زلة تخفيف لا تبرئة، يوافق العفو اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص166–167، تحت «الاستعارة في لفظ الزلل للتعبير عن معنى الانهزام».","url":""}]},{"id":"s3-566","number":566,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿ببعض ما كسبوا﴾، دون أن يقال: بذنوبهم؟","answer":"﴿كسبوا﴾ تنسب السبب إلى عمل اختاروه هم، لا إلى طبيعة لازمة، و﴿بعض﴾ تفيد أن بعض الذنوب فتح للشيطان مدخل الزلة؛ وفيها تخفيف ورحمة مع إثبات المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص168، تحت «معاني حرف الباء في قوله: ﴿ببعض ما كسبوا﴾».","url":""}]},{"id":"s3-567","number":567,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"لماذا كرر العفو في ﴿ولقد عفا الله عنهم﴾؟","answer":"أعيد العفو هنا ليخص الذين تولوا يوم التقى الجمعان بعد بيان سبب زلتهم، فيغلق باب التشهير والمؤاخذة بعد التوبة؛ فليس تكرارًا خاليًا، بل عفو محدد عن جماعة عُين خطؤها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص169، تحت «علة تكرار الإخبار بالعفو»","url":""}]},{"id":"s3-568","number":568,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"لماذا ختم بـ﴿إن الله غفور حليم﴾؟","answer":"﴿غفور﴾ يقرر ستر زلتهم ومحو مؤاخذتها، و﴿حليم﴾ يبين أنه لم يعاجلهم بالعقوبة حين فروا بل أمهلهم حتى تابوا؛ فاجتمعت إزالة الذنب مع الإمهال السابق لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص171، تحت «دلالة جملة التذييل».","url":""}]},{"id":"s3-569","number":569,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا نُهي المؤمنون أن يكونوا كالذين كفروا في كلامهم عن إخوانهم؟","answer":"لأن قولهم يربط الموت بالسفر والقتال ويغذي الحسرة والجبن، فأبطل القرآن منطقهم بتقرير أن الإحياء والإماتة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص185–188، تحت «قوة قوله: ﴿والله يحيي ويميت﴾ بعد النهي السابق».","url":""}]},{"id":"s3-570","number":570,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا ضربوا في الأرض﴾، وكيف يكون السفر ضربًا؟","answer":"الضرب في الأرض كناية عن السفر والسير فيها، لأن المسافر يوقع قدميه عليها ويقطع نواحيها حركةً بعد حركة؛ فاختير فعل حركي يجسد مشقة الارتحال وامتداده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص182، تحت «وجه الاستعارة في لفظة الضرب».","url":""}]},{"id":"s3-571","number":571,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا قابل بين ﴿غزّى﴾ و﴿ضربوا في الأرض﴾؟","answer":"﴿ضربوا في الأرض﴾ يشمل السفر في مصالح الدنيا، و﴿غزّى﴾ يخص الخروج للقتال؛ فجمعهما ليبطل قولهم في كل غائب مات طبيعيًا أو قتل في المعركة، لا في صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص180، تحت «علة ذكر الغزو بعد الضرب، وإفراده منه».","url":""}]},{"id":"s3-572","number":572,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا كرروا ﴿ما ماتوا وما قتلوا﴾ مع إمكان الاكتفاء بأحدهما؟","answer":"الموت يقابل السفر والقتل يقابل الغزو، فلابد من ذكرهما لاستيعاب الحالتين؛ وكررت ﴿ما﴾ حتى يكون كل نفي مستقلًا: لا ماتوا ولا قتلوا، لا أن المنفي أحدهما فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص184، تحت «فائدة تكرار حرف النفي (ما)».","url":""}]},{"id":"s3-573","number":573,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿ليجعل الله ذلك حسرة في قلوبهم﴾؟","answer":"جعل الله هذا الاعتقاد نفسه حسرة ملازمة لقلوبهم؛ لأن من ظن أن البقاء كان يمنع الموت ظل يراجع الاحتمال المستحيل ويندم، أما المؤمن فيسلم للأجل فلا تستعبده «لو».","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص185، تحت «معنى جعل الحسرة من فعل الله تعالى».","url":""}]},{"id":"s3-574","number":574,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿والله يحيي ويميت﴾ بعد نفي أثر البقاء في البيوت؟","answer":"عقب قولهم ليحسم أصل الوهم: لا البيت يحيي ولا السفر والقتال يميتان، بل الله وحده يقدر الحياة والموت بأجلهما؛ فذكر الضدين يستوعب السلطان كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص185، تحت «قوة قوله: ﴿والله يحيي ويميت﴾ بعد النهي السابق».","url":""}]},{"id":"s3-575","number":575,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"لماذا ختم بـ﴿والله بما تعملون بصير﴾؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص186–187، تحت «بيان المناسبة بين العمل والبصر والعلم».","url":""}]},{"id":"s3-576","number":576,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"ما سرّ تقديم ﴿قتلتم﴾ على ﴿متم﴾ في الآية 157، وتقديم الموت على القتل في الآيتين 144 و158؟","answer":"في آية 157 المقام ترغيب في الجهاد فقدم القتل في سبيل الله، أما آية 144 فالمقام في مضي الرسول كسائر الرسل، فقدم الموت لأنه الوصف الجامع لمضيهم، ومعه إشعار بأن النبي ﷺ سيموت ولا يقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص199–200، تحت «توجيه المتشابه اللفظي تقديمًا وتأخيرًا في لفظتي الموت والقتل».","url":""}]},{"id":"s3-577","number":577,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿لمغفرة من الله ورحمة خير مما يجمعون﴾؟","answer":"أكد بالقسم واللام أن ما يناله المقتول أو الميت في سبيل الله من مغفرة تمحو الذنب ورحمة توصله إلى النعيم خير من جميع ما يكدس الناس من متاع الدنيا؛ فصحح مقياس الربح والخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص193، تحت «غرض تنكير مغفرة ورحمة».","url":""}]},{"id":"s3-578","number":578,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"لماذا قدّم المغفرة على الرحمة؟","answer":"لأن المغفرة ترفع أثر الذنب أولًا، ثم تتفضل الرحمة بإيصال الخير؛ فالتطهير سابق على الإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص194–195، تحت «توجيه عطف ﴿ورحمة﴾ على المغفرة».","url":""}]},{"id":"s3-579","number":579,"surah":3,"verses":[157],"references":[{"surah":3,"verses":[157]}],"verseLabel":"آل عمران: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿مما يجمعون﴾ ولم يذكر المال؟","answer":"حذف مفعول ﴿يجمعون﴾ ليعم المال والغنائم وسائر متاع الدنيا ومكاسبها؛ فالمغفرة والرحمة خير من كل مجموع يتنافسون فيه، لا من نوع مالي واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص195، تحت «وجه احتمال خيرية ما يجمعون».","url":""}]},{"id":"s3-580","number":580,"surah":3,"verses":[158],"references":[{"surah":3,"verses":[158]}],"verseLabel":"آل عمران: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿لإلى الله تحشرون﴾ بتقديم الجار والمجرور؟","answer":"قدم ﴿إلى الله﴾ لقصر الحشر والمرجع عليه ولتعظيم الغاية: سواء متم أو قتلتم فليس المصير إلى الدنيا ولا إلى من خفتموهم، بل إليه وحده للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص201، تحت «بلاغة تقديم متعلق الفعل عليه في قوله: ﴿لإلى الله تحشرون﴾».","url":""}]},{"id":"s3-581","number":581,"surah":3,"verses":[158],"references":[{"surah":3,"verses":[158]}],"verseLabel":"آل عمران: 158","question":"لماذا اختير ﴿تحشرون﴾ لا: ترجعون؟","answer":"الرجوع قد يكون فرديًا ومجرد عودة، أما الحشر فيصور جمع الناس من قبورهم وسوقهم جميعًا إلى موقف الحساب؛ فناسب تقرير المصير العام بعد الموت والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص202، تحت «سر التعبير بالفعل المبني للمفعول».","url":""}]},{"id":"s3-582","number":582,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿فبما رحمة من الله لنت لهم﴾، وما سر زيادة ﴿ما﴾؟","answer":"زيدت ﴿ما﴾ لتوكيد أن لين النبي ﷺ ناشئ عن رحمة عظيمة من الله وتقوية السببية، وقيل هي نكرة تفخيمية: فبرحمةٍ ما عظيمة لنت لهم؛ وفي الوجهين تعظيم للمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص209، تحت «بلاغة ذكر (ما) في قوله تعالى: ﴿فبما﴾».","url":""}]},{"id":"s3-583","number":583,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا نُسب اللين إلى النبي في قوله ﴿لنت لهم﴾؟","answer":"نسب الفعل إليه لأن الرحمة الإلهية تجسدت في معاملته الفعلية لهم: عفا وخاطب برفق بعد أُحد؛ واستعير لين الملمس لسهولة الخلق ورفقه، مع بقاء مصدر هذا الخلق رحمةً من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص212–213، تحت «فن التكميل في قوله: ﴿فبما رحمة من الله لنت لهم﴾».","url":""}]},{"id":"s3-584","number":584,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا جمع بين ﴿فظًا﴾ و﴿غليظ القلب﴾؟","answer":"الفظاظة خشونة القول والمعاملة في الظاهر، وغلظ القلب قسوة الباطن؛ فانتفى عن الرسول السبب الداخلي ومظهره الذي ينفر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص213، تحت «علة تقديم وصف الفظاظة على وصف الغلظة».","url":""}]},{"id":"s3-585","number":585,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا صوّر ابتعاد الناس بقوله ﴿لانفضوا من حولك﴾؟","answer":"الانفضاض تفرق الجماعة من حول مركزها؛ فشبه نفورهم وفرارهم عنه متفرقين بانفضاض قوم كانوا مجتمعين حوله، وفي ﴿من حولك﴾ إشعار بأنهم كانوا ملتفين به متبعين له.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص205–206، تتمة «شرح المفردات»، مدخلا ﴿لانفضوا﴾ و﴿حولك﴾.","url":""}]},{"id":"s3-586","number":586,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا رتب الأوامر: ﴿فاعف عنهم واستغفر لهم وشاورهم في الأمر﴾؟","answer":"بدأ بالعفو عما تعلق بحقه ﷺ، ثم بالاستغفار لهم فيما بينهم وبين الله، ثم بالمشاورة بعد إزالة أثر الذنب؛ فانتقل من محو المؤاخذة إلى طلب المغفرة ثم إعادة إشراكهم في أمر الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص216، تحت «مراعاة حسن الترتيب في الأوامر».","url":""}]},{"id":"s3-587","number":587,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا أمره بمشاورتهم بعد ما وقع بسبب بعضهم في أُحد؟","answer":"أمره أن يشاورهم بعد زلتهم تأليفًا لقلوبهم وإشعارًا ببقاء منزلتهم، حتى لا يظنوا أن خطأ أُحد أخرجهم من المشاركة؛ فالعفو والاستغفار يتبعهما رد الاعتبار العملي بالمشاورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص214–215، تحت «علة التفريع في قوله: ﴿فاعف عنهم﴾».","url":""}]},{"id":"s3-588","number":588,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا أمر الله بالتوكل عليه بعد الأمر بالمشاورة في قوله تعالى: ﴿فإذا عزمت فتوكل على الله﴾؟","answer":"المشاورة أخذ بالأسباب، ثم يأتي التوكل حتى لا يكون الاعتماد على الرأي الذي انتهت إليه المشاورة وحده، بل على إعانة الله وتسديده؛ فيجمع العمل بين النظر في الأسباب والاعتماد على مسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص217، تحت عنوان «دلالة نسبة التوكل على الله تعالى»","url":""}]},{"id":"s3-589","number":589,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"لماذا ختم بـ﴿إن الله يحب المتوكلين﴾؟","answer":"ختم بالمحبة ترغيبًا في التوكل بعد العزم؛ لأنه علامة صدق الإيمان والافتقار إلى الله. وأكد الخبر بـ﴿إن﴾، وعبّر بـ﴿المتوكلين﴾ لمدح من ثبت التوكل وصفًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص218–219، تحت «بلاغة التذييل بجملة ﴿إن الله يحب المتوكلين﴾».","url":""}]},{"id":"s3-590","number":590,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]},{"surah":62,"verses":[11]}],"verseLabel":"آل عمران: 159؛ الجمعة: 11","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿لانفضوا من حولك﴾، وقوله تعالى في الجمعة ﴿انفضوا إليها وتركوك قائمًا﴾؟","answer":"﴿من حولك﴾ تصور تفكك الجماعة وابتعادها عن مركزها بسبب الفظاظة، أما ﴿إليها﴾ فتصور اندفاعهم نحو التجارة واللهو؛ فالحرفان يرسمان جهتي الحركة: نفورًا من شخص، وإقبالًا على مغرٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص746، تحت «نكتة تعدية الفعل ﴿انفضوا﴾ بـ(إلى)».","url":""}]},{"id":"s3-591","number":591,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ينصركم الله فلا غالب لكم﴾، دون أن يقال: فأنتم الغالبون؟","answer":"﴿فلا غالب لكم﴾ تنفي جنس من يستطيع غلبتكم نفيًا شاملاً، وهو أقوى من مجرد قول «فأنتم الغالبون»؛ لأن العبرة ليست بقوتكم الذاتية بل باستحالة قهر من نصره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص225، تحت «بيان دلالة النفي في قوله: ﴿إن ينصركم الله فلا غالب لكم﴾».","url":""}]},{"id":"s3-592","number":592,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"لماذا قابل النصر بالخذلان لا بالهزيمة؟","answer":"لأن الخذلان هو سلب المعونة، وهو المقابل الحقيقي لنصر الله؛ أما الهزيمة فنتيجة ظاهرة قد تقع ابتلاءً ولا تدل وحدها على انقطاع الولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص226، تحت «براعة التعبير عن المقابلة».","url":""}]},{"id":"s3-593","number":593,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن ذا الذي ينصركم من بعده﴾ في صورة سؤال؟","answer":"الاستفهام إنكاري بمعنى: لا أحد ينصركم إذا خذلكم الله، وهو أبلغ لأنه يدفعهم إلى طلب الناصر ثم الإقرار باستحالته؛ وصيغ سؤالًا تلطفًا بالمؤمنين بدل التصريح القاسي بنفي الناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص226، تحت «غرض الاستفهام البلاغي».","url":""}]},{"id":"s3-594","number":594,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"لماذا ختم ﴿وعلى الله فليتوكل المؤمنون﴾ كما ختمت آية 122؟","answer":"لما انحصر النصر والخذلان في مشيئة الله، لزم أن يخصه المؤمنون بالتوكل؛ فقدم ﴿على الله﴾ للحصر، وعلق الأمر بالمؤمنين لأن إيمانهم بأنه وحده الناصر يقتضي تفويض الأمر إليه، كما في آية 122.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص229، تحت «فائدة التعبير بلفظ المؤمنين».","url":""}]},{"id":"s3-595","number":595,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان لنبي أن يغل﴾ بصيغة الاستبعاد؟","answer":"﴿ما كان لنبي﴾ لا تنفي وقوع الغلول فحسب، بل تستبعد إمكان ملاءمته لمقام النبوة أصلًا؛ فالأمانة لازمة لكل نبي، والخيانة منافية لما اصطفاه الله له.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص234، تحت «بلاغة النفي بالتعبير ﴿وما كان﴾»","url":""}]},{"id":"s3-596","number":596,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يغلل يأت بما غل يوم القيامة﴾، وكيف يأتي الإنسان بما أخفى؟","answer":"يجيء الغال يوم القيامة حاملًا ما خانه على رؤوس الأشهاد، وقيل يأتي بإثم الغلول وتبعته؛ ففي الوجهين ينقلب ما أخفاه في الدنيا إلى علامة ظاهرة تفضحه وتلزمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص241–245، تحت «الإتيان والمجيء».","url":""}]},{"id":"s3-597","number":597,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم توفى كل نفس ما كسبت﴾، فجعل العمل كسبًا؟","answer":"سمى العمل كسبًا لأنه ثمرة اختيار النفس وسعيها، يعود نفعه أو ضرره عليها؛ وبعد ذكر الغال خاصة عمم الحكم: كل نفس تستوفي جزاء جميع ما اكتسبت بلا نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص240، تحت «سبب وضع المكسوب موضع جزائه».","url":""}]},{"id":"s3-599","number":599,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿أفمن اتبع رضوان الله كمن باء بسخط من الله﴾؟","answer":"الاستفهام ينفي التسوية نفيًا يحمل السامع على الحكم بنفسه؛ فشتان بين من طلب الرضا ومن رجع حاملًا السخط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص245، تحت «بلاغة الفصل بالاستفهام الإنكاري».","url":""}]},{"id":"s3-600","number":600,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿اتبع رضوان الله﴾، وكيف يُتبع الرضوان؟","answer":"اتبع رضوان الله أي سلك الأعمال والهدى التي توصل إليه، مقتفيًا أمر الله ومجتنبًا نهيه؛ فنزل طلب أسباب الرضا منزلة اتباع طريق وآثار تقود إلى الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص246، تحت «التعبير بالرضوان دون الرضا».","url":""}]},{"id":"s3-601","number":601,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿باء بسخط﴾ لا: استحق سخطًا؟","answer":"﴿باء بسخط﴾ أبلغ من «استحق»؛ فهي تصوره راجعًا وقد حمل السخط ولزمه، حتى صار مآبه مقرونًا به، لا مجرد حكم باستحقاق بعيد عن مشهد الرجوع والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص246، تحت «وجه الاستعارة في الاستفهام»، في بيان ﴿كمن باء بسخط من الله﴾.","url":""}]},{"id":"s3-602","number":602,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"لماذا ختم بـ﴿وبئس المصير﴾ بعد ذكر جهنم؟","answer":"لم يكتف بذكر جهنم، بل ذمها بوصفها المرجع الذي ينتهي إليه صاحبه ويستقر فيه؛ فـ﴿بئس﴾ تقبح العاقبة، و﴿المصير﴾ يقرر أنها نهاية طريق السخط لا عارض عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص247، تحت «تعقيب ذكر السخط بذكر العقاب».","url":""}]},{"id":"s3-603","number":603,"surah":3,"verses":[163],"references":[{"surah":3,"verses":[163]}],"verseLabel":"آل عمران: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿هم درجات عند الله﴾، دون أن يقال: لهم درجات؟","answer":"﴿هم درجات﴾ أبلغ من ﴿لهم درجات﴾؛ إذ جعلهم نفس الدرجات مبالغة في شدة تفاوتهم بحسب أعمالهم، كأن ذواتهم تجسدت منازل متفاوتة علوًا وسفلاً عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص253، تحت «بلاغة المجاز بحذف المضاف في قوله: ﴿هم درجات﴾».","url":""}]},{"id":"s3-604","number":604,"surah":3,"verses":[163],"references":[{"surah":3,"verses":[163]}],"verseLabel":"آل عمران: 163","question":"لماذا جمع الجميع في لفظ ﴿درجات﴾ مع اختلاف منازل الخير والشر؟","answer":"إذا عاد ﴿هم﴾ إلى فريقي الرضوان والسخط، أطلق ﴿درجات﴾ على منازل الفريقين من باب تغليب درجات أهل الخير على دركات أهل الشر؛ فشمل تفاوت الثواب والعقاب مع إبراز جانب الرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص254، تحت «نكتة التعبير عن الدرجات بجمع القلة»","url":""}]},{"id":"s3-605","number":605,"surah":3,"verses":[163],"references":[{"surah":3,"verses":[163]}],"verseLabel":"آل عمران: 163","question":"لماذا ختم بـ﴿والله بصير بما يعملون﴾؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص255، تحت «التعبير بصيغة فعيل».","url":""}]},{"id":"s3-606","number":606,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد منّ الله على المؤمنين﴾، وخص المؤمنين مع أن الرسول أُرسل للناس؟","answer":"الرسالة عامة، لكن المنة خصت بالمؤمنين لأنهم الذين آمنوا بالرسول وانتفعوا بتلاوته وتزكيته وتعليمه؛ فمن رد الرسالة لم تتحقق فيه ثمرة هذه النعمة وإن بلغه أصل الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص266، تحت «سر التعبير بالرسول دون النبي»","url":""}]},{"id":"s3-607","number":607,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿رسولًا من أنفسهم﴾ لا: منهم؟","answer":"﴿من أنفسهم﴾ تشعر بأنه من صميم جماعتهم وجنسهم ولسانهم، معروف النسب والسيرة بينهم؛ فذلك أدعى لأن يألفوه ويفهموا عنه ويثقوا بصدقه، وهو أبلغ قربًا من «منهم».","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص264–265، تحت «فائدة التعبير بلفظ ﴿أنفسهم﴾».","url":""}]},{"id":"s3-608","number":608,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"لماذا رتب وظائف الرسول: التلاوة، ثم التزكية، ثم تعليم الكتاب والحكمة؟","answer":"التلاوة توصل الوحي أولًا، والتزكية تهيئ النفوس لقبوله، والتعليم يبني الفهم الراسخ للكتاب والحكمة؛ فجمع البلاغ والتربية والمعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص267–268، تحت «نكتة توسيط التزكية بين تلاوة الآيات وتعليمها».","url":""}]},{"id":"s3-609","number":609,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ تقديم التزكية هنا على تعليم الكتاب والحكمة؟","answer":"قدمت التزكية لأن تخليص النفوس من الشرك وأخلاق الجاهلية يهيئها للانتفاع بالكتاب والحكمة، ولأن المخاطبين كانوا أحوج أولًا إلى تهذيب النفس؛ وليس المقصود فصل العمليتين زمنيًا، فالتعليم نفسه من وسائل التزكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص267، تحت «علة تقديم جملة ﴿ويزكيهم﴾».","url":""}]},{"id":"s3-610","number":610,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن كانوا من قبل لفي ضلال مبين﴾ بهذا التوكيد؟","answer":"أكد الجملة بـ﴿إن﴾ واللام في ﴿لفي﴾ لتقرير أنهم كانوا قبل الرسالة غارقين حقًا في ضلال واضح هو الشرك؛ وكلما ثبتت شدة الحال الأولى ظهر مقدار المنة في إخراجهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص269، تحت «نكتة التعبير بجملة ﴿وإن كانوا من قبل﴾».","url":""}]},{"id":"s3-611","number":611,"surah":3,"verses":[164],"references":[{"surah":2,"verses":[129,151]},{"surah":3,"verses":[164]},{"surah":62,"verses":[2]}],"verseLabel":"آل عمران: 164؛ البقرة: 129، 151؛ الجمعة: 2","question":"ما سرّ تقديم التزكية على تعليم الكتاب في آل عمران، بينما قدم إبراهيم التعليم على التزكية في دعائه؟","answer":"دعاء إبراهيم سار على ترتيب الوسائل المتوقعة: تلاوة ثم تعليم ثم تزكية، أما الإخبار عن منة الله فقدم ثمرة الرسالة العملية وهي تزكية النفوس، مع أن أعمال الرسول متداخلة؛ فترتيب الدعاء ترتيب طلب، وترتيب الامتنان ترتيب عناية وغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص267–268، تحت «علة تقديم جملة ﴿ويزكيهم﴾».","url":""}]},{"id":"s3-613","number":613,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿أولما أصابتكم مصيبة قد أصبتم مثليها﴾؟","answer":"أنكر تعجبهم من أُحد وذكّرهم بموازين الوقائع: أصابهم قتل سبعين، وقد أصابوا المشركين في بدر مثلي ذلك قتلًا وأسرًا؛ فلا يصح أن ينسوا النعمة السابقة ثم يستبعدوا مصيبة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص276، تحت «دلالة لفظ ﴿مثليها﴾ وما يستفاد منها».","url":""}]},{"id":"s3-614","number":614,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"لماذا حكى تعجبهم بقولهم ﴿أنى هذا﴾ لا: كيف حدث هذا؟","answer":"﴿أنى﴾ تسأل عن جهة مجيء المصيبة ومصدرها، فجاء الجواب ﴿هو من عند أنفسكم﴾ مطابقًا؛ أما كيف فتطلب صفة الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص277، تحت «بلاغة الاستفهام بـ﴿أنى﴾».","url":""}]},{"id":"s3-615","number":615,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"لماذا جاء الجواب ﴿قل هو من عند أنفسكم﴾؟","answer":"ردّ سبب المصيبة إلى مخالفة الرماة والتنازع، ليمنع تعليق الفشل على القدر وحده ويثبت مسؤولية الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص277، تحت «وجه التوكيد في جملة القول».","url":""}]},{"id":"s3-616","number":616,"surah":3,"verses":[165],"references":[{"surah":3,"verses":[165]}],"verseLabel":"آل عمران: 165","question":"لماذا ختم بـ﴿إن الله على كل شيء قدير﴾ مع أن الحديث عن خطأ البشر؟","answer":"حتى لا يفهم إسناد المصيبة إلى أنفسهم أن الله عجز عن دفعها؛ فهو قادر على النصر والخذلان، لكن حكمته أجرت أثر مخالفتهم عليهم. فاجتمعت مسؤولية البشر مع شمول القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص278، تحت «بلاغة الفاصلة القرآنية».","url":""}]},{"id":"s3-617","number":617,"surah":3,"verses":[166],"references":[{"surah":3,"verses":[166]}],"verseLabel":"آل عمران: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أصابكم يوم التقى الجمعان فبإذن الله﴾؟","answer":"بعد قوله إن المصيبة من عند أنفسهم، بيّن أنها لم تخرج عن سلطان الله: وقعت بعلمه وقضائه وقدره وإذنه الكوني؛ فالمخالفة سببها البشري، والإذن يثبت أن الأسباب لا تستقل عن تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص285، تحت «سر التعبير بـ﴿يوم التقى الجمعان﴾ دون ﴿يوم أُحد﴾».","url":""}]},{"id":"s3-618","number":618,"surah":3,"verses":[166],"references":[{"surah":3,"verses":[166]}],"verseLabel":"آل عمران: 166","question":"لماذا عبّر عن أُحد بـ﴿يوم التقى الجمعان﴾؟","answer":"لم يسم أُحد، بل استحضرها بوصفها يوم مواجهة جمع المؤمنين وجمع المشركين؛ لأن المقصود ليس المكان وحده، بل اللقاء الذي ترتبت عليه المصيبة وانكشف فيه صدق المؤمنين ونفاق المتخلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص285، تحت «سرّ التعبير بـ﴿يوم التقى الجمعان﴾ دون يوم أُحد»","url":""}]},{"id":"s3-619","number":619,"surah":3,"verses":[166],"references":[{"surah":3,"verses":[166]}],"verseLabel":"آل عمران: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿وليعلم المؤمنين﴾ مع سبق علم الله؟","answer":"ليس المراد حدوث علم لم يكن، فعلم الله سابق محيط؛ بل أن يظهر إيمان المؤمنين في الواقع ويتميزوا بأفعالهم، فينكشف للناس ما كان معلومًا لله ويقوم عليه الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص286، تحت «نكتة تكرار فعل العلم من قوله تعالى: ﴿وليعلم المؤمنين وليعلم الذين نافقوا﴾».","url":""}]},{"id":"s3-620","number":620,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿وقيل لهم تعالوا قاتلوا في سبيل الله أو ادفعوا﴾؟","answer":"أقيمت عليهم الحجة بدعوتهم إلى أحد طريقين: قتال مخلص في سبيل الله، أو على الأقل دفع العدو عن الحرم والأهل وتكثير جمع المسلمين؛ فرفضهم الأمرين كشف أن تخلفهم ليس لاختلاف نية القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص289، تحت «دلالة ﴿أو﴾ وبلاغة التعريض في قوله: ﴿قاتلوا في سبيل الله أو ادفعوا﴾».","url":""}]},{"id":"s3-621","number":621,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"لماذا عُرض عليهم القتال في سبيل الله، ثم أدنى منه مجرد الدفع؟","answer":"أقام عليهم الحجة بالتدرج: إن لم يخلصوا للقتال الديني فليدفعوا عن الأهل والبلد؛ فلما رفضوا الأدنى انكشف أن عذرهم ستار للنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص289، تحت «دلالة ﴿أو﴾ وبلاغة التعريض في قوله: ﴿قاتلوا في سبيل الله أو ادفعوا﴾».","url":""}]},{"id":"s3-622","number":622,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما دلالة قولهم ﴿لو نعلم قتالًا لاتبعناكم﴾ بدل أن يقولوا: لقاتلنا معكم؟","answer":"قالوا ﴿لاتبعناكم﴾ ليظهروا أن امتناعهم تابع لتقدير عسكري لا رفضًا للجماعة، وكأنهم مستعدون للسير خلفهم متى ثبت عندهم القتال؛ لكنهم كانوا يعلمون وقوعه ولا ينوون الاتباع، ففضحت العبارة كذب الشرط والجواب معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص290، تحت «دلالة تعليق الشرط بـ(لو) في قوله تعالى: ﴿لو نعلم قتالًا﴾».","url":""}]},{"id":"s3-623","number":623,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿هم للكفر يومئذ أقرب منهم للإيمان﴾ لا: هم كافرون؟","answer":"لم يحكم على بواطنهم حكمًا مطلقًا، بل وصف ما أظهره موقفهم يومئذ؛ وفي المقارنة كشف لتأرجحهم وغلبة جانب الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص291، تحت «دلالة تقديم ما حقه التأخير في قوله تعالى: ﴿هم للكفر يومئذ أقرب منهم للإيمان﴾».","url":""}]},{"id":"s3-624","number":624,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿يقولون بأفواههم ما ليس في قلوبهم﴾؟","answer":"ذكر الأفواه مع أن القول لا يكون إلا بها ليصور أن دعواهم بقيت ألفاظًا على الشفاه لا حقيقة لها في القلوب؛ فالمقابلة بين الفم والقلب تكشف انفصال ظاهرهم عن باطنهم، وهو عين النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص293، تحت «براعة المجاز المرسل في قوله تعالى: ﴿يقولون بأفواههم ما ليس في قلوبهم﴾».","url":""}]},{"id":"s3-625","number":625,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"لماذا جاءت خاتمة آل عمران ﴿والله أعلم بما يكتمون﴾، وفي المائدة ﴿والله أعلم بما كانوا يكتمون﴾؟","answer":"في آل عمران كشف موقف عارض اشتد فيه قربهم من الكفر، فجيء بـ﴿يكتمون﴾ لحال كتمانهم؛ أما المائدة فتصف قومًا رسخ تاريخهم في الدخول بالكفر والخروج به، فزادت ﴿كانوا﴾ للدلالة على استمرار الكتمان وتمكنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص295، تحت «توجيه المتشابه اللفظي».","url":""}]},{"id":"s3-626","number":626,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]},{"surah":63,"verses":[1]}],"verseLabel":"آل عمران: 167؛ المنافقون: 1","question":"ما سرّ التعبير بقوله تعالى: في آل عمران ﴿الذين نافقوا﴾، وجاء في السورة الأخرى الاسم الصريح ﴿المنافقون﴾؟","answer":"في آل عمران يصف النص فعلًا ظهر منهم في حادثة أحد، فناسب الموصول والفعل ﴿الذين نافقوا﴾؛ أما سورة المنافقون فتعالج الصفة بعد رسوخها واشتهار أصحابها بها، فجاء اسم الفاعل عنوانًا ثابتًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص286، تحت «سرّ التعبير عن أهل الإيمان بالاسم وعن أهل النفاق بالفعل في قوله تعالى: ﴿وليعلم المؤمنين وليعلم الذين نافقوا﴾».","url":""}]},{"id":"s3-627","number":627,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين قالوا لإخوانهم وقعدوا﴾، دون أن يقال: الذين قعدوا وقالوا؟","answer":"الواو في ﴿وقعدوا﴾ للحال، أي قالوا لإخوانهم هذا الكلام وهم قد قعدوا عن الجهاد؛ فقدم القول لأنه موضع الرد، وذكر القعود حالًا تكشف تناقض من يلوم المقاتلين بعد أن تخلف هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص300، تحت «دلالة (أل) في ﴿الذين﴾ في قوله تعالى: ﴿الذين قالوا لإخوانهم وقعدوا﴾».","url":""}]},{"id":"s3-628","number":628,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"لماذا سمّوا المقتولين ﴿إخوانهم﴾ مع تخذيلهم لهم؟","answer":"سماهم إخوانهم لما بينهم من نسب وقوم، أو بحسب أخوة الإسلام التي يظهرها المنافقون؛ وفي التسمية توبيخ خفي: كيف يتخذون الأخوة لسانًا ثم يقعدون ويجعلونها بابًا للوم المقتولين؟","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص300–301، تحت «دلالة الأخوة في قوله تعالى: ﴿الذين قالوا لإخوانهم وقعدوا لو أطاعونا ما قتلوا﴾».","url":""}]},{"id":"s3-629","number":629,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"ما سرّ التعبير بقوله تعالى: لهم ﴿فادرءوا عن أنفسكم الموت إن كنتم صادقين﴾؟","answer":"ألزمهم بنتيجة قولهم: إن كان القعود يرد الموت حقًا فادفعوه عن أنفسكم حين يأتيكم؛ فلما كانوا عاجزين ثبت أن الخروج لم ينشئ الأجل، وأن قولهم ﴿لو أطاعونا ما قتلوا﴾ كذب على القدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص302، تحت «براعة أسلوب البحث في قوله تعالى: ﴿قل فادرؤوا عن أنفسكم الموت إن كنتم صادقين﴾»","url":""}]},{"id":"s3-630","number":630,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"لماذا اختير ﴿ادرءوا﴾ لا: ادفعوا؟","answer":"الدرء دفع الشيء وإبعاده قبل أن يصل، فـ﴿ادرءوا﴾ تصور محاولة اعتراض الموت وصرفه عن النفس قبل وقوعه؛ وهذا أبلغ في التحدي من مجرد دفع غير محدد الجهة أو الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص296–297، تحت «الدفع والرد والدرء».","url":""}]},{"id":"s3-631","number":631,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تحسبن الذين قتلوا في سبيل الله أمواتًا﴾ بصيغة النهي؟","answer":"جاء نهيًا مؤكدًا بالنون ليقتلع الظن الذي روّجه المنافقون أن القتل ضياع، ويوجه الرسول والمؤمنين إلى الحكم المقابل يقينًا: الشهداء ليسوا أمواتًا عند ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص309، تحت «دلالة الخطاب في قوله تعالى: ﴿ولا تحسبن الذين قتلوا في سبيل الله أمواتًا﴾».","url":""}]},{"id":"s3-632","number":632,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"ما دلالة ﴿بل﴾ في قوله تعالى عن الشهداء: ﴿بل أحياء عند ربهم يرزقون﴾؟","answer":"تنقل ﴿بل﴾ الحكم من حسبانهم أمواتًا إلى إثبات الحياة لهم. فمع ثبوت قتل أجسامهم، لهم حياة حقيقية عند ربهم تزيد على مجرد بقاء الأرواح؛ ولذلك وصفوا بأنهم أحياء يرزقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص309–310، تحت عنوان «دلالة الطباق في قول الله تعالى: ﴿ولا تحسبن الذين قتلوا في سبيل الله أمواتًا بل أحياء﴾»","url":""}]},{"id":"s3-633","number":633,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿عند ربهم﴾، دون أن يقال: في الجنة؟","answer":"﴿عند ربهم﴾ تفيد منزلة القرب والتشريف والكرامة مع رعاية الرب لهم، لا مجرد كونهم في مكان نعيم؛ وإضافة ﴿ربهم﴾ إليهم تزيد معنى العناية والتربية الخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص310–311، تحت «نكتة التعبير بالاسم الأحسن (الرب) وإضافته إلى الضمير العائد على الشهداء».","url":""}]},{"id":"s3-634","number":634,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"لماذا جاء ﴿يرزقون﴾ بالمضارع المبني للمجهول؟","answer":"المضارع يصور رزقهم متجددًا مستمرًا، وبني للمجهول لأن المقصود إبراز دوام ما يصل إليهم من النعيم، مع أن الرازق معلوم من قربه: هم عند ربهم وهو الذي يرزقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص320، تحت «الرزق والنعمة واللذة».","url":""}]},{"id":"s3-635","number":635,"surah":3,"verses":[169],"references":[{"surah":2,"verses":[154]},{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169؛ البقرة: 154","question":"ما سرّ اختلاف التفصيل في شأن الشهداء بين قوله تعالى في البقرة ﴿بل أحياء ولكن لا تشعرون﴾، وقوله تعالى في آل عمران ﴿بل أحياء عند ربهم يرزقون﴾؟","answer":"البقرة جاءت في أول تربية الأمة على البلاء فاكتفت بإثبات حياة لا تدركها الحواس، أما آل عمران فنزلت بعد وقوع القتل في أحد ففصلت تسليةً لأهل الشهداء: قربٌ ورزق وفرح واستبشار؛ فالثانية تفصيل للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص310، تحت «﴿بل أحياء﴾».","url":""}]},{"id":"s3-636","number":636,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿فرحين بما آتاهم الله من فضله﴾ لا: بما استحقوا؟","answer":"لأن ما نالوه ليس ثمنًا واجبًا على الله بمجرد عملهم، بل عطاء تفضل به فوق ما يتصورونه؛ فذكر الإيتاء والفضل يرد النعمة إلى واهبها ويضاعف الفرح بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص311، تحت «سر التعبير بالاسم الموصول (ما) في قوله تعالى: ﴿فرحين بما آتاهم الله من فضله﴾».","url":""}]},{"id":"s3-637","number":637,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿ويستبشرون بالذين لم يلحقوا بهم من خلفهم﴾؟","answer":"يفرح الشهداء بإخوانهم المؤمنين الذين بقوا بعدهم ولم يصلوا بعد إلى منزلتهم، لما علموا من حسن ما أعد لهم؛ فـ﴿لم يلحقوا﴾ تصور الفاصل المؤقت وتوقع اجتماع اللاحق بالسابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص312، تحت «دلالة التعبير بالاسم الموصول وصلته في قوله تعالى: ﴿ويستبشرون بالذين لم يلحقوا بهم من خلفهم﴾»","url":""}]},{"id":"s3-638","number":638,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"لماذا نُفي عن اللاحقين الخوف والحزن مع اختلاف زمنيهما؟","answer":"الخوف توقع مكروه آت، والحزن ألم على فائت؛ فنفيهما يؤمن مستقبلهم وماضيهم ويستوعب اضطراب النفس كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص313، تحت «نكتة تقديم نفي الخوف على نفي الحزن في قوله تعالى: ﴿ألا خوف عليهم ولا هم يحزنون﴾».","url":""}]},{"id":"s3-639","number":639,"surah":3,"verses":[171],"references":[{"surah":3,"verses":[171]}],"verseLabel":"آل عمران: 171","question":"لماذا كرر ﴿يستبشرون﴾ في آيتين متتاليتين؟","answer":"الاستبشار الأول بإخوانهم اللاحقين وأمنهم، والثاني بنعمة الله وفضله وعدم ضياع الأجر؛ فأعيد الفعل لأن متعلق الفرح تجدد: فرح بمصير إخوانهم، ثم فرح بما هم فيه من نعمة وضمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص314–315، تحت «فائدة تكرار الفعل ﴿يستبشرون﴾».","url":""}]},{"id":"s3-640","number":640,"surah":3,"verses":[171],"references":[{"surah":3,"verses":[171]}],"verseLabel":"آل عمران: 171","question":"لماذا فُصّل الاستبشار بـ﴿نعمة من الله وفضل﴾، وما الفرق بينهما؟","answer":"النعمة هي ما أنعم الله به عليهم من الحياة والرزق والكرامة، والفضل زيادة الإحسان فوق أصل الجزاء والاستحقاق؛ فجمعهما ليستوعب أصل العطاء وما زاد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص315–316، تحت «نكتة تنكير ﴿نعمة﴾ و﴿فضل﴾، وسر ذكر الخاص بعد العام».","url":""}]},{"id":"s3-641","number":641,"surah":3,"verses":[171],"references":[{"surah":3,"verses":[171]}],"verseLabel":"آل عمران: 171","question":"لماذا ختم بـ﴿وأن الله لا يضيع أجر المؤمنين﴾؟","answer":"ختم بضمان جامع يفسر استبشار الشهداء ويشمل من خلفهم: الله لا يبطل ثواب إيمان أو طاعة، بل يوفي كل مؤمن أجره؛ فكرامة الشهداء مثال على قاعدة حفظ العمل لا حالة منفصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص316، تحت «توجيه القراءات القرآنية في قوله: ﴿وأن الله لا يضيع أجر المؤمنين﴾».","url":""}]},{"id":"s3-642","number":642,"surah":3,"verses":[172],"references":[{"surah":3,"verses":[172]}],"verseLabel":"آل عمران: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين استجابوا لله والرسول من بعد ما أصابهم القرح﴾؟","answer":"وصفهم بالاستجابة لأنهم لبوا نداء الخروج إلى حمراء الأسد فور أُحد، مع أن جراح المعركة ما زالت فيهم؛ فذكر القرح يعظم طاعتهم، إذ غلبوا الألم والخوف ولم يتخذوه عذرًا للقعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص326، تحت «نكتة الوصف في قوله تعالى: ﴿الذين استجابوا لله والرسول﴾».","url":""}]},{"id":"s3-644","number":644,"surah":3,"verses":[172],"references":[{"surah":3,"verses":[172]}],"verseLabel":"آل عمران: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿للذين أحسنوا منهم واتقوا﴾، فجاء بـ﴿منهم﴾؟","answer":"جاءت ﴿منهم﴾ لتمييز من استمر إحسانه وتقواه داخل جماعة المستجيبين؛ فالأجر العظيم ليس لمجرد الحضور أو الاسم، بل لمن أحسن العمل واتقى المخالفة، وقيل هي لبيان أن هؤلاء هم الجماعة الممدوحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص328، تحت «سبب فصل قول الله تعالى: ﴿للذين أحسنوا منهم واتقوا أجر عظيم﴾ عما قبله».","url":""}]},{"id":"s3-645","number":645,"surah":3,"verses":[172],"references":[{"surah":3,"verses":[172]}],"verseLabel":"آل عمران: 172","question":"لماذا جمع الإحسان والتقوى؟","answer":"لأن الوصفين يجمعان ترك المنكرات وفعل الخيرات؛ فالتقوى باعتبار أصلها اتقاء المنكر، والإحسان عمل الخير بإخلاص ومراقبة لله، فاجتمعت سلامة الترك وحسن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص754، تحت عنوان «علة الجمع بين صفتي التقوى والإحسان»","url":""}]},{"id":"s3-646","number":646,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"ما دلالة تكرار لفظ ﴿الناس﴾ في قوله تعالى: ﴿الذين قال لهم الناس إن الناس قد جمعوا لكم﴾؟","answer":"«الناس» الأولى ناقل التخويف، والثانية جيش المشركين المجتمع؛ وتكرار اللفظ يضخم التهديد كأن جماعة البشر كلها اجتمعت عليهم، مع اختلاف المراد في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص330–331، تحت «بلاغة المجاز المرسل في قوله تعالى: ﴿الذين قال لهم الناس إن الناس قد جمعوا لكم﴾».","url":""}]},{"id":"s3-647","number":647,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"لماذا زادهم التخويف إيمانًا بدل الخوف؟","answer":"لأن التهديد ردهم إلى يقينهم بأن الله كافيهم، فصار اجتماع الناس عليهم دليلًا جديدًا على صدق الوعد وميدانًا للتوكل، لا سببًا للانهيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص332، تحت «دلالة قوله تعالى: ﴿فزادهم إيمانًا﴾».","url":""}]},{"id":"s3-648","number":648,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"ما دلالة جواب المؤمنين: ﴿حسبنا الله ونعم الوكيل﴾؟","answer":"﴿حسبنا الله﴾ تعلن أن الله وحده كافيهم خطر العدو، و﴿نعم الوكيل﴾ تثني عليه بوصفه خير من يفوض إليه الأمر ويحفظه؛ فكان جوابهم توكلًا عمليًا يقابل التخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص332، تحت «دلالة قوله تعالى: ﴿حسبنا الله ونعم الوكيل﴾».","url":""}]},{"id":"s3-649","number":649,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"لماذا اختير اسم ﴿الوكيل﴾ في هذا الموقف؟","answer":"الوكيل هو من تفوض إليه الأمور فيحفظها ويدبرها ويكفي صاحبها؛ فناسب موقف قوم لا يملكون تقدير قوة العدو ونتيجة المواجهة، فأسندوا الحماية والتدبير إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص332–334، تحت «دلالة قوله تعالى: ﴿حسبنا الله ونعم الوكيل﴾».","url":""}]},{"id":"s3-650","number":650,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿فانقلبوا بنعمة من الله وفضل﴾، فجعل الرجوع انقلابًا؟","answer":"الانقلاب رجوع يصحبه تحول في الحال؛ خرجوا مثقلين بالجراح ومهددين بالعدو، ثم عادوا آمنين سالمين تحيط بهم النعمة والفضل، فدل الفعل على عودتهم وعلى انقلاب الخوف أمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص341–342، تحت «(انقلبوا)، و(رجعوا)» ضمن الفروق المعجمية.","url":""}]},{"id":"s3-652","number":652,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"لماذا جاءت جملة ﴿لم يمسسهم سوء﴾ بين النعمة واتباع الرضوان؟","answer":"توسطت لتبين أثر النعمة المحسوس: عادوا ولم يصبهم أدنى سوء، ثم عطفت المكسب الأعلى وهو اتباع رضوان الله؛ فجمعت سلامة البدن من الضرر وسلامة القصد بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص341، تحت «بلاغة التنكير وفن الاحتراس في قوله تعالى: ﴿لم يمسسهم سوء﴾».","url":""}]},{"id":"s3-653","number":653,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"لماذا ختم بـ﴿والله ذو فضل عظيم﴾؟","answer":"ختم بإرجاع السلامة والنعمة والرضوان والأجر إلى مصدرها: الله صاحب الفضل العظيم؛ فما نالوه تجاوز قدرتهم واستحقاقهم، ويفتح الختام الفضل على ما ذُكر وما لم يذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص192، تحت «بلاغة التذييل بقوله: ﴿والله ذو الفضل العظيم﴾».","url":""}]},{"id":"s3-654","number":654,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما ذلكم الشيطان يخوف أولياءه﴾؟","answer":"قصر بـ﴿إنما﴾ حقيقة هذا التهويل على وسوسة الشيطان؛ فهو يخوفكم بأوليائه ويضخم قوتهم في نفوسكم، ولذلك جاء التفريع: ﴿فلا تخافوهم﴾، أي لا تستجيبوا للصورة التي صنعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص346، تحت «سر استعمال أداة ﴿إنما﴾».","url":""}]},{"id":"s3-655","number":655,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تخافوهم وخافون﴾، فجمع ضميرهم وأفرد ضمير الله؟","answer":"جمع ضمير الأعداء لكثرتهم الظاهرة، ثم أفرد ضمير الله لأن المستحق للخوف واحد؛ فالمقابلة تهدم رهبة العدد: لا تخافوا هذا الجمع، وخافوا الله وحده الذي يملك الأمر كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص348، تحت «فائدة جمع الضمير في قوله: ﴿فلا تخافوهم﴾».","url":""}]},{"id":"s3-656","number":656,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"لماذا عُلّق الأمر بالخوف من الله بقوله ﴿إن كنتم مؤمنين﴾؟","answer":"لأن الإيمان الحق يثمر خوف الله وحده ويمنع خضوع القلب لتهويل الشيطان؛ فالشرط يحرضهم: إن كان الإيمان مستقرًا في قلوبكم فليظهر أثره في ترك خوف العدو والثبات على طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص349–352، تحت «الخوف والخشية».","url":""}]},{"id":"s3-657","number":657,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحزنك الذين يسارعون في الكفر﴾، وكيف تكون المسارعة داخل الكفر؟","answer":"جعل الكفر ميدانًا يندفعون في داخله، فالصورة تكشف نشاطهم في أسبابه، ثم تسلّي الرسول بأنهم لا يضرون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص356، تحت «سر التعبير بالاسم الموصول في قوله سبحانه: ﴿الذين يسارعون في الكفر﴾».","url":""}]},{"id":"s3-658","number":658,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿إنهم لن يضروا الله شيئًا﴾ لا: لن يضروك؟","answer":"لم يقل «لن يضروك» لأن مسارعتهم ليست اعتداءً شخصيًا على الرسول ﷺ فقط، بل محاولة لمغالبة دين الله؛ فنفى قدرتهم على الإضرار بالله، أي بدينه ووعده، وارتد ضررهم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص356–357، تحت «غرض التعليل في قوله تعالى: ﴿إنهم لن يضروا الله﴾».","url":""}]},{"id":"s3-659","number":659,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿يريد الله ألا يجعل لهم حظًا في الآخرة﴾؟","answer":"كشف عاقبة الإمهال حتى لا يظن نشاطهم نجاحًا: يتركهم الله لاختيارهم حتى يستوفوا طريق الكفر، فتكون النتيجة ألا يبقى لهم نصيب من ثواب الآخرة، بل عذاب عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص358، تحت «بلاغة فصل جملة ﴿يريد الله ألا يجعل لهم حظًا في الآخرة﴾».","url":""}]},{"id":"s3-660","number":660,"surah":3,"verses":[176],"references":[{"surah":3,"verses":[176]}],"verseLabel":"آل عمران: 176","question":"لماذا سمّى نصيب الآخرة ﴿حظًا﴾؟","answer":"الحظ هو النصيب المقدر من الخير، فنفاه عنهم ليقرر أنهم لا يملكون في الآخرة أدنى سهم من النعيم أو الثواب؛ وتنكيره في سياق النفي يعم القليل والكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص358، تحت «غرض تنكير ﴿حظ﴾ ونكتة تأخيره عن ﴿لهم﴾».","url":""}]},{"id":"s3-661","number":661,"surah":3,"verses":[177],"references":[{"surah":3,"verses":[177]}],"verseLabel":"آل عمران: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿اشتروا الكفر بالإيمان﴾، وكيف يُشترى الكفر؟","answer":"صور تركهم الإيمان واختيارهم الكفر بصفقة: دفعوا الإيمان ثمنًا وأخذوا الكفر بدلًا منه؛ فالفعل يثبت أنهم اختاروا الخسارة بإرادتهم، لا أنهم وقعوا فيها بلا قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص361–362، تحت «بلاغة الاستعارة في قوله تعالى: ﴿اشتروا﴾».","url":""}]},{"id":"s3-662","number":662,"surah":3,"verses":[177],"references":[{"surah":3,"verses":[177]}],"verseLabel":"آل عمران: 177","question":"لماذا أعاد ﴿لن يضروا الله شيئًا﴾؟","answer":"أعيد لأن السياق انتقل من المسارعة في الكفر إلى صفقة استبدال الإيمان به؛ فمهما تعددت صور الكفر لا ينال ضررها دين الله أو ملكه، وإنما يرجع على أصحابها بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص362، تحت «المبالغة في تعليل النهي في قوله تعالى: ﴿إنهم لن يضروا الله شيئًا﴾».","url":""}]},{"id":"s3-663","number":663,"surah":3,"verses":[177],"references":[{"surah":3,"verses":[177]}],"verseLabel":"آل عمران: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿ولهم عذاب أليم﴾ بعد نفي الضرر عن الله؟","answer":"لما نفى أن يبلغ ضررهم الله، بيّن أين يقع الضرر حقيقة: عليهم هم؛ فتقديم ﴿لهم﴾ يخصهم بالعذاب، و﴿أليم﴾ يقابل وهم القوة بألم العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص362، تحت «المبالغة في تعليل النهي في قوله تعالى: ﴿إنهم لن يضروا الله شيئًا﴾».","url":""}]},{"id":"s3-664","number":664,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحسبن الذين كفروا أنما نملي لهم خير لأنفسهم﴾؟","answer":"نهاهم أن يظنوا أن تمديد العمر وإرخاء المهلة دليل خير أو رضا؛ فقد يكون الإملاء استدراجًا يتيح لهم الإصرار حتى تتراكم تبعة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص364، تحت «توجيه عطف قوله تعالى: ﴿ولا يحسبن الذين كفروا﴾».","url":""}]},{"id":"s3-665","number":665,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"لماذا كرر ﴿إنما نملي لهم﴾ بعد ذكر الإملاء أولًا؟","answer":"ذُكر الإملاء أولًا داخل ظنهم أنه خير، ثم أعيد بـ﴿إنما﴾ ليصحح ذلك الظن ويقصر حقيقته في حالهم على تمكينهم من زيادة الإثم؛ فالثاني تفسير حاسم للأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص366–367، تحت «بلاغة قوله تعالى: ﴿إنما نملي لهم ليزدادوا إثمًا﴾».","url":""}]},{"id":"s3-666","number":666,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"لماذا عُلّل الإمهال بقوله ﴿ليزدادوا إثمًا﴾؟","answer":"أي يمد لهم في الزمن وهم يختارون الكفر، فتكون نتيجة الإمهال ازدياد إثمهم بأفعالهم؛ فاللام للعاقبة أو الغاية بحسب التوجيه، ولا تعني إجبارهم على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص366، تحت «بلاغة قوله تعالى: ﴿إنما نملي لهم ليزدادوا إثمًا﴾».","url":""}]},{"id":"s3-667","number":667,"surah":3,"verses":[178],"references":[{"surah":3,"verses":[178]}],"verseLabel":"آل عمران: 178","question":"لماذا وصف العذاب هنا بـ﴿مهين﴾؟","answer":"لأنهم اغتروا بالمهلة وعدوها كرامة وقوة، فجاء العذاب مهينًا يسلبهم العزة الموهومة ويقابل استكبارهم بالذل، مع ما فيه من الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص362–363، تحت «مناسبة الآية لما قبلها» في قوله تعالى: ﴿ولهم عذاب مهين﴾.","url":""}]},{"id":"s3-669","number":669,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان الله ليذر المؤمنين على ما أنتم عليه﴾؟","answer":"الصيغة تنفي وتستبعد أن يترك الله الجماعة على حال اختلاط الصادق بالمنافق؛ فحكمته تقتضي أحداثًا وابتلاءات تظهر الخبيث من الطيب، لا دوام الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص372، تحت «معنى اللام في قوله: ﴿ليذر المؤمنين﴾».","url":""}]},{"id":"s3-670","number":670,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"لماذا انتقل من الغيبة في ﴿المؤمنين﴾ إلى الخطاب في ﴿ما أنتم عليه﴾؟","answer":"بدأ باسم المؤمنين لتقرير سنة عامة في جماعتهم، ثم التفت إلى ﴿أنتم﴾ ليواجه أهل المدينة مباشرة بحال اختلاطهم يومئذ؛ فصار الخبر حكمًا عامًا وتنبيهًا شخصيًا في آن.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص373، تحت «براعة الالتفات في إفادة الإيجاز».","url":""}]},{"id":"s3-671","number":671,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يميز الخبيث من الطيب﴾، ومن الخبيث والطيب هنا؟","answer":"المراد أن تكشف المحنة المنافق الخبيث من المؤمن الطيب، أو الكفر من الإيمان وآثارهما؛ فاستعير وصفا الخبث والطيب من الأشياء المحسوسة للنفوس والأعمال بحسب فسادها وصلاحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص374، تحت «نكتة إفراد الخبيث والطيب».","url":""}]},{"id":"s3-672","number":672,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"لماذا نفى إطلاع الناس على الغيب ثم أثبت اجتباء الرسل؟","answer":"نفى أن يكون الغيب مباحًا للبشر ابتداءً، ثم بيّن الاستثناء المنضبط: الله يختار من رسله من يطلعه على قدر يؤدي به الرسالة؛ فلا تناقض بين النفي والاجتباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص376، تحت «سر التعبير بلفظ الاجتباء في قوله تعالى: ﴿ولكن الله يجتبي من رسله﴾».","url":""}]},{"id":"s3-673","number":673,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿يجتبي من رسله من يشاء﴾ لا: يختار؟","answer":"الاجتباء اختيار خاص يصحبه اصطفاء وتقريب وضم إلى صفوة الله؛ فليس كل اختيار اجتباءً، ولذلك ناسب الرسل الذين يخصهم الله بحمل الوحي وبما يشاء من الغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص376، تحت «سر التعبير بلفظ الاجتباء في قوله تعالى: ﴿ولكن الله يجتبي من رسله﴾».","url":""}]},{"id":"s3-674","number":674,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"لماذا ختم بـ﴿وإن تؤمنوا وتتقوا فلكم أجر عظيم﴾؟","answer":"بدل الانشغال بطلب الغيب وتمييز السرائر، ردهم إلى ما يستطيعونه ويكلفون به: صدق الإيمان ولزوم التقوى؛ فمن حققهما فله الأجر العظيم وإن خفيت عليه بواطن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص377، تحت «قوة تفريع شرط الإيمان على الأمر بالإيمان».","url":""}]},{"id":"s3-675","number":675,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحسبن الذين يبخلون بما آتاهم الله من فضله هو خيرًا لهم﴾؟","answer":"نهى البخلاء أن يظنوا أن احتباس المال وحفظه ينفعهم؛ فما أمسكوه من عطاء الله لا يبقى لهم، بل يتحول يوم القيامة عقوبة ملازمة، فصحح مقياس الربح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص383–384، تحت «نوع عطف قوله: ﴿ولا يحسبن الذين يبخلون﴾».","url":""}]},{"id":"s3-676","number":676,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿بما آتاهم الله من فضله﴾، دون أن يقال: بأموالهم؟","answer":"لم يسم المال مالهم حتى لا يتوهموا استقلال الملك؛ إنه ما آتاهم الله تفضلًا، فالبخل حبس لنعمة المالك الحقيقي عن الحق الذي أمر به، وفي اللفظ تقبيح للجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص383–384، تحت «نكتة اختيار لفظ الإيتاء في قوله: ﴿بما آتاهم الله﴾».","url":""}]},{"id":"s3-677","number":677,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"لماذا أعقب ﴿هو خيرًا لهم﴾ بقوله ﴿بل هو شر لهم﴾؟","answer":"أبطلت ﴿بل﴾ ظنهم ولم تكتف بنفي الخير، بل أثبتت ضده: عين المال أو البخل الذي عدوه نفعًا هو شر عليهم؛ فانتقل الحكم من الوهم إلى الحقيقة المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص384، تحت «فائدة الإضراب والتنوين في قوله: ﴿بل هو شر لهم﴾».","url":""}]},{"id":"s3-678","number":678,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"لماذا صوّر مال البخيل بقوله ﴿سيطوقون ما بخلوا به﴾؟","answer":"حوّل المال المحبوب إلى طوق ملازم خانق يوم القيامة؛ فالعقوبة من جنس تعلقهم بما منعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص384–385، تحت «براعة المباغتة في الوعيد، وحسن التفسير بالتمثيل البليغ».","url":""}]},{"id":"s3-679","number":679,"surah":3,"verses":[180],"references":[{"surah":3,"verses":[180]}],"verseLabel":"آل عمران: 180","question":"لماذا ختم بـ﴿ولله ميراث السماوات والأرض﴾؟","answer":"لأن البخيل سيترك ما أمسكه ويموت، بينما الملك كله يرجع ويبقى لله؛ فتقديم ﴿لله﴾ يقصر الميراث الحقيقي عليه، ويجعل حبس المال عن حقه وهمًا قصيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص385–386، تحت «فائدة تقديم لفظ الجلالة في قوله: ﴿ولله ميراث السماوات والأرض﴾».","url":""}]},{"id":"s3-680","number":680,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد سمع الله قول الذين قالوا﴾ مع أن الله يسمع كل شيء؟","answer":"التوكيد والقول المكرر يثبتان أن الكلمة لم تضع، ويحوّلان ما حسبوه حديثًا عابرًا إلى جريمة محفوظة محاسب عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص392، تحت «علة التعبير بلفظ السمع».","url":""}]},{"id":"s3-681","number":681,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"لماذا حكى مقالتهم البشعة نصًا: ﴿إن الله فقير ونحن أغنياء﴾؟","answer":"حكاها نصًا لتقوم الحجة بعين لفظهم، ولتظهر شناعة الافتراء والمفاخرة: أكدوا بـ﴿إن﴾ زعم فقر الله، وجاؤوا بواو الحال في ﴿ونحن أغنياء﴾ ليجعلوا غناهم الموهوم في مقابلة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص392، تحت «بلاغة توكيد المقولة».","url":""}]},{"id":"s3-682","number":682,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿سنكتب ما قالوا﴾، وكيف يُكتب القول؟","answer":"أي سنثبت مقالتهم ونحفظها في صحائف أعمالهم لتبقى حجة عليهم ويجازوا بها؛ فالقول يكتب بكتابة ألفاظه وإثبات تبعته، والسين وعيد بأن الجريمة لن تنسى أو تهمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص392، تحت «دلالة السين في فعل الكتابة».","url":""}]},{"id":"s3-683","number":683,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"لماذا عطف ﴿وقتلهم الأنبياء بغير حق﴾ على مقالتهم؟","answer":"لأن جرأة اللسان في قولهم على الله امتداد لجرأة الفعل على رسله؛ فجمع شاهد العقيدة الفاسدة وشاهد التاريخ الإجرامي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص393، تحت «بلاغة العطف في جملة قتل الأنبياء».","url":""}]},{"id":"s3-684","number":684,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿ونقول ذوقوا عذاب الحريق﴾؟","answer":"استعير ﴿ذوقوا﴾ للمباشرة والإحساس الذي يختبره المعذب بنفسه، فصار العذاب كأنه شيء يباشر أثره ولا يسمع خبره فقط؛ و﴿الحريق﴾ نار ملتهبة تحرق وتلازم الإحراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص394، تحت «وجوه المبالغة في مقولة إذاقة عذاب الحريق».","url":""}]},{"id":"s3-685","number":685,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بما قدمت أيديكم﴾ مع أن الذنوب ليست كلها باليد؟","answer":"الأيدي كناية عن الإنسان وأعماله لأنها أبرز آلات الكسب والمباشرة؛ فالمعنى: ذلك بسبب ما عملتموه باختياركم، لا أن كل ذنب وقع بالجارحة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص395، تحت «بديع المجاز في لفظ الأيدي».","url":""}]},{"id":"s3-686","number":686,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"لماذا عبّر عن الأعمال الماضية بأنها ﴿قدمت﴾؟","answer":"لأن الأعمال تسبق أصحابها إلى موقف الحساب كأنهم أرسلوها أمامهم، ثم يلقون ما ترتب عليها؛ فـ﴿قدمت﴾ تصل فعل الدنيا بنتيجته الآتية في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص395، تحت «بديع المجاز في لفظ الأيدي».","url":""}]},{"id":"s3-687","number":687,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن الله ليس بظلام للعبيد﴾ بصيغة المبالغة؟","answer":"جاءت الصيغة باعتبار كثرة العبيد وكثرة ما يحكم فيه بينهم؛ فنفى الله عن نفسه تكرر الظلم أو وقوع شيء منه في أي عبد، فالعذاب أثر ما قدموه لا جور في الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص397، تحت «فائدة التعبير بصيغة المبالغة في ﴿بظلام﴾».","url":""}]},{"id":"s3-688","number":688,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما دلالة نسبتهم طلبهم إلى عهد إلهي في قولهم: ﴿إن الله عهد إلينا﴾؟","answer":"نسبوا اشتراطهم إلى عهد من الله ليصوروا امتناعهم من التصديق التزامًا دينيًا لا تعنتًا منهم؛ فجاء الرد بتكذيب دعواهم من تاريخهم مع الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص404–405، تحت «بلاغة التضمين في جملة العهد».","url":""}]},{"id":"s3-689","number":689,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما سرّ اشتراطهم قربانًا ﴿تأكله النار﴾؟","answer":"زعموا أن علامة الرسول المقبول أن يقدم ما يتقرب به إلى الله، فتنزل نار فتستوفيه وتحرقه؛ فجعلوا أكل النار للقربان آية حسية اشترطوها للإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص405–406، تحت «بلاغة المجاز والاستعارة في أكل النار».","url":""}]},{"id":"s3-691","number":691,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما دلالة ختام الرد بقوله تعالى: ﴿فلم قتلتموهم إن كنتم صادقين﴾؟","answer":"ختم باستفهام تقريعي يلزمهم بتاريخهم: إن كان الامتناع سببه حقًا غياب القربان، فلم قتل أسلافكم رسلًا جاؤوا به؟ فالشرط يهدم صدق الدعوى بالفعل المناقض لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص407–408، تحت «الشرط، وأثره في تجلية المعنى».","url":""}]},{"id":"s3-692","number":692,"surah":3,"verses":[184],"references":[{"surah":3,"verses":[184]}],"verseLabel":"آل عمران: 184","question":"ما دلالة قوله تعالى: ﴿فإن كذبوك فقد كذب رسل من قبلك﴾ في تسلية النبي ﷺ؟","answer":"سلاه بأن التكذيب ليس خاصًا به ولا ناشئًا عن نقص في بيانه؛ فقد وقع لرسل قبله جاءوا بأجناس الحجج والوحي، فله في ثباتهم أسوة وعاقبة المكذبين معلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص408، تحت «دلالة الفاء في جملة الشرط».","url":""}]},{"id":"s3-693","number":693,"surah":3,"verses":[184],"references":[{"surah":3,"verses":[184]}],"verseLabel":"آل عمران: 184","question":"ما دلالة الجمع بين ﴿البينات والزبر والكتاب المنير﴾؟","answer":"جمع أجناس الحجة التي جاء بها الرسل: دلائل ومعجزات ظاهرة، وصحفًا مكتوبة فيها المواعظ، وكتابًا وحيانيًا ينير طريق الحق؛ فالتكذيب وقع مع اكتمال البرهان والتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص409، تحت «فائدة العطف في الآية».","url":""}]},{"id":"s3-694","number":694,"surah":3,"verses":[184],"references":[{"surah":3,"verses":[184]}],"verseLabel":"آل عمران: 184","question":"ما سرّ وصف الكتاب بـ﴿المنير﴾؟","answer":"لأنه يبين الحق ويفصل الهدى من الضلال، فشبه أثره في البصائر بأثر النور في الأبصار؛ لا يترك طالب الحق في ظلمة الالتباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص410–411، تحت «بيان المجاز في وصف المنير».","url":""}]},{"id":"s3-695","number":695,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿كل نفس ذائقة الموت﴾، وهل الموت يُذاق؟","answer":"استعير الذوق للمباشرة الشخصية التي لا ينوب فيها أحد عن أحد؛ واسم الفاعل يقرر تحقق التجربة لكل نفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص417، تحت «بلاغة المجاز في لفظ التذوق».","url":""}]},{"id":"s3-696","number":696,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿ذائقة﴾ باسم الفاعل لا: تذوق؟","answer":"اسم الفاعل في ﴿ذائقة﴾ يثبت الصفة لصاحبها ويقرر تحققها، وهو أرسخ من فعل عابر مقيد بزمن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–421، تحت «وجه التحقيق في جملة المجازاة».","url":""}]},{"id":"s3-697","number":697,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما دلالة القصر في قوله تعالى: ﴿وإنما توفون أجوركم يوم القيامة﴾ مع وجود جزاء في الدنيا؟","answer":"﴿إنما﴾ تقصر تمام الاستيفاء على يوم القيامة: هناك تعطى الأجور كاملة بلا نقص، أما ما يقع في الدنيا أو البرزخ فبعض الجزاء أو مقدماته، فلا يناقض التوفية الأخيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418، تحت «براعة أسلوب القصر».","url":""}]},{"id":"s3-698","number":698,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ تصوير النجاة بقوله تعالى: ﴿فمن زحزح عن النار﴾؟","answer":"الزحزحة تنحية بجذب متكرر عاجل، فصورت الإنسان مشرفًا على نار هائلة لا يبعد عنها إلا بجهد ورحمة متجددة؛ لذلك كان مجرد إبعاده عنها فوزًا عظيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص419، تحت «سر إيثار فعل الزحزحة».","url":""}]},{"id":"s3-699","number":699,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"لماذا قدّم الزحزحة عن النار على إدخال الجنة؟","answer":"لأن النجاة من أعظم مرهوب مقدمة الفوز، ثم يكتمل بإدخال الجنة؛ فجمع دفع الشر وجلب الخير ورتبهما بحسب المرور يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص419، تحت «سر إيثار فعل الزحزحة».","url":""}]},{"id":"s3-700","number":700,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما دلالة الإيجاز والتوكيد في قوله تعالى: ﴿فقد فاز﴾؟","answer":"﴿قَدْ﴾ تحقق الفوز، والفعل الموجز ﴿فَازَ﴾ يجمع النجاة من المكروه والظفر بالمطلوب: الزحزحة عن النار ودخول الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص420، تحت «بلاغة الإيجاز في جملة المجازاة».","url":""}]},{"id":"s3-701","number":701,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما سرّ وصف الحياة الدنيا بأنها ﴿متاع الغرور﴾؟","answer":"لأنها منفعة مؤقتة تشبه سلعة يدلس بها على المشتري فيعجب بظاهرها ثم يتبين زوالها؛ فالإضافة تكشف أن التعلق بها ناشئ من غرورها، لا من دوام حقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص421، تحت «براعة الاستعارة، أو التشبيه البليغ في الفاصلة».","url":""}]},{"id":"s3-702","number":702,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]},{"surah":21,"verses":[35]},{"surah":29,"verses":[57]}],"verseLabel":"آل عمران: 185؛ الأنبياء: 35؛ العنكبوت: 57","question":"لماذا تكررت ﴿كل نفس ذائقة الموت﴾ ثم اختلف ما بعدها في آل عمران والأنبياء والعنكبوت؟","answer":"آل عمران في سياق العمل والجزاء فأتبعها بتوفية الأجور والفوز، والأنبياء في سياق الابتلاء فأتبعها بفتنة الخير والشر، والعنكبوت في سياق الهجرة والرجوع فأتبعها بالرجوع إلى الله؛ فالحقيقة الواحدة صارت مدخلًا للغرض الذي تعالجه كل سورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–422، تحت «براعة الاستعارة، أو التشبيه البليغ في الفاصلة».","url":""}]},{"id":"s3-703","number":703,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"لماذا قدّم الابتلاء في الأموال على الأنفس؟","answer":"قدم المال على النفس على سبيل الترقي من الأدنى إلى الأشرف والأعز؛ فابتلاء المال شديد، ثم يبلغ الابتلاء ذروته حين يمس النفس بالجراح والمرض والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص426، تحت «نكتة تقديم الأموال على الأنفس».","url":""}]},{"id":"s3-704","number":704,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"ما دلالة توكيد الابتلاء بلام القسم ونون التوكيد في ﴿لتبلون﴾ و﴿لتسمعن﴾؟","answer":"أكدهما بلام القسم ونون التوكيد الثقيلة ليوقن المؤمنون أن الابتلاء والأذى واقعان، فلا يفاجئهم وقوعهما، ويتهيؤوا لهما بالصبر والتقوى والاعتماد على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص425–426، تحت «بلاغة تأكيد المطلع».","url":""}]},{"id":"s3-705","number":705,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتسمعن... أذى كثيرًا﴾، فجعل الأذى مسموعًا؟","answer":"لأن الأذى هنا قول يطعن في الدين والكتاب والرسول، فسمعوا الكلام المؤذي نفسه؛ لذلك جعل ﴿أذى﴾ مفعولًا للسماع، ووصفه بالكثرة لتعدد قدره وأنواعه وطرائقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص427، تحت «علة التعبير عن نزول الأذى بسماعه».","url":""}]},{"id":"s3-706","number":706,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"لماذا جمع أذى أهل الكتاب والمشركين في آية واحدة؟","answer":"ليتهيأ المؤمنون لاجتماع مصادر العداوة المختلفة على أذاهم، فلا يفاجئهم صدوره ممن عنده كتاب ولا ممن يعلن الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص426–427، تحت «وجه التفريق بين من أوتوا الكتاب ومن أشركوا».","url":""}]},{"id":"s3-707","number":707,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن تصبروا وتتقوا فإن ذلك من عزم الأمور﴾؟","answer":"الصبر يضبط احتمال الأذى، والتقوى تضبط الرد عليه، ووصفهما بالعزم لأن الثبات الأخلاقي عند الاستفزاز يحتاج إرادة راسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص431–434، تحت «العزم والحزم».","url":""}]},{"id":"s3-708","number":708,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ أخذ الله ميثاق الذين أوتوا الكتاب﴾؟","answer":"استحضر وقت أخذ الله العهد المؤكد على علماء أهل الكتاب أن يبينوا ما في كتابهم ولا يكتموه؛ فذكر الميثاق يجعل كتمانهم خيانة لعهد معلوم، لا مجرد تقصير عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص435، تحت «دلالة الميثاق على العموم».","url":""}]},{"id":"s3-709","number":709,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"ما دلالة تقديم ﴿لتبيننه للناس﴾ على ﴿ولا تكتمونه﴾؟","answer":"لأن الأمر بالبيان العام هو الأصل الأعم، وثبوته يستلزم ترك الكتمان؛ ثم صرح بالنهي عن الكتمان دفعًا لتوهم أن يكفي بيان بعض الحق لبعض الناس مع إخفاء بقيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص437، تحت «سر تقديم التبيان على عدم الكتمان».","url":""}]},{"id":"s3-710","number":710,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"لماذا صوّر ترك الميثاق بقوله ﴿فنبذوه وراء ظهورهم﴾؟","answer":"صوّر إهمال الميثاق بكتاب يُرمى خلف الظهر فلا يُرى ولا يُرجع إليه؛ وهي أبلغ من مجرد الترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص438–439، تحت «بلاغة الاستعارة الترشيحية في لفظ النبذ».","url":""}]},{"id":"s3-711","number":711,"surah":3,"verses":[187],"references":[{"surah":3,"verses":[187]}],"verseLabel":"آل عمران: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿واشتروا به ثمنًا قليلًا﴾؟","answer":"صور خيانتهم صفقة: بذلوا الميثاق وما في الكتاب ثمنًا، وأخذوا مقابله رشى وجاهًا ومنافع دنيوية زائلة؛ فسمي العوض قليلًا لهوانه أمام الحق الذي فرطوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص439، تحت «بلاغة المجاز المرسل في لفظ الاشتراء».","url":""}]},{"id":"s3-714","number":714,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما دلالة الجمع بين قوله تعالى: ﴿يفرحون بما أتوا﴾ و﴿يحبون أن يحمدوا بما لم يفعلوا﴾؟","answer":"علق الحكم بموصول يجمع خصلتين: الإعجاب بما أتوه من باطل، وطلب الحمد على خير لم يفعلوه؛ ثم نهى عن حسبان نجاتهم ليهدم تزكيتهم لأنفسهم واغترارهم بثناء الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص446–447، تحت «سر التعبير بالاسم الموصول».","url":""}]},{"id":"s3-715","number":715,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"لماذا جمع بين الفرح بالعمل وحب الحمد بغير عمل؟","answer":"الأول إعجاب بالباطل الذي فعلوه، والثاني طلب منزلة لم يحققوها؛ فجمع فساد تقييم العمل وفساد طلب السمعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص446–447، تحت «سر التعبير بالاسم الموصول».","url":""}]},{"id":"s3-716","number":716,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما دلالة تكرار النهي في قوله تعالى: ﴿فلا تحسبنهم بمفازة من العذاب﴾ بعد قوله: ﴿لا تحسبن الذين يفرحون﴾؟","answer":"طالت الصلة بذكر حالين، فأعيد النهي في ﴿فَلَا تَحْسَبَنَّهُمْ﴾ لتجديد التحذير وإبراز نتيجته: أنهم ليسوا بمنجاة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص447، تحت «سر إعادة فعل الحسبان».","url":""}]},{"id":"s3-717","number":717,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿بمفازة من العذاب﴾، فجعل النجاة مكانًا؟","answer":"المفازة مصدر للفوز والسلامة، وتستعمل أيضًا لمكان النجاة؛ فصورهم كمن يطلب موضعًا آمنًا يفصل بينه وبين العذاب، ثم نفى أن يكونوا في شيء من ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص451، تحت «مفازة ومنجاة».","url":""}]},{"id":"s3-718","number":718,"surah":3,"verses":[188],"references":[{"surah":3,"verses":[188]}],"verseLabel":"آل عمران: 188","question":"ما مناسبة ختام الآية بقوله تعالى: ﴿ولهم عذاب أليم﴾؟","answer":"لم يكتف بنفي المفازة، بل أثبت لهم العذاب اختصاصًا بتقديم ﴿لهم﴾، ووصفه بـ﴿أليم﴾ أي ثابت الألم شديده؛ فانتقل من إبطال وهم النجاة إلى تقرير المصير المقابل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص449، تحت «بلاغة التوكيد في الفاصلة».","url":""}]},{"id":"s3-719","number":719,"surah":3,"verses":[189],"references":[{"surah":3,"verses":[189]}],"verseLabel":"آل عمران: 189","question":"لماذا تكرر تقرير ملك السماوات والأرض قبيل آيات التفكر؟","answer":"ليجعل النظر في الكون نظرًا في ملك الله وآيات قدرته لا تأملًا منفصلًا عن العبادة، وليمهد للاستدلال من الخلق على الحكمة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص455، تحت «بلاغة الوصل في الآية».","url":""}]},{"id":"s3-720","number":720,"surah":3,"verses":[189],"references":[{"surah":3,"verses":[189]}],"verseLabel":"آل عمران: 189","question":"ما مناسبة الجمع بين ملك السماوات والأرض والقدرة على كل شيء في قوله تعالى: ﴿ولله ملك السماوات والأرض والله على كل شيء قدير﴾؟","answer":"ملك السماوات والأرض يثبت شمول السلطان، والقدرة على كل شيء تثبت نفاذه؛ فليس بعسير على مالك الكون أن يبعث الخلق ويحاسبهم، وهي مناسبة لما قبلها ولآيات التفكر بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص455، تحت «بلاغة الوصل في الآية».","url":""}]},{"id":"s3-721","number":721,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما دلالة التوكيد والجمع في قوله تعالى: ﴿إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات﴾؟","answer":"أكدت الجملة بـ﴿إِنَّ﴾ واللام، وجمعت ﴿آيَاتٍ﴾؛ لأن في أصل الخلق وتعاقب الليل والنهار دلائل كثيرة متجددة، لا علامة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص461، تحت «بديع التوكيد في مطلع الآية».","url":""}]},{"id":"s3-722","number":722,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"لماذا قدّم خلق السماوات والأرض على اختلاف الليل والنهار؟","answer":"قدم الأصل الجامع، وهو إنشاء جرمي السماوات والأرض، ثم ذكر الظاهرة المتجددة الواقعة فيهما، وهي تعاقب الليل والنهار؛ فانتقل من إيجاد محل الآيات إلى نظامها المشاهد المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص458–460، تحت «مناسبة الآية لما قبلها» في قوله تعالى: ﴿إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات لأولي الألباب﴾.","url":""}]},{"id":"s3-723","number":723,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سرّ تخصيص الانتفاع بهذه الآيات بـ﴿أولي الألباب﴾؟","answer":"لأن أولي الألباب هم أصحاب العقول الصافية من شوائب الكبر والعناد، فيعبرون من مشاهدة الخلق إلى معرفة الخالق؛ وفي التخصيص تعريض بمن يرى الآيات ولا ينتفع بعقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص465، تحت «الألباب والعقول».","url":""}]},{"id":"s3-724","number":724,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما دلالة ترتيب أحوال الذكر في قوله تعالى: ﴿قيامًا وقعودًا وعلى جنوبهم﴾؟","answer":"رتب أشهر هيئات الإنسان من الأكمل قدرة إلى ما دونها: قائمًا، ثم قاعدًا، ثم مضطجعًا على جنبه؛ ليدل على دوام ذكر الله في جميع الأحوال وعدم سقوطه بالعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص469–470، تحت «بلاغة الفصل في الآية».","url":""}]},{"id":"s3-725","number":725,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"لماذا انتقل من ذكر الله إلى التفكر في خلق السماوات والأرض؟","answer":"لأن الذكر يوقظ القلب والتفكر يقيم الدليل في العقل؛ وباجتماعهما تتحول مشاهدة الكون إلى معرفة وخشية ودعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص473، تحت «التفكر والتدبر».","url":""}]},{"id":"s3-726","number":726,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما دلالة اسم الإشارة المفرد في دعائهم: ﴿ربنا ما خلقت هذا باطلًا﴾؟","answer":"أفرد اسم الإشارة لأن السماوات والأرض واختلاف الليل والنهار نُظر إليها كنظام كوني واحد متماسك يشهد بالحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص472، تحت «سر التعبير باسم الإشارة».","url":""}]},{"id":"s3-727","number":727,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما مناسبة قولهم ﴿سبحانك﴾ بين الاعتراف بحكمة الخلق وطلب الوقاية من النار؟","answer":"لما قرروا أن الخلق ليس باطلًا، نزهوا الله بـ﴿سبحانك﴾ عن العبث وكل ما لا يليق بحكمته؛ ثم بنوا على هذا اليقين طلب الوقاية من النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص472، تحت «نكتة التعبير بالمصدر: ﴿سبحانك﴾».","url":""}]},{"id":"s3-728","number":728,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما مناسبة دعائهم: ﴿فقنا عذاب النار﴾ بعد التفكر في الكون؟","answer":"لأن التفكر أوصلهم إلى أن الخلق لحكمة وأن وراءه حسابًا؛ ففرعوا بالفاء على هذا الإقرار دعاء الوقاية من عذاب النار، لتصير المعرفة عملًا وخشية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص473، تحت «سر استعمال الفاء».","url":""}]},{"id":"s3-729","number":729,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما سرّ التعبير في قوله تعالى: ﴿إنك من تدخل النار فقد أخزيته﴾، فجعل دخول النار خزيًا؟","answer":"لأن دخول النار يجمع ألم العقوبة بانكشاف الخسارة والذل أمام الخلق؛ فالخزي انكسار وافتضاح وهوان، ومن أدخله الله النار فقد بلغ به ذلك غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص479، تحت «نكتة اصطفاء لفظي (الإدخال، والخزي) في مورد العذاب».","url":""}]},{"id":"s3-730","number":730,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما دلالة الجمع ودخول ﴿من﴾ في قوله تعالى: ﴿وما للظالمين من أنصار﴾؟","answer":"جمع ﴿أنصار﴾ ليستغرق كل صور النصرة والأعوان، وزيدت ﴿من﴾ في سياق النفي لتقرر أنه لا يوجد للظالمين ناصر واحد فضلًا عن جماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص479–480، تحت «بلاغة التعبير بلفظ ﴿للظالمين﴾».","url":""}]},{"id":"s3-731","number":731,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة الجمع بين الاسم والفعل من مادة واحدة في قوله تعالى: ﴿إننا سمعنا مناديًا ينادي للإيمان﴾؟","answer":"الجمع بين ﴿مُنَادِيًا﴾ و﴿يُنَادِي﴾ يثبت ذات المنادي ويستحضر تجدد ندائه، فيبرز قوة الدعوة ووضوح وصولها إلى السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص487، تحت «فائدة الجمع بين ﴿مناديًا﴾ و﴿ينادي﴾».","url":""}]},{"id":"s3-732","number":732,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"لماذا لم يصرّحوا باسم المنادي؟","answer":"لأن المقصود مضمون النداء وأثره لا ذات المنادي، ولأن إبهامه يفخمه: منادٍ عظيم الشأن يدعو إلى أعظم مطلوب وهو الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص486، تحت «نكتة تنوين لفظ المنادي».","url":""}]},{"id":"s3-733","number":733,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة تفسير النداء بقوله تعالى: ﴿أن آمنوا بربكم فآمنا﴾؟","answer":"جاءت ﴿أن آمنوا﴾ تفسيرًا لمضمون النداء حتى لا يبقى مجملًا، ثم دلت الفاء في ﴿فآمنا﴾ على أنهم بادروا إلى الامتثال فور سماعه بلا مكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص486، تحت «دلالة النداء للإيمان».","url":""}]},{"id":"s3-734","number":734,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"لماذا رتبوا الدعاء: مغفرة الذنوب، وتكفير السيئات، ثم الوفاة مع الأبرار؟","answer":"بدأوا بطلب غفران الذنوب رحمة وفضلًا، ثم تكفير السيئات بما شرع من الطاعات، ثم سألوا دوام البر وحسن الخاتمة حتى يتوفوا في زمرة الأبرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص489–490، تحت «وجه الجمع بين لفظي: الغفران والتكفير».","url":""}]},{"id":"s3-735","number":735,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة الجمع بين ﴿ذنوبنا﴾ و﴿سيئاتنا﴾ في الدعاء؟","answer":"إما أن الجمع للتوكيد واستيعاب التقصير كله، وإما لأن الذنب ما فيه عصيان وتقصير فيناسبه الغفران، والسيئة الفعلة القبيحة فيناسبها التكفير الذي يسترها ويعوض أثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص489، تحت «وجه الجمع بين لفظي: (الغفران، والتكفير)».","url":""}]},{"id":"s3-736","number":736,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما سرّ التعبير في دعائهم: ﴿وآتنا ما وعدتنا على رسلك﴾، دون أن يقال: على ألسنة رسلك؟","answer":"لأن الرسل أنفسهم حملة الوعد ومبلغوه، فنسب مجيء الوعد إليهم مباشرة: ما وعدتنا على أيدي رسلك وبسبب تصديقهم، وهو أوجز وأشمل من حصر التبليغ في الألسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص495، تحت «دلالة حرف الجر ﴿على﴾».","url":""}]},{"id":"s3-737","number":737,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"لماذا طلبوا إنجاز الوعد مع يقينهم أن الله لا يخلف الميعاد؟","answer":"ليس شكًا في الوعد، بل تضرع لطلب الدخول في أهله والثبات على أسبابه؛ فالخشية متجهة إلى تقصيرهم لا إلى خلف من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص497، تحت «الوعد والعهد».","url":""}]},{"id":"s3-738","number":738,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما سرّ تخصيص نفي الخزي بقولهم: ﴿يوم القيامة﴾؟","answer":"لأن خزي القيامة هو الأشد والأبقى: افتضاح أمام الخلق يعقبه مصير لا مهرب منه ولا فرصة لتداركه، فخصوه بالدعاء وإن وقعت صور من الخزي في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص497، تحت «الخزي والذل».","url":""}]},{"id":"s3-739","number":739,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما مناسبة ختم الدعاء بقولهم: ﴿إنك لا تخلف الميعاد﴾؟","answer":"ختموا بها تعليلًا لرجائهم وتثبيتًا لقلوبهم: طلبهم مبني على وعد صادق لا يتخلف، وهم يسألون أن يجعلهم الله من أهله؛ وفيها كمال اليقين مع كمال التضرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص495، تحت «بلاغة التأكيد والتعليل في الفاصلة».","url":""}]},{"id":"s3-740","number":740,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستجاب لهم ربهم﴾ لا ﴿فأجابهم﴾؟","answer":"الاستجابة تفيد قبول الدعاء وتحقيق مقتضاه، وإظهار ﴿ربهم﴾ يربط الإجابة بالتربية والرعاية والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص503، تحت «سر التعبير بـ(استجاب) دون (أجاب)».","url":""}]},{"id":"s3-741","number":741,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ إظهار وصف الربوبية في قوله تعالى: ﴿ربهم﴾؟","answer":"أظهر وصف الربوبية لأن استجابته لهم من إحسانه وتفضله ورعايته لعباده، ولأنهم كرروا دعاءه بقولهم ﴿ربنا﴾؛ فجاء ﴿ربهم﴾ مشعرًا بالشفقة والقرب والتشريف وردِّ حسن دعائهم بمثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص504، تحت «نكتة اختيار اسم الله الرب»","url":""}]},{"id":"s3-742","number":742,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿أني لا أضيع عمل عامل منكم﴾، فجعل العمل شيئًا يضيع؟","answer":"صوّر العمل كشيء محفوظ يمكن أن يضيع، ثم نفى إضاعته؛ أي لا يُبطل الله ثواب عمل عامل ولا يدعه يذهب هدرًا، بل يحفظه لصاحبه ويجازيه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص505، تحت «نكتة التعبير عن ترك الإثابة بالإضاعة».","url":""}]},{"id":"s3-743","number":743,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة التصريح بقوله تعالى: ﴿من ذكر أو أنثى﴾ بعد عموم ﴿عامل﴾؟","answer":"جاء ﴿من ذكر أو أنثى﴾ بعد عموم ﴿عامل﴾ توكيدًا ورفعًا لتوهم أن الخطاب أو الوعد خاص بالرجال؛ فصرح بأن حفظ العمل والجزاء عليه يشمل الجنسين سواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص502، تحت «المعنى الإجمالي».","url":""}]},{"id":"s3-744","number":744,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"لماذا اعترض بقوله ﴿بعضكم من بعض﴾؟","answer":"اعتراض يقرر وحدة الأصل والتكليف والتناصر، وينفي أن يضيع عمل بسبب الذكورة أو الأنوثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص505، تحت «بلاغة الإطناب بالاعتراض».","url":""}]},{"id":"s3-745","number":745,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"لماذا رُتبت الأعمال: الهجرة، والإخراج، والأذى، والقتال، والقتل؟","answer":"تصاعدت من مفارقة الوطن، إلى الإكراه على الخروج، إلى تحمل الأذى، ثم مباشرة القتال، ثم بذل النفس؛ فوافق تصاعد الجزاء تصاعد التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص507، تحت «براعة حسن ترتيب المعطوفات».","url":""}]},{"id":"s3-746","number":746,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"لماذا أكّد التكفير والإدخال بلام ونون التوكيد؟","answer":"لتثبيت الوعد بعد ذكر أقصى التضحيات وقطع توهم ضياع شيء منها؛ فاللام والنون تنقلان الجزاء إلى وعد محقق مؤكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص509، تحت «سر تأكيد الخبر بـ﴿لأكفرن﴾ و﴿لأدخلنهم﴾».","url":""}]},{"id":"s3-747","number":747,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿ثوابًا من عند الله﴾ بعد تفصيل الجزاء؟","answer":"جاء ﴿ثوابًا﴾ توكيدًا لمعنى الجزاء المفصل قبله من التكفير وإدخال الجنات، و﴿من عند الله﴾ لتعظيم هذا الثواب وتشريفه وبيان أنه فضل خاص صادر من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص510، تحت «دلالة التنكير في ﴿ثوابًا﴾».","url":""}]},{"id":"s3-748","number":748,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة ختم الآية بقوله تعالى: ﴿والله عنده حسن الثواب﴾؟","answer":"ذُيّلت الآية بـ﴿والله عنده حسن الثواب﴾ لتقرير أن الجزاء الكامل الحسن مختص بالله ومدخر عنده، وتعظيم ما أعده للعاملين وترغيبهم فيه بعد تفصيل الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص511–512، تحت «نكتة التذييل في الفاصلة».","url":""}]},{"id":"s3-749","number":749,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]},{"surah":4,"verses":[124]}],"verseLabel":"آل عمران: 195؛ النساء: 124","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿مَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ مِنْ ذَكَرٍ أَوْ أُنْثَى﴾، وقوله تعالى في آل عمران: ﴿لَا أُضِيعُ عَمَلَ عَامِلٍ مِنْكُمْ مِنْ ذَكَرٍ أَوْ أُنْثَى﴾؟","answer":"في آل عمران: 195: في النساء سيقت قاعدة دخول الجنة، فذُكر الإيمان والعمل من الصالحات شرطًا للجزاء؛ وهنا سيق جواب الدعاء ووعد الجماعة المؤمنة، فنفى إضاعة عمل أي عامل منهم ثم صرح بشمول الذكر والأنثى.\n\nفي النساء: 124؛ آل عمران: 195: النساء تقرر قاعدة الجزاء بصيغة الشرط، فبدأت بالعمل ثم عممت فاعله. وآل عمران جواب دعاء، فبدأت بنفي إضاعة عمل أي عامل، تمهيدًا لما بعدها من أعمال المهاجرين والمجاهدين.","sources":[{"label":"[آل عمران: 195] موسوعة التفسير البلاغي، ج6، ص498–514؛ مسح عكسي","url":""},{"label":"[النساء: 124؛ آل عمران: 195] موسوعة التفسير البلاغي، ج6، ص498–514؛ وج8، ص93–102","url":""}]},{"id":"s3-750","number":750,"surah":3,"verses":[196],"references":[{"surah":3,"verses":[196]}],"verseLabel":"آل عمران: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يغرنك تقلب الذين كفروا في البلاد﴾، وما الصورة التي يرسمها ﴿تقلب﴾؟","answer":"التقلب هو تنقلهم وتصرفهم في البلاد للتجارة والمكاسب، وما يصاحبه من ظهور السعة والقوة؛ فنُهي عن أن يخدع هذا الازدهار العارض، لأن مآله متاع قليل ثم جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص518، تحت «بلاغة المجاز العقلي في قوله: ﴿لا يغرنك تقلب﴾».","url":""}]},{"id":"s3-751","number":751,"surah":3,"verses":[196],"references":[{"surah":3,"verses":[196]}],"verseLabel":"آل عمران: 196","question":"لماذا أُفرد خطاب النبي في نهي يراد به تثبيت المؤمنين؟","answer":"لأن ثبات القائد أبلغ طريق إلى تثبيت الجماعة، والخطاب له تشريف وتعليم لكل سامع؛ فإذا نُهي الرسول عن الاغترار بتقلب الكافرين فالأمة أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص517، تحت «دلالة الخطاب في ﴿لا يغرنك﴾».","url":""}]},{"id":"s3-753","number":753,"surah":3,"verses":[196],"references":[{"surah":3,"verses":[196]},{"surah":40,"verses":[4]}],"verseLabel":"آل عمران: 196؛ غافر: 4","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران: ﴿لا يغرنك تقلب الذين كفروا في البلاد﴾، وقوله في غافر: ﴿فلا يغررك تقلبهم في البلاد﴾؟","answer":"في آل عمران جاء النهي ابتداءً، وصرح بـ﴿الَّذِينَ كَفَرُوا﴾، وأكد الفعل بنون التوكيد الثقيلة: ﴿يَغُرَّنَّكَ﴾. وفي غافر جاء بالفاء نتيجةً لما قبلها، واكتفى بالضمير بعد ذكر الكافرين، وجاء الفعل مجزومًا بلا نون: ﴿يَغْرُرْكَ﴾؛ فناسب كل تعبير سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص519–521، تحت «توجيه المتشابه اللفظي».","url":""}]},{"id":"s3-754","number":754,"surah":3,"verses":[197],"references":[{"surah":3,"verses":[197]}],"verseLabel":"آل عمران: 197","question":"ما دلالة إيجاز نجاحهم الدنيوي في قوله تعالى: ﴿متاع قليل﴾؟","answer":"سمّاه ﴿متاعًا﴾ لأنه انتفاع عارض لا بقاء له، ووصفه بالقلة لقصر مدته وضآلة قدره أمام نعيم الآخرة أو عذابها؛ فاختصر بهما بريق نجاحهم كله وحقره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص519، تحت «بلاغة الفصل في قوله: ﴿متاع قليل﴾».","url":""}]},{"id":"s3-755","number":755,"surah":3,"verses":[197],"references":[{"surah":3,"verses":[197]}],"verseLabel":"آل عمران: 197","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم مأواهم جهنم﴾؟","answer":"﴿ثُمَّ﴾ تفيد التراخي الزمني، وتبرز كذلك البون بين المتاع العابر والمصير الثقيل. و﴿مَأْوَاهُمْ﴾ تسمي جهنم مقرهم النهائي بعد ذلك التقلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص519، تحت «دلالة حرف العطف ﴿ثم﴾».","url":""}]},{"id":"s3-756","number":756,"surah":3,"verses":[197],"references":[{"surah":3,"verses":[197]}],"verseLabel":"آل عمران: 197","question":"لماذا ختم بـ﴿وبئس المهاد﴾، وسمّى جهنم مهادًا؟","answer":"سمّى النار مهادًا على سبيل التهكم؛ فالمهاد موضع الراحة، أما هذا المهاد فغاية العذاب، وفي التضاد زيادة تهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص521، تحت «بلاغة الاستعارة التهكمية في قوله: ﴿ثم مأواهم جهنم وبئس المهاد﴾».","url":""}]},{"id":"s3-757","number":757,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الذين اتقوا ربهم﴾ بعد وصف حال الكافرين؟","answer":"جاءت ﴿لكن﴾ استدراكًا ينقل من تقلب الكافرين القصير ومأواهم في النار إلى المصير المقابل للمتقين: جنات خالدة ونزل من الله؛ فأتبع الوعيد بالوعد وأظهر التفاوت بين المآلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص527–528، تحت «بلاغة المقابلة».","url":""}]},{"id":"s3-758","number":758,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"ما دلالة قوله تعالى: ﴿لهم جنات تجري من تحتها الأنهار خالدين فيها﴾ في مقابلة ﴿متاع قليل﴾؟","answer":"جمع ﴿جنات﴾ ونكّرها للإشعار بكثرتها وتنوعها وتفاوت درجاتها بحسب الأعمال، ووصفها بجريان الأنهار لدوام زهرتها وتجدد نعيمها، ثم قال ﴿خالدين فيها﴾ ليقابل دوام نعيم المتقين قصر متاع الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص527–528، تحت «بلاغة المقابلة».","url":""}]},{"id":"s3-759","number":759,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"لماذا سمّى نعيم الجنة ﴿نزلًا من عند الله﴾؟","answer":"النزل ما يهيأ للضيف عند قدومه؛ فإذا كان نعيم الجنة مجرد نزل من عند الله فما بعده أعظم وأدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص528، تحت «سر التعبير بـ﴿نزلا﴾»","url":""}]},{"id":"s3-760","number":760,"surah":3,"verses":[198],"references":[{"surah":3,"verses":[198]}],"verseLabel":"آل عمران: 198","question":"ما سرّ التعبير بقوله تعالى: ﴿وما عند الله خير للأبرار﴾، دون: للمتقين كما في أول الآية؟","answer":"عدل من ﴿الذين اتقوا﴾ إلى ﴿الأبرار﴾ ليبين أن ما وصفوا به من التقوى والطاعة هو عين البر، وأنهم جمعوا الوصفين؛ ففي الإظهار تنويه بهم وإشعار بتداخل أعمال البر والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص530، تحت «نكتة وضع المظهر موضع المضمر».","url":""}]},{"id":"s3-761","number":761,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة قوله تعالى: ﴿وإن من أهل الكتاب لمن يؤمن بالله﴾ بعد الآيات التي نقدت مواقف فريق منهم؟","answer":"لئلا يعم النقد جميع أهل الكتاب؛ فبين أن منهم فريقًا آمن بالله والوحي وخشع ولم يبع الآيات، فهو داخل في وصف المتقين. وفي ذلك إنصاف يميز الصادقين من ناقضي الميثاق والمحرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص535، تحت «سبب وصل ﴿وإن من أهل الكتاب﴾ بما قبلها».","url":""}]},{"id":"s3-762","number":762,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"لماذا جمع بين ﴿ما أنزل إليكم وما أنزل إليهم﴾؟","answer":"ليثبت أن إيمان الصادقين من أهل الكتاب لا يتجزأ: يصدقون بالقرآن وبأصل الوحي الذي عندهم، فيلتقي التنزيلان عند مصدر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص536، تحت «نكات تقديم الإيمان بالقرآن على الإيمان بما أنزل إليهم».","url":""}]},{"id":"s3-763","number":763,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة وصفهم بقوله تعالى: ﴿خاشعين لله﴾ بين صفات الإيمان؟","answer":"لأن الخشوع أثر الإيمان الصادق في القلب: انقياد باطن لله مع الذل والافتقار والتأثر بجلاله؛ ومن ثمرته ألا يؤثر صاحبه عرض الدنيا على آيات الله، فوقع بين الإيمان وعدم بيع الآيات رابطًا بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص542–545، تحت «الخشوع والخضوع».","url":""}]},{"id":"s3-764","number":764,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة قوله تعالى: ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾ في مقابل من سبق ذكرهم؟","answer":"صوّر إيثار الدنيا على الوحي بصفقة يبيع فيها المرء آيات الله بثمن حقير؛ فنفى ذلك عن المؤمنين من أهل الكتاب مدحًا لهم، وعرّض بمن حرفوا وكتموا لقاء الرشوة، فظهر التباين بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص537، تحت «بلاغة المجاز في قوله: ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾».","url":""}]},{"id":"s3-765","number":765,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سرّ إضافة الأجر إليهم في قوله تعالى: ﴿أولئك لهم أجرهم عند ربهم﴾؟","answer":"أضاف الأجر إليهم في ﴿أجرهم﴾ للعهد والاختصاص؛ أي الأجر المعروف الموعود لهم، وقدم ﴿لهم﴾ لتأكيد أنه خاص بهؤلاء المؤمنين دون من بقي على رد القرآن وتحريف الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص539، تحت «فائدة الإضافة في قوله: ﴿أجرهم﴾».","url":""}]},{"id":"s3-766","number":766,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"لماذا ختم بـ﴿إن الله سريع الحساب﴾ في مقام الوعد؟","answer":"سرعة الحساب تطمئن إلى قرب الوفاء، وتحذر من توهم أن كثرة الخلق أو الأعمال تؤخر الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص540، تحت «نكتة الإتيان بجملة ﴿إن الله سريع الحساب﴾ بعد ذكر الأجر».","url":""}]},{"id":"s3-767","number":767,"surah":3,"verses":[77,199],"references":[{"surah":3,"verses":[77,199]}],"verseLabel":"آل عمران: 199؛ آل عمران: 77","question":"لماذا قوبل من ﴿يشترون بعهد الله وأيمانهم ثمنًا قليلًا﴾ بمن ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾ في آخر السورة؟","answer":"التركيب الواحد يقيم ميزانًا داخل أهل الكتاب: فريق باع العهد والآيات فعوقب بالحرمان، وفريق آمن وخشع ورفض البيع فثبت له الأجر؛ فالمقابلة تختم السورة بالإنصاف بعد النقد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص537، تحت «بلاغة المجاز في قوله: ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾».","url":""}]},{"id":"s3-768","number":768,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما دلالة اجتماع الأوامر الأربعة في خاتمة السورة: ﴿اصبروا وصابروا ورابطوا واتقوا الله﴾؟","answer":"خُتمت بها لأنها تجمع مقتضى ما سبق من العقائد والأحكام: صبر النفس على الطاعة والبلاء، ومغالبة الخصم في الصبر، والثبات لحراسة الدين ودفع العدوان، وجعل التقوى باعثًا وضابطًا لهذه الأعمال كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص548، تحت «براعة الختام في السورة».","url":""}]},{"id":"s3-769","number":769,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما الفرق بين ﴿اصبروا﴾ و﴿صابروا﴾، وما الذي زادته صيغة المفاعلة؟","answer":"﴿اصبروا﴾ أمر عام بحبس النفس على الطاعة وعن المعصية وعلى البلاء، ثم زادت صيغة المفاعلة في ﴿صابروا﴾ معنى مقابلة الخصم ومغالبته في الصبر حتى لا يكون أثبت منكم؛ فهي صبر مشترك أشد من الصبر الفردي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص546–547، تحت «بلاغة عطف الخاص على العام».","url":""}]},{"id":"s3-770","number":770,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما مناسبة إتباع الصبر والمصابرة بالأمر: ﴿ورابطوا﴾؟","answer":"لأن المرابطة مرحلة أزيد من مجرد الصبر ومغالبة الخصم فيه: ثبات دائم واستعداد في الثغور لحراسة الدين ودفع العدوان؛ فترقى الأمر من صبر النفس إلى مصابرة العدو ثم ملازمة موقع الحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص546–547، تحت «بلاغة عطف الخاص على العام».","url":""}]},{"id":"s3-771","number":771,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما دلالة ختم الأوامر بقوله تعالى: ﴿واتقوا الله﴾؟","answer":"لأن التقوى هي الدافع والضابط للأوامر السابقة: تحمل على الصبر، وتقوي المصابرة، وتصون المرابطة من الرياء أو العدوان؛ وهي أن يحذر المؤمن مخالفة أمر الله بتركه ونهيه بفعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص545–546، تحت «بلاغة عطف الخاص على العام».","url":""}]},{"id":"s3-772","number":772,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما دلالة تعليق الفلاح على هذه الأوامر في قوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"لأن الصبر والمصابرة والمرابطة والتقوى أسباب الفلاح؛ فجاء ﴿لعلكم﴾ ترغيبًا ورجاءً للمؤمنين أن يفضي امتثالهم إليها إلى الفوز بخير الدنيا والآخرة وإدراك الخير والبقاء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص548–549، تحت «براعة الختام في السورة».","url":""}]},{"id":"s4-1","number":1,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿اتَّقُوا رَبَّكُمُ﴾، دون أن يقال: اتقوا الله؟","answer":"افتتاح الخطاب باسم الرب يستحضر نعمة الخلق والتربية التي قررتها الآية، فيكون الأمر بالتقوى مبنيًا على رابطة الربوبية؛ ثم جاء الاسم الجليل في التقوى الثانية عند الحقوق التي يُتساءل بها والأرحام.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص575–576، تحت «بلاغة أسلوب الترقي في إقرار الألوهية».","url":""}]},{"id":"s4-2","number":2,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا وصف أصل البشر بأنه ﴿نَفْسٍ وَاحِدَةٍ﴾، ولم يصرح باسم آدم عليه السلام؟","answer":"جاء الوصف ﴿نفس واحدة﴾ لإبراز المعنى الجامع لا مجرد الاسم: فالناس جميعًا يرجعون إلى أصل إنساني واحد، ولذلك هم متساوون في أصل الخلقة ومتصل بعضهم ببعض وإن تباعدت أنسابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص572، تحت «دلالة حرف الجر ﴿من﴾ وتكراره».","url":""}]},{"id":"s4-3","number":3,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا اختير فعل ﴿بَثَّ﴾، ولم يقل: نشر منهما رجالًا ونساء؟","answer":"البث نشرٌ مع تفريق وتكثير في جهات واسعة، فهو يصور امتداد البشر من أصل واحد أجيالًا وأقطارًا، وهو أبلغ حركةً من مجرد النشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص565، تحت «شرح المفردات»، مدخل ﴿وبث﴾.","url":""}]},{"id":"s4-4","number":4,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿رِجَالًا كَثِيرًا وَنِسَاءً﴾، فوصف الرجال بالكثرة، دون أن يقال: ونساء كثيرات؟","answer":"ذِكر الكثرة مع الرجال يغني عنها في المعطوف، فالمعنى: رجالًا كثيرًا ونساءً كثيرات؛ وحذفها يمنع الثقل ويحفظ الفاصلة من غير أن ينفي كثرة النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص574، تحت «سر تخصيص الرجال بالكثرة دون النساء».","url":""}]},{"id":"s4-5","number":5,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا تكرر الأمر بالتقوى مرتين في آية واحدة: ﴿اتَّقُوا رَبَّكُمُ﴾ ثم ﴿وَاتَّقُوا اللَّهَ﴾؟","answer":"الأولى تقوى الرب الذي خلق البشر من نفس واحدة، والثانية تقوى الله في الحقوق المتبادلة والأرحام؛ فتجدد الأمر لاختلاف العلة والمجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص575، تحت «نكتة تكرار صيغة الأمر بالتقوي»","url":""}]},{"id":"s4-6","number":6,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا ختمت الآية بـ﴿رَقِيبًا﴾، ولم تختم بـ«حفيظًا» مثلًا؟","answer":"الرقيب من يلاحظ الشيء ولا يغيب عنه، وهو أنسب بأحكام الحقوق الخفية وصلات الأرحام؛ أما الحفظ فقد يدل على الصيانة، ولا يستحضر المراقبة والمحاسبة بالوضوح نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص580–581، تحت «الفروق المعجمية: الرقيب والحفيظ».","url":""}]},{"id":"s4-7","number":7,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿وَخَلَقَ مِنْهَا زَوْجَهَا﴾، بينما قال في الأعراف والزمر: ﴿وَجَعَلَ مِنْهَا زَوْجَهَا﴾؟","answer":"قال في النساء ﴿خلق منها زوجها﴾ لأن الكلام على أصل خلق آدم وحواء؛ والخلق ابتداء إيجاد. وقال في الأعراف والزمر ﴿جعل منها زوجها﴾ لأن الكلام على ما بعد ذلك من عموم بني آدم، أي جعل الأنثى زوجًا للذكر بعد خلقها؛ فالجعل حالة تالية للخلق في الغالب.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج2، ص32؛ منقول في Quranpedia، ملاحظة 48388","url":""}]},{"id":"s4-8","number":8,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى في حقوق اليتامى: ﴿وَآتُوا الْيَتَامَى أَمْوَالَهُمْ﴾، واختار الإيتاء دون الإعطاء؟","answer":"الإيتاء يشعر بإيصال الحق وتمكين صاحبه منه، لا بمجرد المناولة؛ ولذلك ناسب رد مال اليتيم كاملًا بوصفه حقًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص595، تحت «سر إيثار فعل الإيتاء على غيره».","url":""}]},{"id":"s4-9","number":9,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّهُ كَانَ حُوبًا كَبِيرًا﴾، واختار «الحوب» بدل «الإثم»؟","answer":"الحوب هو الإثم العظيم الذي يوقع في الحرج والهلاك، وفي اللفظ زجر أشد من الاسم العام للإثم، ولا سيما في أكل مال اليتيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص599–600، تحت «علة إيثار لفظ (الحوب) منكرًا».","url":""}]},{"id":"s4-10","number":10,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما الصلة بين الخوف من عدم القسط في اليتامى وبين قوله مباشرة: ﴿فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ﴾؟","answer":"الشرط والجواب مرتبطان: إذا خاف الولي ألا يعدل في اليتيمة التي تحت ولايته، في مهرها وحقوقها، ترك الزواج بها وتزوج من غيرها؛ فقد وسّع الله له الاختيار، فلا يحمله طلب الزواج على ظلمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص600، تحت عنوان «بلاغة التعبير بـ﴿وإن﴾ الشرطية»","url":""}]},{"id":"s4-11","number":11,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا طَابَ لَكُمْ﴾، دون أن يقال: من طاب لكم؟","answer":"أوثر ﴿ما﴾ لأن المقصود وصف النساء اللاتي يحل نكاحهن والصنف الطيب المباح منهن؛ فالنظر هنا إلى الصفة والحكم، لا إلى مجرد ذوات أشخاص معينين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص602–603، تحت «إيثار التعبير بالاسم الموصول ﴿ما﴾ دون ﴿من﴾».","url":""}]},{"id":"s4-12","number":12,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾، دون أن يقال: اثنتين أو ثلاثًا أو أربعًا؟","answer":"هذه صيغ توزيع على جماعة المخاطبين: فمنهم من يختار اثنتين، ومنهم من يختار ثلاثًا أو أربعًا، وليس المراد جمع الأعداد لكل واحد. ولهذا كان التعبير مناسبًا لاختلاف اختيار المخاطبين مع الوقوف عند العدد المأذون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص603–604، تحت عنوان «سر العطف بالواو في ﴿مثنى وثلاث ورباع﴾»","url":""}]},{"id":"s4-13","number":13,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا عطف الأعداد بالواو: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾، ولم يعطفها بـ«أو» الدالة على التخيير؟","answer":"جاءت الواو للتقسيم والجمع على سبيل البدل: فمن المخاطبين من يختار اثنتين، ومنهم من يختار ثلاثًا، ومنهم من يختار أربعًا؛ وليست لجمع هذه الأعداد في ذمة رجل واحد، وإلا لقيل تسعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص603–604، تحت «سر العطف بالواو في ﴿مثنى وثلاث ورباع﴾».","url":""}]},{"id":"s4-14","number":14,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكَ أَدْنَى أَلَّا تَعُولُوا﴾، واختار هذا التعبير دون التصريح بـ«ألا تجوروا»؟","answer":"﴿تعولوا﴾ كناية عن الميل والجور؛ فأدى التعبير المعنى بطريق ألطف وأبلغ من التصريح بـ«تجوروا»، وجعل العدل كأنه استقامة يقابلها ميل الميزان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص604، تحت «بلاغة التعبير عن العول بالكناية».","url":""}]},{"id":"s4-15","number":15,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا سمى المهور ﴿صَدُقَاتِهِنَّ﴾، ولم يقل: مهورهن؟","answer":"اشتق الاسم من الصدق؛ لأن المهر علامة صدق الرغبة في النكاح وتكريم المرأة، لا ثمنًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص605، تحت «نكتة اصطفاء لفظ الصدقة».","url":""}]},{"id":"s4-16","number":16,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا وصف إعطاء المهر بأنه ﴿نِحْلَةً﴾؟","answer":"وُصف المهر بالنحلة ليؤدَّى عن طيب نفس وسماحة، وليُبعد عن معنى الثمن والعوض المالي. وهو حق واجب للمرأة فرضه الله، لا تفضّل من الزوج عليها؛ فسماه هدية واجبة إكرامًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص606–607، تحت عنوان «تنوع دلالة النحلة بين الزوج والزوجة»","url":""}]},{"id":"s4-17","number":17,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا خُص الأكل بالذكر في قوله تعالى: ﴿فكلوه هنيئًا مريئًا﴾؟","answer":"المقصود إباحة الانتفاع بما طابت نفس المرأة ببذله من مهرها، وذُكر الأكل لأنه معظم وجوه التصرف المالي، فيشمل الإذن سائر التصرفات المباحة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص608، تحت عنوان «نكتة تخصيص لفظ (الأكل) بالذكر»","url":""}]},{"id":"s4-472","number":472,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما دلالة الجمع بين ﴿هنيئًا مريئًا﴾ في الإذن بالانتفاع بما طابت به نفس المرأة؟","answer":"هما وصفان لما يسوغ من الطعام ولا تنغيص فيه، وفي ورودهما هنا تأكيد لحل الانتفاع ومبالغة في الإباحة وإزالة التبعة عما بُذل عن طيب نفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص608، تحت عنوان «سر تذييل الفاصلة بالوصفين ﴿هنيئًا مريئًا﴾»","url":""}]},{"id":"s4-18","number":18,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا سمى أموال السفهاء ﴿أَمْوَالَكُمُ﴾، مع أنها أموالهم هم؟","answer":"أضاف أموال السفهاء إلى الجماعة لأن المال قوام المجتمع ولأن الولي مؤتمن عليه كأنه ماله؛ فيمنعه ذلك من إضاعته كما يمنع إضاعة مال نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص609، تحت «التعريف بالإضافة».","url":""}]},{"id":"s4-19","number":19,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا وصف الأموال بأنها ﴿الَّتِي جَعَلَ اللَّهُ لَكُمْ قِيَامًا﴾؛ وكيف يكون المال قيامًا للناس؟","answer":"المال مما يقيم شؤون الناس ويصلح أحوالهم؛ فوصفه بأنه قيام يبين حاجتهم إليه في مصالحهم ومعاشهم، وحاجتهم إلى حفظه وحسن تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص609، تحت عنوان «توجيه القراءات في لفظ ﴿قيامًا﴾»","url":""}]},{"id":"s4-20","number":20,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿وَارْزُقُوهُمْ فِيهَا﴾، دون أن يقال: وارزقوهم منها؟","answer":"﴿فيها﴾ تدعو إلى تنمية أصل المال والإنفاق من ريعه، كأن الرزق واقع في محيط المال لا مقتطع من أصله حتى يفنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص610، تحت «سر إيثار ﴿في﴾».","url":""}]},{"id":"s4-21","number":21,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ آنَسْتُمْ مِنْهُمْ رُشْدًا﴾، دون أن يقال: فإن علمتم منهم رشدًا؟","answer":"الإيناس إدراك يتولد من أمارات متكررة ظاهرة، فليس المطلوب ظن الرشد أو معرفته مرة، بل اختباره حتى يطمئن الولي إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص613، تحت «علة إيثار لفظ الإيناس على غيره».","url":""}]},{"id":"s4-22","number":22,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا أمر بالإشهاد عند دفع مال اليتيم: ﴿فَأَشْهِدُوا عَلَيْهِمْ﴾، ثم ختم بـ﴿وَكَفَى بِاللَّهِ حَسِيبًا﴾؟","answer":"أُمر بالإشهاد لحفظ الحق وقطع النزاع في الظاهر، ثم خُتم بـ﴿وكفى بالله حسيبًا﴾ ليعلم الولي أن الشهود لا يغنون عن رقابة الله وحسابه؛ فهو الكافي في الشهادة والمحاسب على الخفي والظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص616–618","url":""}]},{"id":"s4-23","number":23,"surah":4,"verses":[3],"references":[{"surah":4,"verses":[3]}],"verseLabel":"النساء: 3","question":"ما الفرق بين التعبير بـ﴿أَلَّا تُقْسِطُوا فِي الْيَتَامَى﴾ والتعبير بـ﴿أَلَّا تَعْدِلُوا﴾ في تعدد الزوجات؟","answer":"القسط استعمل مع حقوق اليتامى لأنه العدل في الحكم وإيصال الحق، ثم استعمل العدل في تعدد الزوجات لأنه التسوية المطلوبة في المعاملة والنفقة؛ فتقارب المعنى لا يلغي دقة كل مقام.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 43211","url":""}]},{"id":"s4-24","number":24,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا كرر: ﴿لِلرِّجَالِ نَصِيبٌ﴾ و﴿وَلِلنِّسَاءِ نَصِيبٌ﴾، ولم يجمعهما في عبارة واحدة؟","answer":"كرر ﴿نصيب﴾ وأعاد لام الاستحقاق ليقرر حق كل من الرجال والنساء مستقلًا تقريرًا لا يحتمل التبعية أو السقوط، وليؤكد خصوصًا أن نصيب النساء فرض ثابت بعد أن كانت الجاهلية تحرمهن منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص624، تحت «فائدة تكرار لفظ النصيب».","url":""}]},{"id":"s4-25","number":25,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"ما سرّ تقديم الرجال على النساء في آية الميراث؟","answer":"قدم الرجال لأن السياق يراعي ما حمّلوا من القوامة والنفقة والمسؤولية الأسرية؛ فكان تقديم ذكرهم مناسبًا لهذا التكليف، مع إثبات حق النساء مستقلًا عقبهم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص623، تحت «سر تقديم الرجال على النساء».","url":""}]},{"id":"s4-26","number":26,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا ذكر ﴿الْوَالِدَانِ﴾ ثم ﴿الْأَقْرَبُونَ﴾، مع أن الوالدين من الأقربين؟","answer":"خُص الوالدان بالذكر أولًا مع دخولهما في الأقربين لشدة قرابتهما وعظم منزلتهما وأصالتهما في باب الميراث، ثم جاء ﴿الأقربون﴾ ليعم سائر المستحقين بحسب درجات القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص624–625، تحت «الإطناب البلاغي بذكر العام بعد الخاص».","url":""}]},{"id":"s4-27","number":27,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا أعاد قوله: ﴿مِمَّا تَرَكَ الْوَالِدَانِ وَالْأَقْرَبُونَ﴾، ولم يكتف بضمير يعود إلى المذكور؟","answer":"أعيدت العبارة ظاهرة مع نصيب النساء ليأتي حكمهن مستقلًا كاملًا كحكم الرجال، وليتقرر أن مصدر استحقاق الفريقين واحد: ما ترك الوالدان والأقربون، فلا يبدو حق النساء تابعًا أو مفهومًا بطريق الضمير فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص626، تحت «بلاغة الإظهار في موضع الإضمار».","url":""}]},{"id":"s4-28","number":28,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"ما سرّ التعبير في قوله تعالى: ﴿نَصِيبًا مَفْرُوضًا﴾، دون أن يقال: حظًا معلومًا؟","answer":"النصيب حصة مخصوصة، و﴿مفروضًا﴾ تثبت أنها مقدرة ملزمة من الله لا منحة عائلية قابلة للمنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص628، تحت «بلاغة الإيجاز بالحذف، ودلالة الاختزال بـ﴿مفروضًا﴾».","url":""}]},{"id":"s4-29","number":29,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا حَضَرَ الْقِسْمَةَ﴾ بـ«إذا»، دون أن يقال: وإن حضر القسمة؟","answer":"جيء بـ﴿إذا﴾ لأن حضور هؤلاء عند قسمة الميراث أمر متوقع كثير الوقوع، فصيغ الحكم على تحقق الحالة؛ أما ﴿إن﴾ فتناسب ما يشك في حصوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص630، تحت «نكتة التعبير بـ﴿واذا﴾ دون ان»","url":""}]},{"id":"s4-30","number":30,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا سمى ما يعطى الحاضرين عند القسمة رزقًا: ﴿فَارْزُقُوهُمْ مِنْهُ﴾، ولم يقل: فأعطوهم؟","answer":"سماه رزقًا ليشعرهم أن ما يصل إليهم ساقه الله من غير منة من الورثة، وليطيب نفوسهم وهم يشهدون قسمة المال؛ فليس مجرد مناولة، بل رزق يسد شيئًا من الحاجة ويصون الخاطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص634–636، تحت «علة تسمية العطاء رزقًا».","url":""}]},{"id":"s4-31","number":31,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"لماذا جمع بين الأمر بالتقوى والأمر بالقول السديد في حماية اليتامى؟","answer":"أمر بالتقوى لتضبط باطن الولي وخشيته من ظلم اليتيم، وبالقول السديد ليكون خطابه ووصيته مستقيمين مصيبين للحق؛ فحماية اليتيم تحتاج رقيبًا في القلب واستقامة في القول والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص646–649، تحت «نكتة التفريع بالفاء في فعل الاتقاء».","url":""}]},{"id":"s4-32","number":32,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"ما سرّ التعبير في قوله تعالى: ﴿قَوْلًا سَدِيدًا﴾ هنا، بينما قال قبلها: ﴿قَوْلًا مَعْرُوفًا﴾؟","answer":"السديد هو المصيب المستقيم الذي يسد موضع الخلل؛ فناسب مقام الوصية بحماية اليتيم، أما المعروف ففي مقام الملاطفة والعطاء لمن حضر القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص640، تحت «شرح المفردات»، مدخل ﴿سديدًا﴾.","url":""}]},{"id":"s4-33","number":33,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"ما سر الصورة المروعة في قوله: ﴿يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا﴾، مع أنهم يأكلون أموالًا؟","answer":"صوّر المال الحرام بحقيقته التي يصير إليها: نارًا تملأ البطون؛ فانتقل من ظاهر اللذة العاجلة إلى باطن العاقبة المروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص652–653، تحت «بلاغة المجاز المرسل في التنبيه على أداء حقوق الضعفاء».","url":""}]},{"id":"s4-34","number":34,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَسَيَصْلَوْنَ سَعِيرًا﴾ بالسين، ولم يأت بها في فعل الأكل؟","answer":"لم تدخل السين على الأكل لأنه فعلهم الواقع الآن، ودخلت على ﴿سيصلون﴾ لأن صلي السعير جزاؤهم المستقبل؛ وهي مع ذلك تقرب الوعيد وتجعله كأنه وشيك محقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص654، تحت «سر دخول السين في فعل الصلي دون الأكل».","url":""}]},{"id":"s4-35","number":35,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿يُوصِيكُمُ اللَّهُ﴾، دون أن يقال: نوصيكم؟","answer":"إظهار الاسم الجليل يرفع الحكم من عرف الأسرة إلى وصية الله الملزمة، ويورث المهابة والتسليم في موضع تنازع النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص664–665، تحت «براعة إظهار فاعل الإيصاء».","url":""}]},{"id":"s4-36","number":36,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي أَوْلَادِكُمْ﴾، دون أن يقال: في أبنائكم؟","answer":"الأولاد يشملون الذكور والإناث، بخلاف الأبناء الذي قد يتبادر منه الذكور؛ فاختير اللفظ الأجمع لأصحاب الأنصبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص665، تحت «التعبير بـ﴿الأولاد﴾ دون ﴿الأبناء﴾ وغيره».","url":""}]},{"id":"s4-37","number":37,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ﴾، دون أن يقال: للرجل مثل حظ المرأتين؟","answer":"اختير الذكر والأنثى لأن الحكم متعلق بوصف الجنس لا بسن الرجولة والبلوغ، وجعل نصيبه معيارًا مضاعفًا يختصر صور القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص666–667، تحت «وجه التعبير بـ﴿الذكر﴾ و﴿الأنثى﴾ دون ﴿الرجال﴾ و﴿النساء﴾».","url":""}]},{"id":"s4-38","number":38,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فَوْقَ اثْنَتَيْنِ﴾، دون أن يقال: اثنتين فما فوق؟","answer":"جاء ﴿فوق اثنتين﴾ نصًا في حكم الثلاث فأكثر، أما البنتان فأُلحق حكمهما بالثلثين من أدلة أخرى، منها حكم الأختين وما ثبت بالسنة؛ ففصل النص بين ما صرح به هنا وما يستفاد من البيان الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص668","url":""}]},{"id":"s4-39","number":39,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"لماذا ذكر فرض البنت الواحدة صراحة، ولم يذكر فرض الابن الواحد؟","answer":"صُرح بفرض البنت الواحدة لأن العرب كانوا يؤثرون البنين ويحرمون البنات من الميراث، فاحتاج حقها إلى بيان مستقل مؤكد يهدم ذلك العرف؛ أما حق الابن فكان معروفًا غير منكور عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص670، تحت «سر ذكر فرض البنت المنفردة دون الابن».","url":""}]},{"id":"s4-40","number":40,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"لماذا توسط قوله: ﴿آبَاؤُكُمْ وَأَبْنَاؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا﴾ تفاصيل الأنصبة؟","answer":"توسطت الجملة اعتراضًا يقطع تقدير الأنصبة بالهوى؛ فالإنسان لا يعلم أي آبائه وأبنائه أقرب نفعًا في الحقيقة. لذلك رد الله القسمة إلى علمه وحكمته، وطيب النفوس للرضا بالفرائض والتسليم لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص671–672، تحت «نكتة الإطناب بالجملة الاعتراضية».","url":""}]},{"id":"s4-41","number":41,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"لماذا ختمت أحكام المواريث هنا بـ﴿إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا﴾؟","answer":"الخاتمة تثبت إحاطة العلم بالمصالح ووضع الأمر بالجهاد والنهي عن الوهن موضع الحكمة؛ جواب قسمة المواريث أجنبي عن الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص673–674، تحت «التذييل وتشابه الأطراف في فاصلة الآية الكريمة».","url":""}]},{"id":"s4-42","number":42,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا عبر عن الزوجات بلفظ ﴿أَزْوَاجُكُمْ﴾، ولم يقل: زوجاتكم؟","answer":"لفظ «الزوج» يستحضر رابطة الزوجية وما يقتضيه عقدها؛ فناسب الكلام على الميراث الناشئ عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص690–691، تحت «الزوج والمرأة».","url":""}]},{"id":"s4-43","number":43,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَرَكَ أَزْوَاجُكُمْ﴾، فاستعمل «ما» وأجمل أنواع التركة؟","answer":"استعمل ﴿ما﴾ وأجمل التركة ليعم الحكم كل ما يتركه الميت من مال وعقار ومنقول وحقوق ومنافع مما يدخل في الإرث، فلا يقيده بنوع مخصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص682، تحت «نكتة إيجاز الحذف في قوله: ﴿ولكم نصف ما ترك أزواجكم﴾».","url":""}]},{"id":"s4-44","number":44,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا قُيّد تنفيذ الوصية والدَّين بقوله تعالى: ﴿غير مضار﴾؟","answer":"احتراسٌ يمنع اتخاذ الوصية أو الإقرار بالدَّين وسيلةً للإضرار بالورثة وانتقاص حقوقهم؛ كأن يُقرّ المورِّث بدَين لا حقيقة له ليحرمهم بعض المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص687، تحت «بلاغة الإطناب بالاحتراس في قوله: ﴿غير مضار﴾».","url":""}]},{"id":"s4-45","number":45,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا أعيد اسم الله في ﴿والله عليم حليم﴾ بعد ﴿وصية من الله﴾، ولم يقل: وهو عليم حليم؟","answer":"لزيادة التعظيم وإثارة المهابة في النفوس؛ فالتصريح باسم الله يستحضر صفات الجلال والكمال، ويكون أشد وقعًا من الضمير العائد إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص688، تحت «بلاغة الإظهار في موضع الإضمار في قوله تعالى: ﴿والله عليم حليم﴾».","url":""}]},{"id":"s4-46","number":46,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا ختمت آية المواريث الأولى بـ﴿عَلِيمًا حَكِيمًا﴾، وختمت الثانية بـ﴿عَلِيمٌ حَلِيمٌ﴾؟","answer":"ختمت الأولى بـ﴿عليمًا حكيمًا﴾ لأنها أصل تفصيل الأنصبة، فناسبها العلم بالمصالح والحكمة في التقدير. وختمت الثانية بـ﴿عليم حليم﴾ بعد التحذير من المضارة؛ فهو يعلم المتحايل ويمهله حلمًا ولا يهمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص688–689، تحت «بلاغة التذييل وتشابه الأطراف في الآية الكريمة»؛ ولخاتمة الآية الأولى: ج6، ص673–674.","url":""}]},{"id":"s4-47","number":47,"surah":4,"verses":[13,14],"references":[{"surah":4,"verses":[13,14]}],"verseLabel":"النساء: 13–14","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ حُدُودُ اللَّهِ﴾ بعد أحكام المواريث؟","answer":"شُبهت الأحكام بحدود تفصل الحق من الباطل، فلا يجوز تجاوزها؛ وفي الإضافة إلى الله تعظيم لحرمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص696–697، تحت «دلالة الاستعارة التصريحية في قوله: ﴿تلك حدود الله﴾».","url":""}]},{"id":"s4-48","number":48,"surah":4,"verses":[13,14],"references":[{"surah":4,"verses":[13,14]}],"verseLabel":"النساء: 13–14","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الطائعين: ﴿خَالِدِينَ فِيهَا﴾ بالجمع، وقوله تعالى في العاصي: ﴿خَالِدًا فِيهَا﴾ بالإفراد؟","answer":"الجمع في أهل الجنة يناسب الأنس بالاجتماع والصحبة، فيزيد الترغيب، والإفراد في العاصي يصور الوحشة والانفراد بالعذاب، فيزيد التهديد؛ ولا يفيد انحصار العصاة في واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص702–703، تحت «نكتة التغاير بين ﴿خالدين﴾ جمعًا و﴿خالدًا﴾ مفردًا».","url":""}]},{"id":"s4-49","number":49,"surah":4,"verses":[13,14],"references":[{"surah":4,"verses":[13,14]}],"verseLabel":"النساء: 13–14","question":"ما سرّ التعبير في قوله تعالى عن الجنة: ﴿وَذَلِكَ الْفَوْزُ الْعَظِيمُ﴾، وقال عن النار: ﴿وَلَهُ عَذَابٌ مُهِينٌ﴾؟","answer":"سمي دخول الجنة فوزًا عظيمًا لأنه يجمع النجاة والنعيم والخلود والكرامة، أما متجاوز حدود الله فناسبه عذاب مهين؛ إذ قابل استكباره على الحكم بإذلاله مع الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص701–703، تحت «دلالة المقابلة بين الطائعين والعاصين».","url":""}]},{"id":"s4-50","number":50,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"لماذا أسند التوفي إلى الموت في قوله: ﴿حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ﴾؟","answer":"أُسند التوفي إلى الموت على طريق المجاز العقلي؛ لأنه السبب الظاهر الذي تنتهي به الحياة وتستوفى المدة، أما المتوفي حقيقة فالله، وتقبض الملائكة الروح بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص715، تحت «دلالة المجاز في قوله: ﴿يتوفاهن الموت﴾».","url":""}]},{"id":"s4-51","number":51,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلًا﴾، فنكر «سبيلًا» ولم يبينه؟","answer":"أُبهم السبيل وترك تعيينه لما يشرعه الله بعد ذلك، وفي هذا الإبهام تخويف وترهيب. وليس في التنكير ما يقتضي أن يكون الحكم اللاحق أخف أو أن يكون فرجًا موعودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص716، تحت «دلالة الاستعارة في قوله تعالى: ﴿أو يجعل الله لهن سبيلًا﴾».","url":""}]},{"id":"s4-52","number":52,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"لماذا جمع بين التوبة والإصلاح: ﴿فَإِنْ تَابَا وَأَصْلَحَا فَأَعْرِضُوا عَنْهُمَا﴾؟","answer":"التوبة رجوع باطني وترك للذنب، والإصلاح تصحيح عملي لما أفسداه وتقويم للسلوك؛ فلا يكفي الادعاء حتى يظهر أثره. وحذف متعلق ﴿أصلحا﴾ ليعم إصلاح النفس والعمل وما ترتب على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص719، تحت «سر حذف المتعلق من ﴿فإن تابا وأصلحا﴾».","url":""}]},{"id":"s4-53","number":53,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"ما دلالة صيغتي ﴿توابًا رحيمًا﴾ في ختام الأمر بالإعراض عمن تاب وأصلح؟","answer":"تدلان على سعة توبة الله ورحمته وشمولهما للتائبين، وعلى كثرة قبوله لتوبة عباده؛ وفي ذلك ترغيب للعاصي في التوبة وحث على المبادرة إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص721، تحت عنوان «دلالة صيغة المبالغة في اسمي الله تعالى الواردين في قوله: ﴿توابًا رحيمًا﴾»","url":""}]},{"id":"s4-473","number":473,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"لماذا قُدّم ﴿توابًا﴾ على ﴿رحيمًا﴾ في قوله تعالى: ﴿إن الله كان توابًا رحيمًا﴾؟","answer":"في الترتيب بشارة بأن الرحمة تتبع قبول التوبة؛ فمن تاب الله عليه رحمه، وهو انتقال من إزالة أثر الذنب إلى الإنعام على التائب، مع أن أصل قبول التوبة نفسه من رحمته سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص721، تحت عنوان «نكتة تقديم اسم الله تعالى (التواب) على اسمه تعالى (الرحيم) في قوله: ﴿إن الله كان توابًا رحيمًا﴾»","url":""}]},{"id":"s4-54","number":54,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"ما دلالة تعدية التوبة بـ﴿عَلَى﴾ في قوله تعالى: ﴿إِنَّمَا التَّوْبَةُ عَلَى اللَّهِ﴾؟","answer":"﴿على﴾ ليست إلزامًا من غيره، بل وعد أوجبه الله على نفسه تفضلًا وفق حكمته؛ فهي تفيد تحقق القبول لمن استوفى وصف التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص726، تحت «دلالة ﴿على﴾ في قول الله تعالى: ﴿إنما التوبة على الله﴾».","url":""}]},{"id":"s4-55","number":55,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"لماذا وصف أصحاب الذنب بأنهم ﴿يَعْمَلُونَ السُّوءَ بِجَهَالَةٍ﴾؛ أكل ذنب يقع بجهالة؟","answer":"كل معصية جهالة من جهة إيثار اللذة العاجلة على علم العاقبة، ولو عرف صاحبها الحكم؛ فالجهالة هنا سفه العمل لا انعدام المعلومة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص726–727، تحت «نكتة التقييد بالحال ﴿بجهالة﴾ في قوله تعالى: ﴿إنما التوبة على الله للذين يعملون السوء بجهالة﴾».","url":""}]},{"id":"s4-56","number":56,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ يَتُوبُونَ مِنْ قَرِيبٍ﴾، دون أن يقال: سريعًا؟","answer":"أي قبل حضور الموت، والزمن كله قريب أمام الآخرة؛ واللفظ يحث على المبادرة من غير حصرها في مدة حسابية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص728، تحت «دلالة التعبير بالقرب في قوله تعالى: ﴿ثم يتوبون من قريب﴾».","url":""}]},{"id":"s4-57","number":57,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"لماذا قابل بين من يتوب ﴿مِنْ قَرِيبٍ﴾ ومن ينتظر حتى ﴿حَضَرَ أَحَدَهُمُ الْمَوْتُ﴾؟","answer":"أبرزت المقابلة الفرق بين توبة تصدر عن اختيار قبل المعاينة، فتدل على رجوع صادق، وبين اعتراف اضطراري عند حضور الموت وانكشاف المصير، حين ينقطع زمن التكليف والعمل فلا تكون التوبة المقبولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص735، تحت «سر الاختلاف بين قوله: ﴿ثم يتوبون﴾ وقوله: ﴿قال إني تبت الآن﴾».","url":""}]},{"id":"s4-58","number":58,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا﴾، فصور معاملة النساء على هيئة ميراث؟","answer":"صور الفعل ميراثًا لأنه كان عادة جاهلية حقيقية: يعد ولي الميت زوجته جزءًا من تركته، فيحبسها أو يتزوجها أو يزوجها بغير رضاها. فكشف التعبير بشاعة معاملتها كمال موروث ونفى حل ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص746، تحت «بلاغة قوله تعالى: ﴿ترثوا النساء﴾ بين التشبيه والإيجاز».","url":""}]},{"id":"s4-59","number":59,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"لماذا عُلّق الشرط بـ«إن» في قوله تعالى: ﴿فإن كرهتموهن﴾، ولم يقل: إذا كرهتموهن؟","answer":"عُلّق الشرط بـ«إن» دون «إذا» لأن الكراهة غير متيقنة، فلا تفترض في كل زوجة؛ وفي ذلك حث على التجمل والصبر قبل ترتيب أثر الكراهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص751، تحت «دلالة تعليق الشرط بـ(إن) في قوله تعالى: ﴿فإن كرهتموهن﴾».","url":""}]},{"id":"s4-60","number":60,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"لماذا انتقل من كراهية النساء إلى التعبير العام: ﴿فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا﴾؟","answer":"عمم فقال ﴿شيئًا﴾ ليجعل التوجيه قاعدة تتجاوز كراهية الزوجة: قد يكره الإنسان أمرًا وتخفى عنه عاقبته التي يجعل الله فيها خيرًا كثيرًا. وفي السياق يحجز ذلك عن العجلة في المضارة أو الفراق ويدعو إلى حسن العشرة والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص752–753، تحت «دلالة تنكير ﴿شيئًا﴾ ونكتة إقامة الظاهر موقع المضمر في قوله تعالى: ﴿فإن كرهتموهن فعسى أن تكرهوا شيئًا ويجعل الله فيه خيرًا كثيرًا﴾».","url":""}]},{"id":"s4-61","number":61,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"لماذا نُكّر الخير ووُصف بالكثرة في قوله تعالى: ﴿ويجعل الله فيه خيرًا كثيرًا﴾؟","answer":"في التنكير تعظيم للخير وتفخيم لشأنه، ووصفه بالكثرة يزيد الترغيب في الصبر وترك المفارقة؛ فقد يكون فيما يكرهه الإنسان خير عظيم كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص754، تحت عنوان «نكتة التنكير في قوله تعالى: ﴿خيرًا كثيرًا﴾»","url":""}]},{"id":"s4-62","number":62,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا مثل لأعلى المهر بقوله: ﴿آتَيْتُمْ إِحْدَاهُنَّ قِنْطَارًا﴾؟","answer":"ذكر القنطار للمبالغة في كثرة المهر، ليقرر أن حق المرأة لا يجوز استرداده ولو بلغ أقصى ما يتصوره المخاطب من المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص761–762، تحت «بلاغة الكناية في قوله تعالى: ﴿وآتيتم إحداهن قنطارًا﴾».","url":""}]},{"id":"s4-63","number":63,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا جاء الاستفهام المنكر: ﴿أَتَأْخُذُونَهُ بُهْتَانًا وَإِثْمًا مُبِينًا﴾؟","answer":"الاستفهام إنكار وتعجيب يواجه الزوج بقبح الاسترداد بعد الإفضاء والميثاق، ويسميه بهتانًا وإثمًا ظاهرًا ليقطع كل تسويغ له.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص763، تحت «دلالة الاستفهام في قوله تعالى: ﴿أتأخذونه بهتانًا وإثمًا مبينًا﴾».","url":""}]},{"id":"s4-64","number":64,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا وصف الزواج بقوله: ﴿وَأَخَذْنَ مِنْكُمْ مِيثَاقًا غَلِيظًا﴾؛ وكيف تأخذ النساء الميثاق؟","answer":"الميثاق عهد الزواج المؤكد الذي تترتب عليه الحقوق والحرمة. وأُسند أخذه إلى النساء مجازًا؛ لأنهن أصحاب الحق فيه، فكأنهن أخذن العهد الذي أخذه الله على الأزواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص772–773، تحت «بلاغة المجاز العقلي في قوله تعالى: ﴿وأخذن منكم ميثاقًا غليظًا﴾».","url":""}]},{"id":"s4-65","number":65,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا زادت هذه الآية ﴿وَمَقْتًا﴾ في قوله: ﴿إِنَّهُ كَانَ فَاحِشَةً وَمَقْتًا وَسَاءَ سَبِيلًا﴾؟","answer":"أضيف ﴿مقتًا﴾ ليدل على شدة البغض فوق كونه فاحشة، ولأن العرب سموا نكاح امرأة الأب نكاح المقت؛ فجمع قبح الفعل وبغضه وسوء طريقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص781، تحت «بلاغة التذييل في قوله تعالى: ﴿إنه كان فاحشة ومقتًا وساء سبيلًا﴾».","url":""}]},{"id":"s4-66","number":66,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا وصف الفعل بثلاثة أوصاف متتابعة: ﴿فَاحِشَةً وَمَقْتًا وَسَاءَ سَبِيلًا﴾؟","answer":"﴿فاحشة﴾ لقبحه المتجاوز، و﴿مقتًا﴾ لشدة بغضه، و﴿ساء سبيلًا﴾ لفساد الطريق المؤدي إليه وآثاره؛ فاستوعبت الأوصاف ذات الفعل وموقف النفوس ومسلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص781، تحت «بلاغة التذييل في قوله تعالى: ﴿إنه كان فاحشة ومقتًا وساء سبيلًا﴾».","url":""}]},{"id":"s4-67","number":67,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ﴾، فزاد قيد ﴿مِنْ أَصْلَابِكُمْ﴾؟","answer":"القيد يخرج أدعياء التبني الذين كانت العرب تسميهم أبناء وتجري عليهم حكم أبناء النسب؛ فبيّن أن المراد هنا الأبناء الذين من الأصلاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص796–797، تحت «دلالة الوصف ﴿الذين من أصلابكم﴾ في قوله تعالى: ﴿وحلائل أبنائكم الذين من أصلابكم﴾».","url":""}]},{"id":"s4-68","number":68,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا ختم تعداد المحرمات بقوله: ﴿إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا﴾؟","answer":"الخاتمة تقرر المغفرة لما وقع قبل نزول التحريم، فتناسب قوله: ﴿إلا ما قد سلف﴾؛ والغفران تجاوز عما مضى، والرحمة بيان لسبب هذا التجاوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص798، تحت «مناسبة ختم الآية باسمي الله تعالى: الغفور والرحيم».","url":""}]},{"id":"s4-69","number":69,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا اسْتَمْتَعْتُمْ بِهِ مِنْهُنَّ﴾ بـ«ما»، دون أن يقال: فمن استمتعتم بها؟","answer":"جيء بـ«ما» الموصولة بدل «من» مع إرادة النساء؛ للتفخيم من أمر الاستمتاع والتنبيه إلى خطره وما يترتب عليه من حقوق وواجبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص22، تحت «نكتة التعبير بـ(ما) دون (من) في قوله تعالى: ﴿فما استمتعتم به منهن﴾».","url":""}]},{"id":"s4-70","number":70,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا سمى المهور هنا ﴿أُجُورَهُنَّ﴾، بينما سماها قبل ذلك ﴿صَدُقَاتِهِنَّ﴾؟","answer":"﴿صدقاتهن﴾ تبرز صدق الرغبة والعطية عند إنشاء الزواج، و﴿أجورهن﴾ تبرز المهر حقًا واجب الأداء في مقابل عقد الاستمتاع المشروع، لا ثمنًا للمرأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص24، تحت «بلاغة الاستعارة في قوله تعالى: ﴿فآتوهن أجورهن فريضة﴾»؛ وللمقارنة بصدقاتهن: ج6، ص605.","url":""}]},{"id":"s4-71","number":71,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ لَمْ يَسْتَطِعْ مِنْكُمْ طَوْلًا﴾، دون أن يقال: قدرة أو مالًا؟","answer":"الطول سعة وفضل وقدرة ممتدة، فيشمل المال ومؤن النكاح والقدرة عليه، وهو أوسع من مجرد لفظ المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص33، تحت «دلالة التعبير بلفظ الطول بدل السعة».","url":""}]},{"id":"s4-72","number":72,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ فَتَيَاتِكُمُ الْمُؤْمِنَاتِ﴾، واختار «فتياتكم»؟","answer":"الفتاة لفظ ملاطفة يرد للأَمَة كرامتها الإنسانية، وإضافتهن إلى جماعة المؤمنين توثّق أخوة الدين وتمنع الازدراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص36–37، تحت «سر التعبير بالفتيات بدل الجواري والإماء».","url":""}]},{"id":"s4-73","number":73,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا جمع بين الأوصاف: ﴿مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ وَلَا مُتَّخِذَاتِ أَخْدَانٍ﴾؟","answer":"الإحصان يثبت العفة إيجابًا، ونفي السفاح ينفي العلاقة المعلنة، ونفي الأخدان ينفي العلاقة السرية؛ فاستوعب الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص42–44، تحت «نكتة تقديم ذكر المسافحات على متخذات الأخدان».","url":""}]},{"id":"s4-74","number":74,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا جاء الشرط بـ﴿إذا﴾ في ﴿فإذا أُحصنَّ﴾، وبـ﴿إن﴾ في ﴿فإن أتين بفاحشة﴾؟","answer":"جاءت «إذا» مع الإحصان لتأكيد وقوعه، ثم جاءت «إن» لتقليل احتمال الفاحشة ممن أُحصنت؛ فاختلاف الأداة يُبرز أن الإحصان هو المتوقع، والفاحشة خلاف ما يُنتظر معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص45، تحت «نكتة التغاير بين أداتي الشرط (إذا) و(إن) من قوله: ﴿فإذا أحصن فإن أتين﴾».","url":""}]},{"id":"s4-75","number":75,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا وصف المشقة الجنسية بـ﴿الْعَنَتَ﴾ في قوله: ﴿لِمَنْ خَشِيَ الْعَنَتَ مِنْكُمْ﴾؟","answer":"العنت هو المشقة والضرر والهلاك؛ فصور الخوف من الوقوع في الزنا وما يجره من إثم وعقوبة وفساد، لا مجرد ضيق الرغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص46، تحت «نكتة التعبير بالعنت بدل الوقوع في الزنى في قوله تعالى: ﴿ذلك لمن خشي العنت منكم﴾».","url":""}]},{"id":"s4-76","number":76,"surah":4,"verses":[25],"references":[{"surah":4,"verses":[25]},{"surah":5,"verses":[5]}],"verseLabel":"النساء: 25؛ المائدة: 5","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء عن الإماء: ﴿مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ﴾ بصيغة المؤنث، وقوله تعالى في المائدة: ﴿مُحْصِنِينَ غَيْرَ مُسَافِحِينَ﴾ بصيغة المذكر؟","answer":"في النساء الحكم منصب على الإماء اللاتي ينكحن عند العجز، فوصفت حالهن مباشرة بالعفة؛ وفي المائدة الخطاب للرجال الذين أُحلت لهم المحصنات، فحمّلهم هم أيضًا شرط الإحصان ونفي السفاح، فاختلاف الصيغة تابع لجهة التكليف.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص137؛ إسلام ويب، باب النساء: 25","url":""}]},{"id":"s4-77","number":77,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا جاء قوله تعالى: ﴿يريد الله أن يخفف عنكم﴾ في جملة مستقلة؟","answer":"استؤنفت الجملة لتقرر حكمًا عامًا دائمًا يشمل ما خففه الله عن عباده، وتبين عنايته بهم وتفضله عليهم؛ فالتخفيف قاعدة تتجاوز الحكم الجزئي السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص65، تحت عنوان «دلالة الاستئناف والفصل في: ﴿يريد الله أن يخفف عنكم وخلق الإنسان ضعيفًا﴾»","url":""}]},{"id":"s4-78","number":78,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا قابل بين إرادة الله التوبة وإرادة متبعي الشهوات: ﴿أَنْ تَمِيلُوا مَيْلًا عَظِيمًا﴾؟","answer":"إرادة الله ترد العباد إلى الاستقامة بالتوبة، وإرادة أهل الشهوات تصرفهم عنها ميلًا عظيمًا؛ فالمقابلة تكشف تضاد طريق الإصلاح وطريق الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص63، تحت «بلاغة العدول عن الجملة الاسمية إلى الجملة الفعلية».","url":""}]},{"id":"s4-79","number":79,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما الصلة بين قوله: ﴿يُرِيدُ اللَّهُ أَنْ يُخَفِّفَ عَنْكُمْ﴾ وبين ﴿وَخُلِقَ الْإِنْسَانُ ضَعِيفًا﴾؟","answer":"ضعف الإنسان عن مقاومة الشهوة وتحمل المشقة هو علة التخفيف، فجاء التشريع ملائمًا للفطرة ومغلقًا أبواب الحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص65–66، تحت «حسن التذييل في قوله: ﴿وخلق الإنسان ضعيفًا﴾».","url":""}]},{"id":"s4-80","number":80,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ﴾، فسمى مال الآخرين أموالكم؟","answer":"أموال المؤمنين كأنها مال الجماعة لاتصال المصالح، وفي الإضافة تذكير بأن أكل مال غيرك اعتداء على البنية المالية التي أنت منها، كما تحب صيانة مالك.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص75–76، تحت «بلاغة قوله ﴿لا تأكلوا أموالكم بينكم﴾ و﴿ولا تقتلوا أنفسكم﴾ بين الحقيقة والاستعارة والمجاز المرسل».","url":""}]},{"id":"s4-81","number":81,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما دلالة الاستدراك بقوله تعالى: ﴿إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ﴾ بعد النهي عن أكل الأموال بالباطل؟","answer":"الاستثناء منقطع في المعنى: ليست التجارة عن تراض من أكل المال بالباطل، بل هي الطريق المشروع المقابل له. وخصت بالذكر لأنها أبرز صور انتقال الأموال بين الناس بالاختيار والمعاوضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص73–74، تحت «دلالة الاستثناء المنقطع في قوله: ﴿إلا أن تكون تجارة عن تراض منكم﴾».","url":""}]},{"id":"s4-82","number":82,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَقْتُلُوا أَنْفُسَكُمْ﴾، دون أن يقال: لا يقتل بعضكم بعضًا؟","answer":"جعل قتل الآخر قتلًا للنفس لأن المؤمنين كالجسد الواحد، ولأن النهي يشمل قتل الإنسان نفسه وتعريضها للهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص75–76، تحت «بلاغة قوله ﴿لا تأكلوا أموالكم بينكم﴾ و﴿ولا تقتلوا أنفسكم﴾ بين الحقيقة والاستعارة والمجاز المرسل».","url":""}]},{"id":"s4-83","number":83,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا جمع بين ﴿عُدْوَانًا وَظُلْمًا﴾؟","answer":"العدوان تجاوز الحق بإفراط، والظلم إتيان ما لا يستحق؛ والجمع للتغاير والتأكيد والتنبيه إلى جر الصغير إلى الأعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص78–79، تحت «مناسبة الجمع بين العدوان والظلم في قوله: ﴿عدوانًا وظلمًا﴾».","url":""}]},{"id":"s4-84","number":84,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا صرح باسم الله في قوله: ﴿وَكَانَ ذَلِكَ عَلَى اللَّهِ يَسِيرًا﴾، ولم يقل: عليه يسيرًا؟","answer":"أُظهر الاسم الجليل لتربية المهابة وتأكيد أن الإصلاء بالنار، مع شدته، يسير على قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص80، تحت «نكتة العدول إلى الاسم الظاهر في قوله: ﴿وكان ذلك على الله يسيرًا﴾».","url":""}]},{"id":"s4-85","number":85,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ﴾ بالبناء للمجهول، دون أن يقال: ما نهاكم الله عنه؟","answer":"بُني ﴿كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ﴾ للمفعول لأن المقام معقود بالفعل ووقوعه لا بتعيين فاعله، أو لأن الفاعل معلوم من السياق؛ فبرز الأثر المقصود من غير تشتيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص82، تحت «نكتة التعبير بصيغة المبني للمفعول في قوله ﴿تنهون﴾».","url":""}]},{"id":"s4-86","number":86,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما المراد بالسيئات في قوله تعالى: ﴿نكفر عنكم سيئاتكم﴾ بعد اشتراط اجتناب الكبائر؟","answer":"المراد بالسيئات هنا الصغائر في مقابل الكبائر التي أُمر باجتنابها. ويبين المصدر أن اجتناب الكبائر يشمل أداء الواجبات أيضًا، لأن ترك الواجب قد يكون من الكبائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص81–82، تحت عنوان «براعة الكلام بين الحذف والذكر في قوله: ﴿إن تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم﴾»","url":""}]},{"id":"s4-87","number":87,"surah":4,"verses":[26],"references":[{"surah":4,"verses":[26]}],"verseLabel":"النساء: 26","question":"لماذا رُتبت المقاصد هكذا: ﴿لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ… وَيَتُوبَ عَلَيْكُمْ﴾؛ فقدم البيان ثم الهداية ثم التوبة؟","answer":"بدأ بالبيان لأنه يكشف الأحكام، ثم بالهداية إلى سنن الصالحين للعمل بها، ثم بالتوبة لإزالة أثر التقصير؛ فترتيبها ينتقل من معرفة الطريق إلى سلوكه ثم معالجة الزلل.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031","url":""}]},{"id":"s4-88","number":88,"surah":4,"verses":[26,27],"references":[{"surah":4,"verses":[26,27]}],"verseLabel":"النساء: 26–27","question":"لماذا عُدِّي فعل الإرادة باللام: ﴿يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ﴾، ثم عُدِّي بـ«أن»: ﴿يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ﴾؟","answer":"في ﴿يريد الله ليبين لكم﴾ تحتمل اللام أن تكون زائدة للتوكيد، أو لام تعليل لمفعول محذوف، نحو: يريد الله تشريع ذلك ليبين ويهدي؛ فازدادت العبارة توكيدًا لمقاصد متعددة. أما ﴿يريد أن يتوب عليكم﴾ فالتوبة هي المراد المباشر، فنصب الفعل بـ﴿أن﴾.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031","url":"https://quranpedia.net/note/48031"}]},{"id":"s4-89","number":89,"surah":4,"verses":[27],"references":[{"surah":4,"verses":[27]}],"verseLabel":"النساء: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ﴾ فقدم اسم الله، بينما قال قبلها وبعدها: ﴿يُرِيدُ اللَّهُ﴾؟","answer":"قُدم اسم الله في ﴿والله يريد أن يتوب عليكم﴾ لمقابلة إرادته الرحيمة بإرادة متبعي الشهوات في الجملة التالية؛ أما الموضعان الآخران فالمقصود تعداد ما يريده الله من بيان وتخفيف، فجرى الفعل أولًا.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031","url":"https://quranpedia.net/note/48031"}]},{"id":"s4-90","number":90,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما دلالة عموم الخطاب في قوله تعالى: ﴿وَلَا تَتَمَنَّوْا مَا فَضَّلَ اللَّهُ بِهِ بَعْضَكُمْ عَلَى بَعْضٍ﴾ دون تخصيص الرجال أو النساء؟","answer":"جاء ﴿بَعْضَكُمْ عَلَى بَعْضٍ﴾ عامًا ليشمل كل صور التفاوت التي قد تثير التمني والحسد بين الرجال والنساء وبين أفراد الجنس الواحد؛ فالعلاج موجه إلى النفس الإنسانية كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص88–89، تحت «براعة الإيجاز في قوله: ﴿ما فضل الله به بعضكم على بعض﴾».","url":""}]},{"id":"s4-91","number":91,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلرِّجَالِ نَصِيبٌ مِمَّا اكْتَسَبُوا وَلِلنِّسَاءِ نَصِيبٌ مِمَّا اكْتَسَبْنَ﴾، فكرر «نصيب»؟","answer":"تكرار ﴿نَصِيبٌ﴾ يجعل لكل من الرجال والنساء حصة مستقلة مما اكتسب، فلا يذوب حكم أحدهما في الآخر؛ كما يوازن بينهما في ارتباط الجزاء بالسعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص90، تحت «بديع المقابلة في قوله ﴿للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن﴾».","url":""}]},{"id":"s4-92","number":92,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ﴾، وحذف ما يُسأل؟","answer":"حُذف المتعلق في ﴿وَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ﴾ لأن السياق يدل عليه، ولأن تركه يفتح المعنى على كل ما يناسب المقام؛ فالحذف إيجاز وتعميم لا نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص91، تحت «نكتة حذف المفعول في قوله: ﴿واسألوا الله من فضله﴾».","url":""}]},{"id":"s4-93","number":93,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِكُلٍّ جَعَلْنَا مَوَالِيَ﴾، دون أن يقال: ورثة؟","answer":"الموالي هم من تربطهم بالميت ولاية قرابة أو ولاء فيلون أمر ميراثه ويستحقونه؛ فاللفظ أوسع دلالة من لفظ ﴿ورثة﴾ من جهة رابطة القرب والولاية التي نشأ عنها الإرث.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص96، تحت «التنبيه على علاقتهم بالموروث، والتعليل لاستحقاقهم الإرث».","url":""}]},{"id":"s4-94","number":94,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ﴾، دون أن يقال: الذكور؟","answer":"لأن وصف الرجولة يستحضر معاني الشهامة والمروءة والحزم والنخوة، وهي صفات تناسب القيام بالرعاية والحماية؛ فاختيار «الرجال» يلفت إلى مقتضيات هذه المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص105، تحت «نكتة التعبير بـ﴿الرجال﴾».","url":""}]},{"id":"s4-95","number":95,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا اختيرت صيغة المبالغة ﴿قَوَّامُونَ﴾، ولم يقل: قائمون؟","answer":"صيغة «قوامون» تفيد كثرة القيام بشؤون النساء والاعتناء بحفظهن وأداء حقوقهن، وتدل على دوام هذه المسؤولية وتنوع أعمالها؛ فناسبت المقام أكثر من مجرد «قائمون».","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص106، تحت «دلالة التعبير بصيغة المبالغة ﴿قوامون﴾».","url":""}]},{"id":"s4-96","number":96,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ﴾، دون أن يقال صراحة: الرجال على النساء؟","answer":"عدل إلى «بعضهم على بعض» لتجنب إيهام تفضيل كل رجل على كل امرأة، ولإبقاء التفضيل موزعًا داخل الجماعة بحسب ما أقيمت عليه القوامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص107–108، تحت «مناسبة قوله: ﴿بعضهم على بعض﴾».","url":""}]},{"id":"s4-97","number":97,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا رتب علاج النشوز هكذا: الوعظ، ثم الهجر في المضاجع، ثم الضرب؟","answer":"يفيد السياق التدرج من الأخف إلى الأشد، والاقتصار على الأخف متى حصل به المقصود؛ فإذا زال النشوز لم يجز تجاوز ذلك إلى ما بعده. فالترتيب مرتبط بتحقيق الإصلاح لا بإيقاع جميع الإجراءات.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص114–115، تحت «مناسبة الجمع بين المعطوفات في قوله: ﴿فعظوهن واهجروهن في المضاجع واضربوهن﴾».","url":""}]},{"id":"s4-98","number":98,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا ختمت آية القوامة بـ﴿إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا﴾؟","answer":"الخاتمة تهديد لمن يبغي بعد الطاعة؛ فإن علت يد الزوج فالله أعلى منه وأكبر، فيكف ذلك عن التسلط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص118–119، تحت «حسن التذييل في قوله: ﴿إن الله كان عليًا كبيرًا﴾».","url":""}]},{"id":"s4-99","number":99,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا عبر عن النزاع الزوجي بقوله: ﴿شِقَاقَ بَيْنِهِمَا﴾؟","answer":"الشقاق يصور كل واحد في شق غير شق الآخر، فهو انشقاق وتباعد بعد ائتلاف حسي أو معنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص126، تحت «مجاز التعبير في قوله: ﴿وإن خفتم شقاق بينهما﴾».","url":""}]},{"id":"s4-100","number":100,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"إلى من يعود الضمير في قوله: ﴿إِنْ يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا﴾، ولماذا جاء محتملًا؟","answer":"يحتمل أن يعود إلى الحكمين، أي إن قصدا الإصلاح وفق الله مسعاهما، وأن يعود إلى الزوجين، أي إن صدقت إرادتهما أصلح الله بينهما؛ والاحتمال يجمع مسؤولية الوساطة وإرادة الزوجين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص129–130، تحت عنوان «براعة التعبير بالضمير؛ لتكثير المعنى في قوله: ﴿إن يريدا إصلاحًا يوفق الله بينهما﴾»","url":""}]},{"id":"s4-101","number":101,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا أعيدت الباء في قوله تعالى: ﴿وبذي القربى﴾ في آية الحقوق، خلاف نظيرها في البقرة؟","answer":"أعيدت الباء مع ذي القربى لتأكيد الإحسان إليهم والاعتناء بحقهم، كأنه يستأنف الأمر به. وفي إعادة الباء في النساء، خلاف نظير البقرة، توكيد ومبالغة في صلة القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص140، تحت «دلالة إعادة حرف الجر في قوله: ﴿وبذي القربى﴾».","url":""}]},{"id":"s4-102","number":102,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا فرق بين ﴿الْجَارِ ذِي الْقُرْبَى﴾ و﴿الْجَارِ الْجُنُبِ﴾؟","answer":"الجار ذو القربى من اجتمع له حق الجوار والقرب نسبًا أو دارًا، والجار الجنب هو البعيد أو غير القريب؛ فشملت الوصية درجتي الجوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص141، تحت «دلالة المغايرة في التعبير بين قوله: ﴿والجار ذي القربى﴾ وقوله: ﴿والجار الجنب﴾».","url":""}]},{"id":"s4-103","number":103,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"من هو ﴿الصَّاحِبِ بِالْجَنْبِ﴾، ولماذا جاء بهذا التعبير الواسع؟","answer":"هو من لازم الإنسان إلى جنبه في سفر أو دراسة أو عمل أو مجلس ونحوها، فجاء الوصف واسعًا ليشمل صور الصحبة العارضة والدائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص141، تحت «دلالة الباء في قوله: ﴿والصاحب بالجنب﴾».","url":""}]},{"id":"s4-104","number":104,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا جمع بين ﴿مُخْتَالًا فَخُورًا﴾ من غير حرف عطف بينهما؟","answer":"ترك العطف لقرب الوصفين في المعنى والأثر، ولأن الاختيال الباطن والظاهر سبب للفخر بالقول والفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص142–143، تحت «حسن التذييل في قوله تعالى: ﴿إن الله لا يحب من كان مختالًا فخورًا﴾».","url":""}]},{"id":"s4-105","number":105,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا جمع في وصف البخلاء بين: يبخلون، ويأمرون الناس بالبخل، ويكتمون ما آتاهم الله؟","answer":"ذكرت الآية ثلاث جهات: بخلهم في أنفسهم، وأمرهم غيرهم بالبخل، وكتمان ما آتاهم الله من فضله. فالعطف يجمع صفات مستقلة من البخل، ويبين انتقاله من عمل صاحبه إلى إفساد غيره وإخفاء النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص150، تحت «توجيه عطف جمل وجوه البخل».","url":""}]},{"id":"s4-106","number":106,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما مناسبة وصف العذاب بـ﴿مهينًا﴾ بعد ذكر البخل وكتمان فضل الله؟","answer":"الإهانة هنا جزاء من جنس العمل؛ فمن أهان نعمة الله بالبخل بها وإخفائها، استحق عذابًا يهينه. فالوصف يصل العقوبة بصورة الجحود المذكورة في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص151، تحت «علة وضع الظاهر موضع المضمر».","url":""}]},{"id":"s4-107","number":107,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا سمى الشيطان ﴿قَرِينًا﴾، ولم يقل: صاحبًا؟","answer":"القرين صاحب ملازم يقرن نفسه بالإنسان ويخالطه حتى كأنهما شيء واحد، فهو أخص وأشد اتصالًا من مطلق الصاحب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص155–156، تحت «بديع السجع في فواصل الآي».","url":""}]},{"id":"s4-108","number":108,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا تقدم الإنفاق على الإيمان في آية، وتقدم الإيمان على الإنفاق في الآية التالية؟","answer":"قدم الإيمان في مقام التحريض لأنه الأصل ولا اعتداد بالإنفاق دونه، وقدم الإنفاق في وصف المرائين لمناسبته البخل والأمر به قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص157–158، تحت «نكتة تقديم الإيمان هنا، وتأخيره في الآية السابقة».","url":""}]},{"id":"s4-109","number":109,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ﴾، فجمع بين «مثقال» و«ذرة»؟","answer":"﴿مِثْقَالَ﴾ يحدد وزن الشيء ومقداره، و﴿ذَرَّةٍ﴾ تمثل غاية الصغر؛ فاجتماعهما ينفي أن يقع الظلم في أدنى مقدار يمكن وزنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص166، تحت «لطيفة التصوير البياني في التشبيه التمثيلي».","url":""}]},{"id":"s4-110","number":110,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا﴾، دون أن يقال: من عنده؟","answer":"﴿مِنْ لَدُنْهُ﴾ تدل على قرب الاختصاص وصدور الأجر تفضلًا من خزائن الله مباشرة، فهي أخص من مطلق ﴿من عنده﴾ وأقوى في تشريف العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص167–168، تحت «فائدة التعبير بالظرف ﴿لدن﴾ دون ﴿عند﴾».","url":""}]},{"id":"s4-111","number":111,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا خاطب النبي ﷺ في قوله: ﴿وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا﴾، ولم يقل: وجئنا برسولهم؟","answer":"الخطاب المباشر يستحضر شخص النبي ﷺ في مشهد الشهادة، فيزيد الموقف تهويلًا ويخصه بالتشريف بدل الإخبار عنه بالغائب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص173–174، تحت «بلاغة الالتفات في الآية».","url":""}]},{"id":"s4-112","number":112,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿لَوْ تُسَوَّى بِهِمُ الْأَرْضُ﴾، دون أن يقال: لو يسوَّون بالأرض؟","answer":"الباء تصورهم مادة للتسوية مختلطين بالأرض، لا مجرد أناس تسوى الأرض عليهم؛ لشدة تمنيهم الزوال من هول العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص175–176، تحت «توجيه القراءات في ﴿تسوى﴾».","url":""}]},{"id":"s4-113","number":113,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يَكْتُمُونَ اللَّهَ حَدِيثًا﴾، مع ورود ما يدل على كتمانهم في مواضع أخرى؟","answer":"يقع الكتمان في طور من الموقف، ثم تشهد الجوارح وتظهر الحقائق فلا يملكون كتمان حديث عن الله؛ فتختلف أحوال يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص291–292، تحت «سؤال عن بيان مواطن الاختلاف بين ما يحتمل التعارض في الآيات». يتناول القسم آية النساء:42 صراحة، والوجه الثالث ص292 يبين شهادة الجوارح بعد الكتمان.","url":""}]},{"id":"s4-114","number":114,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى﴾، دون أن يقال: لا تصلوا؟","answer":"النهي عن القرب أبلغ من النهي عن الفعل؛ لأنه يمنع مقدماته والدخول فيه قبل زوال المانع، فيصون حرمة الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص185، تحت «سر النهي عن القرب دون الفعل».","url":""}]},{"id":"s4-115","number":115,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا جعل الغاية: ﴿حَتَّى تَعْلَمُوا مَا تَقُولُونَ﴾، ولم يقل: ما تفعلون؟","answer":"القول أعم من المركب والمفرد، ويشمل المفهوم والهذيان؛ ولأن اختلال العمل يسبق اختلال القول جعل إدراك القول حدًا ظاهرًا لزوال السكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص186–187، تحت «نكتة إيثار لفظ القول على الكلام والفعل».","url":""}]},{"id":"s4-116","number":116,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا استثنى من الجنابة ﴿إِلَّا عَابِرِي سَبِيلٍ﴾؟","answer":"الاستثناء رخصة للجنب في عبور المسجد عند الحاجة من غير مكث، مراعاة للحاجة ودفعًا للحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص187، تحت «دلالة تقديم المستثنى قبل تمام الكلام».","url":""}]},{"id":"s4-117","number":117,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا ختمت آية الطهارة بـ﴿إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا﴾؟","answer":"الفاصلة تقرر حكم الرخصة؛ عفا الله عن إلزام العاجز بالغسل أو الوضوء، وغفر ورخص ويسر، واقتران الوصفين يذكر بأصل كمال الطهارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص190–191، تحت «توجيه فاصلة الآية الكريمة».","url":""}]},{"id":"s4-118","number":118,"surah":4,"verses":[43],"references":[{"surah":4,"verses":[43]},{"surah":5,"verses":[6]}],"verseLabel":"النساء: 43؛ المائدة: 6","question":"ما سرّ التعبير في قوله تعالى في تيمم النساء: ﴿فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ﴾، وزاد في المائدة: ﴿مِنْهُ﴾؟","answer":"آية المائدة فصّلت أحكام الطهارة ابتداءً، فزاد ﴿منه﴾ ليصرح بأن المسح يكون من الصعيد الطيب؛ أما النساء فجاء ذكر التيمم ضمن النهي عن الصلاة حال اختلال الإدراك، فناسب الإيجاز اعتمادًا على دلالة ﴿صعيدًا طيبًا﴾.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص138؛ إسلام ويب، باب النساء: 43","url":""}]},{"id":"s4-119","number":119,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا صور اختيارهم الضلالة بالشراء: ﴿يَشْتَرُونَ الضَّلَالَةَ﴾؟","answer":"صوّر اختيارهم الضلالة شراءً؛ لأنهم بذلوا الهدى الذي عرفوه وأخذوا بدله ما يضرهم، فكانت صفقة خاسرة عن قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص197، تحت «سر استعارة لفظ الاشتراء».","url":""}]},{"id":"s4-120","number":120,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا عُرّف ﴿السبيل﴾ في قوله تعالى: ﴿ويريدون أن تضلوا السبيل﴾؟","answer":"التعريف للعهد؛ فالمراد طريق الحق المعروف البيّن، لا مطلق طريق. وبذلك يصور السياق إرادتهم صرف المخاطبين عن الطريق المستقيم الذي يوصل إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص198، تحت «دلالة (الـ) التعريف في ﴿السبيل﴾».","url":""}]},{"id":"s4-121","number":121,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا صرح باسم الله مرتين: ﴿وَاللَّهُ أَعْلَمُ بِأَعْدَائِكُمْ وَكَفَى بِاللَّهِ وَلِيًّا﴾؟","answer":"تكرار الاسم الجليل يجعل كل كفاية مستقلة: العلم بمكر الأعداء، ثم الولاية، ثم النصرة، وفيه تسلية وتقوية للتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص209، تحت «نكتة إظهار اسم الله الأعظم».","url":""}]},{"id":"s4-122","number":122,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا جمع بين ﴿وَلِيًّا﴾ و﴿نَصِيرًا﴾؟","answer":"اجتمع في الولاية والنصرة كفاية الله لعباده: يتولى أمرهم ويؤيدهم على أعدائهم، فيطمئن المؤمن إلى رعايته ونصره ولا يخشى عداوة من سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص209، تحت عنوان «نكتة إظهار اسم الله الأعظم»","url":""}]},{"id":"s4-123","number":123,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِهِ﴾، دون أن يقال: يغيرون الكلام؟","answer":"التحريف إمالة الكلام عن وجهه لفظًا أو معنى، فالفعل يصور نقل الدلالة من موضعها المقصود لا مجرد الكذب المنفصل عن النص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص214–215، تحت «دلالة معنى التحريف بين الحقيقة والمجاز».","url":""}]},{"id":"s4-124","number":124,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"كيف احتمل قولهم ﴿واسمع غير مسمع﴾ ظاهر التوقير وباطن الإساءة؟","answer":"يمكن أن تُفهم «غير مسمع» على معنى: لا أسمعك الله مكروهًا، فتبدو دعاءً بالخير؛ وتحتمل الدعاء بألّا يسمع، فتكون إساءة. استغلوا احتمال اللفظ لستر الطعن بظاهر الأدب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص217–219، تحت «بديع التوجيه في قوله تعالى: ﴿واسمع غير مسمع وراعنا﴾».","url":""}]},{"id":"s4-125","number":125,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا سمي تحريفهم ﴿لَيًّا بِأَلْسِنَتِهِمْ﴾؟","answer":"اللي يصور فتل اللسان وصرف اللفظ عن ظاهره إلى معنى خبيث، مع إبقاء صورة تسمح لهم بالتورية والبراءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص220–221، تحت «سر إيثار لفظ (اللي) دون غيره».","url":""}]},{"id":"s4-126","number":126,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿آمِنُوا بِمَا نَزَّلْنَا مُصَدِّقًا لِمَا مَعَكُمْ﴾، ولم يسم القرآن والتوراة؟","answer":"المنزل هو القرآن المعروف، و«ما معكم» يستحضر صلتهم بالتوراة ويلزمهم بما في أيديهم، فيقيم التصديق حجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص234–235، تحت «إيثار الاسم الموصول (ما) دون العلم».","url":""}]},{"id":"s4-127","number":127,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا هدد بطمس ﴿وُجُوهًا﴾ منكرة، ولم يقل: وجوهكم؟","answer":"التنكير للتهويل والتكثير، ومعه لطف بعدم مواجهتهم بلفظ «وجوهكم» واستدعاء لهم إلى الإيمان قبل العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص236، تحت «السر في تنكير الوجوه دون وصف».","url":""}]},{"id":"s4-128","number":128,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سر الصورة في قوله: ﴿نَطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَى أَدْبَارِهَا﴾؟","answer":"الصورة تحتمل محو معالم الوجه حتى يصير كالقفا، ورد أصحابه القهقرى إلى الضلالة؛ وفي الحالين وعيد بالانتكاس الحسي والمعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص237–238، تحت «دلالة الفاء بين التسبيب والتعقيب في قوله: ﴿فنردها على أدبارها﴾».","url":""}]},{"id":"s4-129","number":129,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا خيّر الوعيد بين طمس الوجوه وبين اللعن: ﴿أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّا أَصْحَابَ السَّبْتِ﴾؟","answer":"نوعت «أو» التهديد بين الطمس واللعن، وشُبه اللعن بما وقع لأصحاب السبت لتذكيرهم بعقوبة يعرفونها وتشديد الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص240–241، تحت «بلاغة التشبيه المرسل».","url":""}]},{"id":"s4-130","number":130,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ﴾، ثم قال: ﴿وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾؛ فلم يذكر المشيئة مع الشرك؟","answer":"أكد النفي لأن الشرك ناقض لأصل التوحيد الذي تبنى عليه المغفرة، وعلق ما دونه بالمشيئة لأنه لا يهدم أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص244–245، تحت «سر تكرار ذكر الفعل (يغفر)».","url":""}]},{"id":"s4-131","number":131,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يُزَكُّونَ أَنْفُسَهُمْ﴾، دون أن يقال: ألم تسمع؟","answer":"هي رؤية علم وتعجيب تجعل حال المزكين أنفسهم كالمشاهد المحقق، فتكون أبلغ من مجرد سماع خبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص253–254، تحت «دلالة الاستفهام الداخل على حرف النفي».","url":""}]},{"id":"s4-132","number":132,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا قابل تزكيتهم أنفسهم بقوله: ﴿بَلِ اللَّهُ يُزَكِّي مَنْ يَشَاءُ﴾؟","answer":"«بل» تبطل دعواهم وتنقل الحكم إلى الله وحده؛ فالتزكية الحقيقية فضل منه وعلم بالسرائر لا شهادة المرء لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص254–255، تحت «سر الإضراب بعد الاستفهام».","url":""}]},{"id":"s4-133","number":133,"surah":4,"verses":[46],"references":[{"surah":4,"verses":[46]},{"surah":5,"verses":[13,41]}],"verseLabel":"النساء: 46؛ المائدة: 13، 41","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِهِ﴾، وقوله تعالى في المائدة: ﴿مِنْ بَعْدِ مَوَاضِعِهِ﴾؟","answer":"﴿عن مواضعه﴾ أعم في إمالة الكلام عن وجهه بتأويل أو تبديل، أما ﴿من بعد مواضعه﴾ فتبرز أنهم عرفوا مواضعه الثابتة ثم أبطلوا العمل بها، ولا سيما حكم الرجم؛ فكانت أشد في وصف التحريف عن علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص162، تحت «(من بعد مواضعه) و(عن مواضعه)»، في المقارنة بين المائدة: 41 والنساء: 46.","url":""}]},{"id":"s4-134","number":134,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ﴾، واستعمل الإيمان لما هو باطل؟","answer":"سمّي تصديقهم بالجبت والطاغوت إيمانًا على المشاكلة التقديرية؛ إذ كان مقتضى إيتائهم الكتاب أن يؤمنوا بالله، فجاء اللفظ نفسه فيما ناقض ذلك، فكشف شدة المفارقة والتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص261، تحت «سر المشاكلة في الآية».","url":""}]},{"id":"s4-135","number":135,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما دلالة وصفهم الكافرين بقولهم: ﴿هَؤُلَاءِ أَهْدَى مِنَ الَّذِينَ آمَنُوا سَبِيلًا﴾، واختيار لفظ ﴿سَبِيلًا﴾؟","answer":"السبيل هو الطريق الموصل إلى الغاية؛ فادعاؤهم أن عبدة الأوثان أهدى طريقًا من المؤمنين يصور انقلاب موازينهم، إذ سموا طريق الضلال هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص263، تحت «سر مجيء الخبر بصيغة أفعل التفضيل».","url":""}]},{"id":"s4-136","number":136,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ لَهُمْ نَصِيبٌ مِنَ الْمُلْكِ فَإِذًا لَا يُؤْتُونَ النَّاسَ نَقِيرًا﴾، واختار النقير؟","answer":"النقير هو النقرة الدقيقة في ظهر نواة التمر، فضُرب به المثل في غاية القلة؛ أي لو كان لهم شيء من الملك لمنعهم بخلهم أن يعطوا الناس أدنى قدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص278، تحت «بلاغة التعبير بلفظة (النقير) في قوله: ﴿فإذا لا يؤتون الناس نقيرًا﴾».","url":""}]},{"id":"s4-137","number":137,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ يَحْسُدُونَ النَّاسَ﴾، دون أن يقال: يحسدون محمدًا ﷺ؟","answer":"توجه الموسوعة لفظ «الناس» إلى النبي ﷺ وحده على المجاز المرسل بعلاقة الكلية؛ ففي إطلاق اسم الناس عليه تفخيم لشأنه، كأن ما فيهم من الكمال اجتمع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص281، تحت «فائدة المجاز المرسل في التعبير بـ﴿الناس﴾ عن النبي ﷺ».","url":""}]},{"id":"s4-138","number":138,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"لماذا قابل حسدهم بقوله: ﴿فَقَدْ آتَيْنَا آلَ إِبْرَاهِيمَ الْكِتَابَ وَالْحِكْمَةَ وَآتَيْنَاهُمْ مُلْكًا عَظِيمًا﴾؟","answer":"أُلزموا بما يقرون به؛ فقد أعطى الله آل إبراهيم النبوة والحكمة والملك، ومحمد ﷺ من آله، فلا وجه لإنكار الفضل عليه حسدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص282، تحت «مغزى الإطناب بعد الإيجاز بطريق الالتفات».","url":""}]},{"id":"s4-139","number":139,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا الْعَذَابَ﴾؟","answer":"التبديل عند كل نضج يصور دوام الإحساس وتجدد الألم بلا انقطاع، و«ليذوقوا» تصرح بأن بقاء ذوق العذاب هو علة التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص293–294، تحت «براعة التصوير بحركية مشهدية، تتجلى في تبديل الجلود الناضجة باستمرار».","url":""}]},{"id":"s4-140","number":140,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"لماذا وُصفت الأزواج في قوله تعالى: ﴿أزواج مطهرة﴾ بالمفرد، ولم يقل: مطهَّرات؟","answer":"يشير الإفراد إلى شدة توافقهن في الطهر، حتى كأنهن ذات واحدة؛ فالوصف يصور اشتراكهن جميعًا في طهارة دائمة لا تتخلف عن واحدة منهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص301، تحت «سر العدول عن الجمع إلى الإفراد، وغرض تقديم المسند».","url":""}]},{"id":"s4-141","number":141,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا﴾، فكرر مادة الظل؟","answer":"﴿ظِلًّا﴾ هو النعيم المظلل، و﴿ظَلِيلًا﴾ تؤكد كثافته ودوامه وكمال الإظلال؛ فاشتقاق الصفة من الموصوف للمبالغة، لا تكرار خالٍ من المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص302، تحت «بديع الجناس بالصفة المشتقة».","url":""}]},{"id":"s4-142","number":142,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"لماذا كرر ﴿أَطِيعُوا﴾ مع الله والرسول، ولم يكرره مع ﴿أُولِي الْأَمْرِ﴾؟","answer":"أولو الأمر أصحاب الولاية العلمية أو التنفيذية الذين يقوم بهم نظام الجماعة؛ وطاعتهم تابعة لطاعة الله والرسول، ولذلك لم يُعَد الفعل معها استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص316–317، تحت «سر إعادة العامل مع ﴿الرسول﴾ لا مع غيره، في قوله: ﴿وأطيعوا الرسول وأولي الأمر﴾».","url":""}]},{"id":"s4-143","number":143,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ﴾، فنكر «شيئًا»؟","answer":"نُكرت ﴿شَيْءٍ﴾ في سياق الشرط لتعم أي أمر يقع فيه التنازع، صغيرًا أو كبيرًا؛ فلا يخرج شيء من وجوب رده إلى الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص318، تحت «سر تنكير لفظ ﴿شيء﴾ المتنازع عليه، في قوله: ﴿فإن تنازعتم في شيء﴾».","url":""}]},{"id":"s4-144","number":144,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ﴾، وكيف يكون الرد إلى الله؟","answer":"الرد إلى الله يكون بالرجوع إلى كتابه، والرد إلى الرسول بالرجوع إليه في حياته وإلى سنته بعد وفاته. واستعير الرد للتحاكم؛ لأن الفصل في النزاع يُرجع فيه إلى حكم الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص318–319، تحت «سر استعارة لفظ (الرد) إلى معنى (التحاكم)».","url":""}]},{"id":"s4-145","number":145,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ تقديم ﴿خَيْرٌ﴾ على ﴿وَأَحْسَنُ تَأْوِيلًا﴾؟","answer":"«خير» يثبت أصل المصلحة في الرد إلى الوحي، ثم «أحسن تأويلًا» يبين حسن العاقبة؛ فبدأ بالحكم ثم مآله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص320–321، تحت «دلالة تقديم الخيرية على الحسن، في قوله: ﴿ذلك خير وأحسن تأويلًا﴾».","url":""}]},{"id":"s4-146","number":146,"surah":4,"verses":[55],"references":[{"surah":4,"verses":[55]},{"surah":64,"verses":[2]}],"verseLabel":"النساء: 55؛ التغابن: 2","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿فَمِنْهُمْ مَنْ آمَنَ بِهِ وَمِنْهُمْ مَنْ صَدَّ عَنْهُ﴾ فقدم المؤمن، بينما قال في التغابن: ﴿فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾ فقدم الكافر؟","answer":"سياق النساء في ذرية إبراهيم وما آتاهم الله، فناسب البدء بمن آمن بذلك الكتاب والنبي؛ أما التغابن فمقام تعداد أحوال عموم البشر والتنبيه على جحود الخلق، فبدأ بالكافر الذي يعالجه السياق ثم ثنّى بالمؤمن.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص140؛ إسلام ويب، باب النساء: 55","url":""}]},{"id":"s4-147","number":147,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿يَزْعُمُونَ أَنَّهُمْ آمَنُوا﴾، دون أن يقال: يقولون؟","answer":"الزعم يطلق على دعوى لا تستند إلى علم محقق، ويغلب استعماله فيما يشك فيه أو يكذب؛ فوصف دعواهم الإيمان بهذا اللفظ يكشف ضعفها وكذبها، كما يفضحه طلب التحاكم إلى الطاغوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص324، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s4-148","number":148,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما دلالة تعقيب قوله تعالى: ﴿يريدون أن يتحاكموا إلى الطاغوت﴾ بقوله: ﴿وقد أمروا أن يكفروا به﴾؟","answer":"جاءت جملة ﴿وقد أمروا أن يكفروا به﴾ حالًا تقبح إرادتهم التحاكم إلى الطاغوت؛ فهم يريدون الرجوع إلى من أُمروا برفضه، فظهر تناقض دعواهم الإيمان مع قصدهم وعملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص330–331، تحت «نكتة التقييد بالجملة الحالية في قوله: ﴿وقد أمروا﴾».","url":""}]},{"id":"s4-149","number":149,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"لماذا أكد إضلال الشيطان بقوله: ﴿أَنْ يُضِلَّهُمْ ضَلَالًا بَعِيدًا﴾؟","answer":"المصدر يؤكد الإضلال، و«بعيدًا» يصور إمعانهم عن الحق وصعوبة رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص332، تحت «سر الاستعارة في وصف الضلال بالبعد في قوله تعالى: ﴿أن يضلهم ضلالًا بعيدًا﴾».","url":""}]},{"id":"s4-150","number":150,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿رَأَيْتَ الْمُنَافِقِينَ يَصُدُّونَ عَنْكَ صُدُودًا﴾، فأعاد المصدر وقال «عنك»؟","answer":"المصدر بعد الفعل يبالغ في وصف الإعراض ويثبته، فكأن الصد صار سمةً كاملة لا حركة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص340–341، تحت «دلالة التأكيد بالمصدر المنكر في قوله تعالى: ﴿يصدون عنك صدودًا﴾».","url":""}]},{"id":"s4-151","number":151,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقُلْ لَهُمْ فِي أَنْفُسِهِمْ قَوْلًا بَلِيغًا﴾؛ كيف يكون القول في أنفسهم؟","answer":"﴿فِي أَنْفُسِهِمْ﴾ أي قولًا يبلغ أعماقهم ويؤثر فيها، أو قل لهم خاليًا بهم ما يردعهم؛ و﴿بَلِيغًا﴾ هو الذي يصل إلى موضع التأثير ويوافق حال المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص352–354، تحت «أسرار حروف الجر الواردة في قوله تعالى: ﴿أولئك الذين يعلم الله ما في قلوبهم فأعرض عنهم وعظهم وقل لهم في أنفسهم قولًا بليغًا﴾».","url":""}]},{"id":"s4-152","number":152,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ﴾، فاختار الإذن دون الأمر؟","answer":"الإذن هنا بمعنى التمكين والإرادة الشرعية التي بها تجب طاعة الرسول؛ فطاعته ليست سلطة مستقلة عن الله، بل طاعة مأذون بها من مرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص358–359، تحت «سر اختيار لفظة الإذن ونكتة الالتفات في قوله تعالى: ﴿وما أرسلنا من رسول إلا ليطاع بإذن الله﴾».","url":""}]},{"id":"s4-153","number":153,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"لماذا جاء القسم على هذه الصورة: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ﴾؟","answer":"قُدم النفي اهتمامًا به ثم أُكد بالقسم، وجيء بعد القسم بجوابه المنفي: ﴿لا يؤمنون﴾. وإضافة الرب إلى ضمير النبي ﷺ تشريف له وتأكيد وجوب التحاكم إليه والرضا بحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص365–366، تحت «سر تقديم النفي على القسم في قوله تعالى: ﴿فلا وربك﴾».","url":""}]},{"id":"s4-154","number":154,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"لماذا جعل تمام الإيمان في ثلاث مراحل: أن يحكموك، وألا يجدوا حرجًا، وأن يسلموا تسليمًا؟","answer":"بدأ بالتحاكم الظاهر إلى الرسول، ثم نفى الحرج الباطن من حكمه، ثم أثبت التسليم العملي التام؛ فاستوعب قبول المرجع والقلب والتنفيذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص367–369، تحت «دلالة حرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم لا يجدوا في أنفسهم حرجًا مما قضيت﴾».","url":""}]},{"id":"s4-155","number":155,"surah":4,"verses":[66,67,68,69,70],"references":[{"surah":4,"verses":[66,67,68,69,70]}],"verseLabel":"النساء: 66–70","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ لَدُنَّا أَجْرًا عَظِيمًا﴾، دون أن يقال: من عندنا؟","answer":"﴿مِنْ لَدُنَّا﴾ أخص من ﴿من عندنا﴾، وتوحي بقرب العطاء واختصاصه بالله؛ فناسبت الأجر العظيم الذي يتفضل به على المطيعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص384، تحت «نكتة لدنية الأجر».","url":""}]},{"id":"s4-156","number":156,"surah":4,"verses":[66,67,68,69,70],"references":[{"surah":4,"verses":[66,67,68,69,70]}],"verseLabel":"النساء: 66–70","question":"لماذا رتبت الأصناف هكذا: النبيون، ثم الصديقون، ثم الشهداء، ثم الصالحون؟","answer":"الترتيب من أعلى مراتب الاصطفاء والقدوة إلى من كمل تصديقه، ثم من شهد للحق بنفسه، ثم عموم الصالحين؛ وهو ترتيب منازل صحبة لا انتقاص لمن تأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص401، تحت «وجه ترتيب منازل الممدوحين».","url":""}]},{"id":"s4-157","number":157,"surah":4,"verses":[66,67,68,69,70],"references":[{"surah":4,"verses":[66,67,68,69,70]}],"verseLabel":"النساء: 66–70","question":"ما سرّ التعبير في قوله تعالى عن جماعة الأصناف: ﴿وَحَسُنَ أُولَئِكَ رَفِيقًا﴾ بالإفراد؟","answer":"﴿رَفِيقًا﴾ مفرد لأنه اسم جنس يشمل الرفقاء المذكورين، أو لأنه حال يلحظ كل واحد منهم رفيقًا؛ فالإفراد يجمع الأصناف في حسن الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص399–400، تحت «سر توحيد التمييز (الرفيق)».","url":""}]},{"id":"s4-158","number":158,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"ما سرّ التعبير في قوله تعالى: ﴿خُذُوا حِذْرَكُمْ﴾؛ وكيف يؤخذ الحذر؟","answer":"صوّر الحذر كأنه سلاح أو متاع يؤخذ ويُحمل؛ ليجعل الاستعداد أمرًا عمليًا ملازمًا، لا مجرد شعور بالخوف في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص410–411، تحت «بلاغة المجاز والاستعارة في التعبير بالأخذ».","url":""}]},{"id":"s4-159","number":159,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا قابل بين ﴿انْفِرُوا ثُبَاتٍ﴾ و﴿انْفِرُوا جَمِيعًا﴾، فذكر حالتي التفرق والاجتماع؟","answer":"﴿ثُبَاتٍ﴾ جماعات متفرقة تتتابع بحسب الحاجة، و﴿جَمِيعًا﴾ جيشًا مجتمعًا؛ فشمل الأمر خطتي الحركة العسكرية تبعًا للمصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص412، تحت «حكمة الأمر بالخروج للجهاد جماعات وجمعًا».","url":""}]},{"id":"s4-160","number":160,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا اعترض بقوله: ﴿كَأَنْ لَمْ تَكُنْ بَيْنَكُمْ وَبَيْنَهُ مَوَدَّةٌ﴾؟","answer":"الجملة المعترضة تكشف تناقض المنافق: يتمنى الغنيمة كأن لا رابطة مودة جمعته بالمؤمنين تلزمه بنصرتهم؛ فلا يرى العلاقة إلا من خلال نصيبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص426–427، تحت «براعة دلالات الاعتراض بجملة التشبيه».","url":""}]},{"id":"s4-161","number":161,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا سمى مبادلة الدنيا بالآخرة شراء: ﴿يَشْرُونَ الْحَيَاةَ الدُّنْيَا بِالْآخِرَةِ﴾؟","answer":"﴿يَشْرُونَ﴾ هنا بمعنى يبيعون؛ فصوّر بذل الحياة الدنيا في سبيل الآخرة صفقة واعية، ثمنها الفاني وعوضها الثواب الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص435، تحت «براعة التعبير بلفظ الشراء على طريق الأضداد».","url":""}]},{"id":"s4-162","number":162,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"ما سرّ تقديم القتل على الغلبة: ﴿فَيُقْتَلْ أَوْ يَغْلِبْ﴾؟","answer":"قدّم القتل، وهو ما تخشاه النفوس، ليقرر من أول الأمر أنه ليس خسارة في سبيل الله بل أحد طريقَي الأجر؛ ثم عطف الغلبة، فكلا المصيرين موعود بالأجر العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص435، تحت «نكتة تقديم القتل على الغلبة».","url":""}]},{"id":"s4-163","number":163,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ هَذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا﴾، دون أن يقال: القرية الظالمة؟","answer":"وصف أهل القرية بالظلم لا القرية نفسها؛ لأن الظلم فعل السكان لا المكان، وفي التصريح بـ﴿أَهْلُهَا﴾ تعيين للمسؤول عن اضطهاد المستضعفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص441–442، تحت «الموصولية والوصف، وأثرهما في توضيح المعنى».","url":""}]},{"id":"s4-164","number":164,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا كرر دعاءهم: ﴿وَاجْعَلْ لَنَا مِنْ لَدُنْكَ وَلِيًّا وَاجْعَلْ لَنَا مِنْ لَدُنْكَ نَصِيرًا﴾؟","answer":"تكرير ﴿واجعل﴾ وما تعلق به مبالغة في التضرع والابتهال، وإظهار لشدة رغبتهم في أن يمنحهم الله الولاية والنصرة. فتكرر الدعاء لإلحاحهم في الطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص442–443، تحت عنوان «أثر التأخير والتكرير في جلاء المعنى وبيانه في هذه الآية»","url":""}]},{"id":"s4-165","number":165,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا قابل بين القتال ﴿فِي سَبِيلِ اللَّهِ﴾ والقتال ﴿فِي سَبِيلِ الطَّاغُوتِ﴾؟","answer":"إضافة السبيل إلى الله تجعل قتال المؤمنين خالصًا لنصرة الحق، وإضافته إلى الطاغوت تكشف أن قتال الكافرين في خدمة الباطل المتجاوز للحد؛ فتقابلت الغايتان قبل تقابل الجيوش.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص446، تحت «أثر العطف في إثراء المعنى، في قوله: ﴿والذين كفروا يقاتلون في سبيل الطاغوت﴾».","url":""}]},{"id":"s4-166","number":166,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا ختم بقوله: ﴿إِنَّ كَيْدَ الشَّيْطَانِ كَانَ ضَعِيفًا﴾، مع ما يبدو من قوة أثره؟","answer":"ضعف كيد الشيطان هنا في مقابلة نصر الله وتأييده؛ فأولياء الشيطان لا يثبتون أمام أولياء الله المؤيدين به. وجاءت الجملة تعليلًا للأمر بقتالهم وتطمينًا للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص447، تحت «التفريع بالفاء وأثره في جلاء المعنى وترابط السياق».","url":""}]},{"id":"s4-167","number":167,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"لماذا كنى عن ترك القتال بقوله: ﴿كُفُّوا أَيْدِيَكُمْ﴾؟","answer":"اليد آلة البطش والقتال، فكنى بكفها عن منع القتال كله؛ والصورة تجعل الأيدي متهيئة للحركة ثم مأمورة بالانقباض حتى يأتي الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص452–453، تحت «الاستفهام التعجبي، وأثره في توضيح المعنى».","url":""}]},{"id":"s4-168","number":168,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللَّهِ أَوْ أَشَدَّ خَشْيَةً﴾؟","answer":"شبه خشيتهم من الناس بخشية الله، ثم ترقى إلى ﴿أَوْ أَشَدَّ خَشْيَةً﴾؛ ليكشف اضطراب ميزانهم حين عظم في قلوبهم ضرر الناس حتى ساوى أو تجاوز ما يجب لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص454–455، تحت «معاني (أو) العاطفة، وأثرها في دلالة هذه الآية».","url":""}]},{"id":"s4-169","number":169,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"لماذا قُيّد خير الآخرة بقوله ﴿لمن اتقى﴾ في مقابل ﴿متاع الدنيا قليل﴾؟","answer":"لحث المخاطبين على اتقاء العصيان والوفاء بالتكليف؛ فالتعلق بتأخير القتال لاستبقاء الحياة لا يوازي حظ الآخرة، وإنما ينال خيرها من اتقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص456، تحت «أسلوب التوبيخ، والعطف، وأثرهما في توضيح المعنى».","url":""}]},{"id":"s4-170","number":170,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿أَيْنَمَا تَكُونُوا يُدْرِكْكُمُ الْمَوْتُ﴾، فصور الموت كطالب يدركهم؟","answer":"أُسند الإدراك إلى الموت فصُوّر طالبًا يلحق الهارب أينما كان؛ وفي ﴿أَيْنَمَا﴾ استغراق لكل مكان، فلا تنجي منه إقامة ولا فرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص463–464، تحت «أسلوب الشرط، وأهميته في قوله تعالى: ﴿أينما تكونوا يدرككم الموت﴾».","url":""}]},{"id":"s4-171","number":171,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ كُنْتُمْ فِي بُرُوجٍ مُشَيَّدَةٍ﴾؟","answer":"يصور التعبير بلوغ التحصن غايته في القصور المنيعة والمنازل الرفيعة، ثم يقرر أن ذلك كله لا يمنع وصول الموت إذا جاء الأجل؛ فلا تنفع معه قوة البناء وارتفاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص462، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s4-172","number":172,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما دلالة نسبتهم الحسنة إلى الله والسيئة إلى الرسول في قولهم: ﴿هَذِهِ مِنْ عِنْدِ اللَّهِ﴾ و﴿هَذِهِ مِنْ عِنْدِكَ﴾؟","answer":"هذه مقالة المنافقين: ينسبون النعمة إلى الله، فإذا أصابتهم شدة تشاءموا بالرسول ﷺ وحملوه تبعتها؛ فكشف النقل اضطرابهم في فهم القدر وتحاملهم على الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص464–466، تحت «دلالة الابتداء، وحكاية كلام الغائب عن المخاطب للمخاطب».","url":""}]},{"id":"s4-173","number":173,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"كيف يجمع القارئ بين ﴿قُلْ كُلٌّ مِنْ عِنْدِ اللَّهِ﴾ ثم ﴿مَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ﴾؟","answer":"﴿كُلٌّ مِنْ عِنْدِ اللَّهِ﴾ من جهة الخلق والتقدير ووقوع الأشياء بمشيئته، و﴿فَمِنْ نَفْسِكَ﴾ من جهة السبب والكسب؛ فالعبد يجلب السيئة بذنبه، والله خالق الأسباب والنتائج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص469، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s4-174","number":174,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا﴾، واختار «حفيظًا» دون «حافظًا»؟","answer":"﴿حَفِيظًا﴾ صيغة تدل على المبالغة والدوام في الحفظ والمراقبة؛ فنفت عن الرسول ﷺ مسؤولية إجبارهم وإحصاء أعمالهم، إذ وظيفته البلاغ وهم محاسبون عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص480–481، تحت «دلالة التعبير بـ﴿حفيظًا﴾ دون حافظًا».","url":""}]},{"id":"s4-175","number":175,"surah":4,"verses":[80],"references":[{"surah":4,"verses":[80]}],"verseLabel":"النساء: 80","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا﴾، وقوله تعالى في الإسراء: ﴿وَمَا أَرْسَلْنَاكَ عَلَيْهِمْ وَكِيلًا﴾؟","answer":"الحفيظ يراقب الأعمال ويحصيها ليجبر الناس على الطاعة، وهذه ليست وظيفة الرسول؛ والوكيل يتولى أمورهم استقلالًا، فنُفي كل وصف في المقام الذي يناسبه.","sources":[{"label":"فاضل السامرائي، *لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 48657","url":""}]},{"id":"s4-176","number":176,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ اقتصار المنافقين على كلمة ﴿طَاعَةٌ﴾، دون أن يقولوا: أطعنا؟","answer":"الاسم المفرد ﴿طَاعَةٌ﴾ دعوى مقتضبة تحتمل معنى: أمرنا طاعة؛ فيظهرون بها موافقة ثابتة من غير أن يسندوا إلى أنفسهم فعلًا تحقق، بخلاف ﴿أطعنا﴾ الذي يلتزم وقوع الطاعة منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص485–486، تحت «دلالة التعبير بلفظ ﴿طاعة﴾ في قوله تعالى: ﴿ويقولون طاعة﴾».","url":""}]},{"id":"s4-177","number":177,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا اختير فعل ﴿بَيَّتَ﴾ لما دبروه ليلًا؟","answer":"التبييت تدبير الأمر ليلًا في خفاء، ثم استعمل لكل ما يضمر ويقرر بعيدًا عن الناس؛ فناسب انقلابهم بعد خروجهم من مجلس الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص487، تحت «سر التعبير بلفظ ﴿بيت﴾ دون غيره من الألفاظ».","url":""}]},{"id":"s4-178","number":178,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ﴾، دون أن يقال: يعلم؟","answer":"الكتابة تزيد على مجرد العلم معنى الإثبات والحفظ للمحاسبة؛ فما يدبرونه ليلًا لا يضيع، بل يسجل عليهم ويواجهون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص489، تحت «الكناية في جملة الحال: ﴿والله يكتب ما يبيتون﴾».","url":""}]},{"id":"s4-179","number":179,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا وصف الاختلاف المفترض في القرآن بأنه ﴿اخْتِلَافًا كَثِيرًا﴾، ولم يقل: اختلافًا فقط؟","answer":"قيد الاختلاف بـ﴿كَثِيرًا﴾ لأن كتابًا طويلًا متعدد الموضوعات لو كان من صنع البشر لظهر فيه تناقض واضطراب كثيران؛ وانتفاء ذلك شاهد على مصدره، ولا يعني إثبات تناقض قليل فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص497–498، تحت «معنى وصف الاختلاف بالكثير دون القليل».","url":""}]},{"id":"s4-180","number":180,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا جَاءَهُمْ أَمْرٌ مِنَ الْأَمْنِ أَوِ الْخَوْفِ أَذَاعُوا بِهِ﴾، واختار «جاءهم»؟","answer":"اختير «جاءهم» لإفادة تحقق ورود الخبر ووثوقه في هذا السياق، لا مجرد سماع أراجيف. والمذموم أنهم أذاعوا خبر الأمن أو الخوف دون مراعاة ما يترتب على إشاعته من أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص502، تحت «فائدة اختيار ﴿جاءهم﴾ دون مرادفاته في الاستعمال».","url":""}]},{"id":"s4-181","number":181,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا صرح بالرسول في قوله: ﴿وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ﴾، ولم يضمره؟","answer":"إظهار الرسول يعظم المرجعية ويجعل الرسالة علة الرد إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص503، تحت «نكتة إظهار لفظ الرسول دون إضماره».","url":""}]},{"id":"s4-182","number":182,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ﴾، واختار صورة الاستنباط؟","answer":"الاستنباط تصوير لاستخراج المعنى الخفي كما يستخرج الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص504–505، تحت «توجيه الاستعارة في قوله: ﴿يستنبطونه﴾».","url":""}]},{"id":"s4-183","number":183,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا استثنى ﴿إِلَّا قَلِيلًا﴾ في قوله: ﴿لَاتَّبَعْتُمُ الشَّيْطَانَ إِلَّا قَلِيلًا﴾؛ وإلى ماذا يعود الاستثناء؟","answer":"تذكر الموسوعة وجهين: أن يكون الاستثناء من عموم أحوال الاتباع، أي لاتبعتم الشيطان إلا اتباعًا قليلًا تُدرك وجوهه ببداهة العقول؛ أو من ضمير المخاطبين، أي إلا قليلًا منهم لا يبلغون تلك المرتبة من اتباع آراء المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص505–506، تحت «بلاغة الالتفات في الآية».","url":""}]},{"id":"s4-184","number":184,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا أفرد النبي ﷺ بالتكليف: ﴿فَقَاتِلْ فِي سَبِيلِ اللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ﴾؟","answer":"إفراد النبي يقرر ثباته ومسؤوليته ولو تخلف الناس مع تحريضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص512، تحت «بلاغة جملة القصر في قوله تعالى: ﴿لا تكلف إلا نفسك﴾».","url":""}]},{"id":"s4-185","number":185,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿عَسَى اللَّهُ أَنْ يَكُفَّ بَأْسَ الَّذِينَ كَفَرُوا﴾، دون أن يقال: أن ينصركم عليهم؟","answer":"كف البأس أعم من النصر وقد يقع بالرعب أو التفرق ونحوهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص514، تحت «سر التعبير بالكف دون النصر».","url":""}]},{"id":"s4-186","number":186,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى في الشفاعة الحسنة: ﴿نَصِيبٌ مِنْهَا﴾، وفي السيئة: ﴿كِفْلٌ مِنْهَا﴾؟","answer":"النصيب حصة من الخير تنمو لصاحب الشفاعة الحسنة، أما الكفل فهو مقدار يحمل تبعته كأنه ثقل على صاحبه؛ فناسب كل لفظ أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص518–520، تحت «سر التعبير عن جزاء الشفاعة الحسنة بالنصيب والسيئة بالكفل».","url":""}]},{"id":"s4-187","number":187,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ تقديم رد التحية بأحسن على رد مثلها: ﴿فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا﴾؟","answer":"زاد الإحسان في الرد ليصنع السلام مودةً متنامية، وأباح المماثلة حدًا أدنى للعدل؛ فجمع الفضل والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص525، تحت «فائدة تقديم ﴿فحيوا بأحسن منها﴾ على ﴿أو ردوها﴾».","url":""}]},{"id":"s4-188","number":188,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا انتقل من التحية إلى قوله: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَى يَوْمِ الْقِيَامَةِ﴾؟","answer":"الانتقال يربط التحية والعمل برقابة التوحيد والجزاء يوم الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص527، تحت «مناسبة الآية لما قبلها».","url":""}]},{"id":"s4-189","number":189,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أصدق من الله حديثًا﴾؟","answer":"الاستفهام يفيد النفي: فلا أحد أصدق من الله، ولا مساويًا له في الصدق. ويشمل ذلك خبره عن جمع الخلق يوم القيامة وسائر أخباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص536، تحت عنوان «بلاغة الاستفهام في قوله تعالى: ﴿ومن أصدق من الله حديثًا﴾»","url":""}]},{"id":"s4-190","number":190,"surah":4,"verses":[87,122],"references":[{"surah":4,"verses":[87,122]}],"verseLabel":"النساء: 87؛ النساء: 122","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آية الجمع: ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ حَدِيثًا﴾، وقوله تعالى في آية الوعد: ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلًا﴾؟","answer":"جاءت ﴿حديثًا﴾ بعد الإخبار بوحدانية الله وجمع الخلق يوم القيامة للحساب، فناسب الحديث مقام الإخبار. وجاءت ﴿قيلًا﴾ بعد الوعد بإدخال المؤمنين الجنات؛ والقيل بمعنى القول يناسب الوعد السابق. فاختير لكل موضع اللفظ الملائم لسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص539، تحت عنوان «توجيه المتشابه اللفظي بين قوله تعالى: ﴿ومن أصدق من الله حديثًا﴾ وقوله سبحانه: ﴿ومن أصدق من الله قيلًا﴾»","url":""}]}]);
